    'On the left you pick an element or a whole ready-made section. Click to insert it after the selected element, drag it anywhere on the page. The Structure tab shows the page as a tree.' => 'Vlevo vyberete prvek nebo celou hotovou sekci. Klepnutím ho vložíte za vybraný prvek, přetažením kamkoli na stránku. Záložka Struktura ukáže stavbu stránky jako strom.',
    'The page as visitors will see it' => 'Stránka, jak ji uvidí návštěvník',
    'Click to select an element, double-click to edit text. At the top you switch the preview to tablet and mobile – the style then changes only for that width.' => 'Klepnutím prvek vyberete, dvojklikem upravíte text. Nahoře přepnete náhled pro tablet a mobil – styl se pak mění jen pro danou šířku.',
    'Content, style and advanced' => 'Obsah, styl a pokročilé',
    'On the right you change the text, links, colours, spacing and behaviour of the selected element. Take colours and sizes from the list – they keep the website consistent.' => 'Vpravo měníte text, odkazy, barvy, rozestupy i chování vybraného prvku. Barvy a velikosti berte z nabídky – drží jednotný vzhled webu.',
    'Saving and publishing' => 'Ukládání a publikování',
    'Changes save automatically as a draft. Visitors see them only after Publish – before that we warn you about missing links, descriptions and low contrast.' => 'Změny se ukládají samy jako koncept. Návštěvníci je uvidí až po Publikovat – předtím vás upozorníme na chybějící odkazy, popisky a slabý kontrast.',
    'Skip' => 'Přeskočit',
    'Done' => 'Hotovo',
    'Style copied.' => 'Styl zkopírován.',
    'Copy style' => 'Kopírovat styl',
    'Paste style' => 'Vložit styl',
    'Display conditions' => 'Podmínky zobrazení',
    'visitors only (not signed in)' => 'jen návštěvníkům (nepřihlášeným)',
    'only people signed in to the administration' => 'jen přihlášeným do administrace',
    'Show from' => 'Zobrazit od',
    'Show until (inclusive)' => 'Zobrazit do (včetně)',
    'On the canvas the element is always visible. On the website it appears only when the conditions are met – for example a promotional banner for a week.' => 'Na plátně je prvek vidět vždy. Na webu se ukáže jen při splnění podmínek – třeba akční banner na týden.',
    'Counter' => 'Počítadlo',
    'Progress bars' => 'Ukazatele průběhu',
    'Countdown' => 'Odpočet',
    'Back-to-top button' => 'Tlačítko nahoru',
    'A big number with a label that counts up when shown (years of experience, customers, projects).' => 'Velké číslo s popiskem, které se při zobrazení napočítá (roky praxe, zákazníci, projekty).',
    'Bars with percentages – goal progress, share, skill level.' => 'Pruhy s procenty – plnění cíle, podíl, úroveň dovedností.',
    'Stars with a score and number of reviews (e.g. from Google).' => 'Hvězdičky s hodnotou a počtem recenzí (např. z Google).',
    'Time remaining until a date – an event, an opening, a registration deadline.' => 'Zbývající čas do data – akce, otevření provozovny, uzávěrka přihlášek.',
    'Icons linking to the company profiles (addresses from Settings).' => 'Ikony s odkazy na profily firmy (adresy z Nastavení).',
    'A website search field – for the header, the 404 page or a listing.' => 'Pole pro hledání na webu – do záhlaví, na stránku 404 nebo k výpisu.',
    'An e-mail field with subscription confirmation – you will find the addresses under Subscribers in the administration.' => 'Pole pro e-mail s potvrzením odběru – adresy najdete v administraci v Odběratelích.',
    'A floating arrow back to the top of the page – put it in the footer.' => 'Plovoucí šipka zpět na začátek stránky – vložte ji do patičky.',
    'Background video (MP4 or WebM from Media, no sound)' => 'Video na pozadí (MP4 nebo WebM z Médií, bez zvuku)',
    'Poster (image before playing)' => 'Plakát (obrázek před spuštěním)',
