    'Text below the field' => 'Text pod polem',
    'Submenu as a wide panel (mega menu)' => 'Podmenu jako široký panel (mega menu)',
    'Background image on scroll' => 'Obrázek pozadí při posunu',
    'stays fixed (parallax)' => 'stojí (paralaxa)',
    'scrolls with content' => 'posouvá se s obsahem',
    'The Newsletter sign-up element in the builder: visitors enter an e-mail and confirm it by a link (double opt-in). The site sends confirmed subscribers to your mailing service (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), or you export them to CSV.' => 'Prvek Odběr novinek v builderu: návštěvník zadá e-mail a potvrdí ho odkazem (double opt-in). Potvrzené odběratele web pošle do vaší mailingové služby (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), nebo je vyexportujete do CSV.',
    'Subscribers' => 'Odběratelé',
    'The subscriber has been deleted.' => 'Odběratel byl smazán.',
    'Subscribed' => 'Přihlášen',
    'Confirmed' => 'Potvrzeno',
    'Unsubscribe link' => 'Odkaz na odhlášení',
    'Addresses from the Newsletter sign-up element. Only people who confirmed by the link in the e-mail count as subscribers. Send with your own tool – the export includes the unsubscribe link.' => 'Adresy z prvku Odběr novinek. Za odběratele se počítá, kdo přihlášení potvrdil odkazem v e-mailu. Rozesílejte svým nástrojem – export obsahuje i odkaz na odhlášení.',
    'Search e-mail' => 'Hledat e-mail',
    'Export confirmed (CSV)' => 'Export potvrzených (CSV)',
    'No subscribers yet.' => 'Zatím žádní odběratelé.',
    'Nothing found.' => 'Nic nenalezeno.',
    'Put the Newsletter sign-up element on the website – for example in the footer.' => 'Vložte na web prvek Odběr novinek – třeba do patičky.',
    'confirmed' => 'potvrzený',
    'awaiting confirmation' => 'čeká na potvrzení',
    'Remove the address from the subscriber list?' => 'Smazat adresu ze seznamu odběratelů?',
    'Only an editor or administrator can publish. Your changes stay saved as a draft.' => 'Publikovat smí jen editor nebo správce. Změny zůstávají uložené jako koncept.',
    'Only an administrator edits a shared class – a change applies to the whole website at once. Set the look of a single element in its style.' => 'Sdílenou třídu upravuje jen správce – změna se hned projeví na celém webu. Vzhled jednoho prvku nastavíte v jeho stylu.',
    'Only an editor or administrator edits, publishes and deletes published pages. You can prepare a new hidden page.' => 'Zveřejněné stránky upravuje, zveřejňuje a maže jen editor nebo správce. Můžete připravit novou skrytou stránku.',
    'This news item is published – only an editor or administrator can save changes to it. Ask them to edit it.' => 'Novinka je vydaná – změny v ní uloží jen editor nebo správce. Požádejte je o úpravu.',
    'The website requires two-step sign-in – you can create a token once you turn it on.' => 'Web vyžaduje dvoufázové přihlášení – token vytvoříte, až si ho zapnete.',
    'These fields have an invalid format and were not saved: %s. Please correct them (they are highlighted); the other settings are saved.' => 'Tato pole nemají platný tvar a neuložila se: %s. Opravte je prosím (jsou zvýrazněná), ostatní nastavení je uložené.',
    'Enquiries older than the given number of months will be permanently deleted right away – including attachments. Save anyway?' => 'Poptávky starší než zadaný počet měsíců se hned natrvalo smažou – i s přílohami. Opravdu uložit?',
    'The database is back in its state before the restore.' => 'Databáze je zpět ve stavu před obnovou.',
    'The state before the restore is in backup %s – please restore it.' => 'Stav před obnovou je v záloze %s – obnovte ji prosím.',
    'The backup is incomplete or damaged (the end of the file is missing) – the restore was stopped.' => 'Záloha je neúplná nebo poškozená (chybí konec souboru) – obnova byla zastavena.',
    'The website files have been returned to their state before the update.' => 'Soubory webu jsou vrácené do stavu před aktualizací.',
    'The server cannot use encrypted FTP (FTPS). Send backups to S3 storage, or download them manually.' => 'Server neumí šifrované FTP (FTPS). Zálohu posílejte do úložiště S3, nebo si ji stahujte ručně.',
    'to an FTP server with FTPS encryption (another host, home NAS)' => 'na FTP server se šifrováním FTPS (jiný hosting, domácí NAS)',
    'The builder needs a larger screen.' => 'Builder potřebuje větší obrazovku.',
    'Build pages on a computer or tablet. On a phone, edit texts with the “Edit here” button right on the website.' => 'Stránky skládejte na počítači nebo tabletu. Na telefonu upravíte texty tlačítkem „Upravit zde“ přímo na webu.',
    'Back to the administration' => 'Zpět do administrace',
    'Please confirm that you want to receive news at %s.' => 'Potvrďte prosím, že chcete dostávat novinky na %s.',
    'Do you really no longer want to receive news at %s?' => 'Opravdu už nechcete dostávat novinky na %s?',
    'tag' => 'štítek',
    'category' => 'kategorie',
    'my section' => 'moje sekce',
    'user' => 'uživatel',
    'Invalid sign-in request' => 'Neplatná žádost o přihlášení',
    'The application did not register correctly with this website (unknown client or return address). Please connect it again.' => 'Aplikace se na tomto webu neohlásila správně (neznámý klient nebo adresa pro návrat). Připojte ji prosím znovu.',
    'Connect an application' => 'Připojení aplikace',
    'The request to connect the application has expired or does not exist. Start connecting again in the application.' => 'Žádost o připojení aplikace vypršela nebo neexistuje. Spusťte připojení v aplikaci znovu.',
    'wants to work with the website %s.' => 'chce pracovat s webem %s.',
    'It will act with the permissions of your account %s (%s): read and edit pages, news, site parts and appearance – just like you in the administration. Builds and news are saved as drafts.' => 'Bude jednat s právy vašeho účtu %s (%s): číst a upravovat stránky, novinky, části webu a vzhled – stejně jako vy v administraci. Stavby a novinky ukládá jako koncept.',
    'After allowing it you return to the application at %s. You can revoke the connection at any time in My account → Connected applications.' => 'Po povolení se vrátíte do aplikace na adrese %s. Připojení kdykoli zrušíte na stránce Můj účet → Připojené aplikace.',
    'Allow access' => 'Povolit přístup',
    'Deny' => 'Nepovolit',
    'The easiest way is to add a custom connector in the Claude app with the address %s – Claude sends you here to sign in and confirm access, no token to copy. The token below is for Claude Code and other tools without sign-in.' => 'Nejjednodušší je přidat v aplikaci Claude vlastní konektor s adresou %s – Claude vás pošle sem přihlásit a potvrdit přístup, žádný token nekopírujete. Token níže je pro Claude Code a jiné nástroje bez přihlášení.',
    'Connected applications' => 'Připojené aplikace',
    'connected %s' => 'připojena %s',
    'Disconnect the application? It will not get into the website until you allow it again.' => 'Odpojit aplikaci? Do webu se už nedostane, dokud ji znovu nepovolíte.',
    'Disconnect' => 'Odpojit',
    'The application is disconnected – it will not get into the website until you allow it again.' => 'Aplikace je odpojená – do webu se už nedostane, dokud ji znovu nepovolíte.',
