    'images in texts: %s' => 'obrázků v textech: %s',
    'What will not be converted' => 'Co se nepřevede',
    'Private posts, trash, revisions and auto-drafts. A password-protected post is imported as a draft.' => 'Soukromé příspěvky, koš, revize a automatické koncepty. Příspěvek chráněný heslem se převede jako koncept.',
    'Custom content types:' => 'Vlastní typy obsahu:',
    'Plug-in shortcodes (forms, page builders…) – the tag disappears, the text inside stays:' => 'Zkratky doplňků (formuláře, buildery stránek…) – značka zmizí, text uvnitř zůstane:',
