    'New pages' => 'Nové stránky',
    'Redirects from old addresses' => 'Přesměrování ze starých adres',
    'Skipped (already imported earlier)' => 'Přeskočeno (převedeno už dříve)',
    'Images from the old site' => 'Obrázky ze starého webu',
    '%s images downloaded, %s failed.' => 'Staženo %s obrázků, nepodařilo se %s.',
    'Latest images that could not be downloaded' => 'Poslední obrázky, které se nepodařilo stáhnout',
    'This server cannot download files from other sites (both curl and allow_url_fopen are missing, or the GD extension). Move the images manually: upload them to Media and replace them in the articles.' => 'Tento server neumí stahovat soubory z jiných webů (chybí curl i allow_url_fopen, případně rozšíření GD). Obrázky přeneste ručně: nahrajte je do Médií a v článcích je vyměňte.',
    'The file does not contain the address of the old site, so the images cannot be downloaded.' => 'V souboru chybí adresa starého webu, obrázky proto nejde stáhnout.',
    'Try downloading again' => 'Zkusit stáhnout znovu',
    'Download images from the old site' => 'Stáhnout obrázky ze starého webu',
    'The PHP extension xmlreader or dom is missing on the server – a WordPress export cannot be read without them.' => 'Na serveru chybí rozšíření PHP xmlreader nebo dom – bez nich nejde export z WordPressu přečíst.',
    'WordPress export' => 'Export z WordPressu',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/ folder – it will appear in the list below.' => 'Server dovolí nahrát nejvýš %s. Větší soubor zkopírujte přes FTP do složky storage/import/ – objeví se v seznamu níže.',
    'Upload and show preview' => 'Nahrát a zobrazit náhled',
    'Uploaded' => 'Nahráno',
    'Delete the file %s? Content that has already been imported stays on the site.' => 'Smazat soubor %s? Už převedený obsah na webu zůstane.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors and commenters from the old site.' => 'Stejný soubor můžete importovat opakovaně – co už bylo převedeno, se přeskočí. Po dokončení importu soubor smažte, obsahuje e-maily autorů a komentujících ze starého webu.',
    'Export of the whole site' => 'Export celého webu',
    'The PHP zip extension is missing on the server, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Na serveru chybí rozšíření PHP zip, export proto obsahuje jen data (JSON). Složku media/ si stáhněte přes FTP.',
    'Create export' => 'Vytvořit export',
    'Delete the export %s?' => 'Smazat export %s?',
    'The last three exports are kept. To restore this site, use the database backup in Settings → Backups and updates.' => 'Uchovávají se poslední tři exporty. Pro obnovu tohoto webu slouží záloha databáze v Nastavení → Zálohy a aktualizace.',
