    'Show preview' => 'Zobrazit náhled',
    'Read again' => 'Načíst znovu',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/ folder.' => 'Soubor se nepodařilo nahrát. Je-li větší, než server dovoluje, nahrajte ho přes FTP do složky storage/import/.',
    'The file must have the .xml extension – it is an export from WordPress (Tools → Export).' => 'Soubor musí mít příponu .xml – je to export z WordPressu (Nástroje → Export).',
    'The file could not be saved – check write permissions for storage/import.' => 'Soubor se nepodařilo uložit – zkontrolujte práva k zápisu do storage/import.',
