    'The file contains no site content (the channel element is missing).' => 'V souboru chybí obsah webu (značka channel).',
    'The file contains a DOCTYPE or custom entities. A WordPress export never has them – the file was rejected for security reasons.' => 'Soubor obsahuje DOCTYPE nebo vlastní entity. Export z WordPressu nic takového nemá – soubor byl z bezpečnostních důvodů odmítnut.',
    'The file is not valid XML – it is damaged or incomplete. Download the export from WordPress again. The error is on line:' => 'Soubor není platné XML – je poškozený nebo neúplný. Stáhněte export z WordPressu znovu. Chyba je na řádku:',
    '(untitled)' => '(bez názvu)',
    'The address does not belong to the old site.' => 'Adresa nepatří starému webu.',
