    'There is not enough disk space for an archive with media, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Na disku není dost místa pro archiv s médii, export proto obsahuje jen data (JSON). Složku media/ si stáhněte přes FTP.',
    'The archive could not be created – check write permissions for storage/zalohy.' => 'Archiv se nepodařilo vytvořit - zkontrolujte práva k zápisu do storage/zalohy.',
