    'Company' => 'Firma',
    'Fill these in once and the site uses them everywhere: in the footer and on the contact page (the Company details element in the builder) and for Google, maps and AI assistants – so they answer correctly when you are open and where to find you.' => 'Údaje vyplníte jednou a web je použije všude: v patičce a na kontaktu (prvek Údaje firmy v builderu) i pro Google, Mapy a AI asistenty – ti tak správně odpoví na otázku, kdy máte otevřeno nebo kde vás najít.',
    'Registered company name' => 'Obchodní firma',
    'The exact registered name, e.g. “Novak Joinery Ltd”. Elsewhere the site uses the site name.' => 'Přesný název podle rejstříku, např. „Truhlářství Novák s.r.o.“. Na webu se jinak používá název webu.',
    'Business type' => 'Druh podniku',
    'Search engines show opening hours, a map and reviews depending on the type. If customers visit you, do not choose “company without premises”.' => 'Podle druhu vyhledávače ukazují otevírací dobu, mapu a hodnocení. Máte-li provozovnu pro zákazníky, nevolte „firma bez provozovny“.',
    'VAT payers only, with the country prefix, e.g. DE123456789 or FR12345678901.' => 'Jen plátce DPH, např. CZ12345678.',
    'Address and contact' => 'Adresa a kontakt',
    'Street and number' => 'Ulice a číslo',
    'Postcode' => 'PSČ',
    'City' => 'Město',
    'Country (code)' => 'Země (kód)',
    'Two-letter code, e.g. GB, IE, DE, FR. Empty = not stated.' => 'Dvoupísmenný kód: CZ, SK, DE… Prázdné = neuvádí se.',
    'Opening hours and map' => 'Otevírací doba a mapa',
    'One day or range of days per line: “Mo–Fr 8:00–17:00”, “Sa 9–12”, “Su closed”, lunch break “Tu 8–12, 13–17”. Empty = no opening hours.' => 'Každý řádek jeden den nebo rozsah dnů: „Po–Pá 8:00–17:00“, „So 9–12“, „Ne zavřeno“, polední pauza „Út 8–12, 13–17“. Prázdné = bez otevírací doby.',
    'Map link' => 'Odkaz na mapu',
    'Link to the place on Google Maps, OpenStreetMap or another map – the Company details element turns it into a “Show on map” link.' => 'Adresa místa na Mapy.cz nebo Google Maps – prvek Údaje firmy z ní udělá odkaz „Zobrazit na mapě“.',
    'Coordinates (optional)' => 'Souřadnice (nepovinné)',
    'Latitude and longitude, e.g. 50.0875, 14.4213 – a more precise location for maps and search engines.' => 'Zeměpisná šířka a délka, např. 50.0875, 14.4213 – přesnější místo pro mapy a vyhledávače.',
    'company without premises for customers' => 'firma bez provozovny pro zákazníky',
    'business premises (general)' => 'provozovna (obecně)',
    'crafts and construction' => 'řemeslo a stavebnictví',
