    'Component' => 'Komponenta',
    'A reusable block – editing the component updates it everywhere it is used.' => 'Znovupoužitelný blok – úprava komponenty se projeví všude, kde je použitá.',
    'Properties' => 'Vlastnosti',
    'Components' => 'Komponenty',
    'New component' => 'Nová komponenta',
    'No components yet.' => 'Zatím žádné komponenty.',
    'A component is a block you use in several places – a service card, a contact strip, a call to action. In the builder, select an element and choose “Save as component”; when you edit it later, it changes everywhere at once.' => 'Komponenta je blok, který používáte na víc místech – karta služby, kontaktní pruh, výzva. V builderu vyberte prvek a zvolte „Uložit jako komponentu“; když ji pak upravíte, změní se všude najednou.',
    'Create a component' => 'Založit komponentu',
    'Name and properties' => 'Název a vlastnosti',
    'Really delete this component?' => 'Opravdu smazat komponentu?',
    'Component name' => 'Název komponenty',
    'e.g. Service card' => 'např. Karta služby',
    'What can differ between uses of the component – heading, text, image, link. In the builder you insert them into the component with a {{key}} tag, then fill in a value for each use (empty = default).' => 'Co se u každého použití komponenty může lišit – nadpis, text, obrázek, odkaz. V builderu je do komponenty vložíte značkou {{klíč}}, u použití pak vyplníte hodnotu (prázdná = výchozí).',
    'Default value' => 'Výchozí hodnota',
    'Save component' => 'Uložit komponentu',
    'The component needs a name.' => 'Komponenta musí mít název.',
    'The component does not exist.' => 'Komponenta neexistuje.',
    'The component was saved.' => 'Komponenta byla uložena.',
    'The component was deleted. Places where it was used will be empty.' => 'Komponenta byla smazána. Místa, kde byla použitá, zůstanou prázdná.',
    'Name or element is missing.' => 'Chybí název nebo prvek.',
    'A component cannot be created from this element.' => 'Z tohoto prvku komponenta vzniknout nemůže.',
    'Component: %s' => 'Komponenta: %s',
    'Services and content' => 'Služby a obsah',
    'Trust' => 'Důvěra',
    'About the company' => 'O firmě',
    'Contact and calls to action' => 'Kontakt a výzvy',
    'Writing assistant – provider, your key and model' => 'Asistent psaní – poskytovatel, váš klíč a model',
    'Provider' => 'Poskytovatel',
    'Create a key with the provider:' => 'Klíč si vytvoříte u poskytovatele:',
    'Mistral AI (Europe)' => 'Mistral AI (Evropa)',
    'You pay only for actual use; one suggestion costs a fraction of a cent. The key is stored only on your site.' => 'Platíte jen za skutečné použití, jeden návrh stojí řádově haléře. Klíč se ukládá jen na vašem webu.',
    'API key' => 'Klíč API',
    'For Claude, choose from the list (Sonnet is recommended). For other providers, enter the exact model name from their documentation – their model line-up changes often.' => 'U Claude vyberte z nabídky (doporučený je Sonnet). U ostatních poskytovatelů napište přesný název modelu z jejich dokumentace – nabídka modelů se tam často mění.',
    'The assistant only suggests – a person decides on every change. When used, the text is sent to the chosen provider; nothing is sent anywhere without clicking an assistant button.' => 'Asistent jen navrhuje – o každé změně rozhoduje člověk. Při použití se text odešle zvolenému poskytovateli; bez kliknutí na tlačítko asistenta se nikam nic neposílá.',
    'The writing assistant is not enabled (Features).' => 'Asistent psaní není zapnutý (Funkce).',
    'Enter the model name of the chosen provider under Features (Writing assistant).' => 'Zadejte název modelu zvoleného poskytovatele v nabídce Funkce (Asistent psaní).',
    'The API key is missing – an administrator enters it under Features (Writing assistant).' => 'Chybí klíč API – administrátor ho zadá v nabídce Funkce (Asistent psaní).',
    'Could not reach %s. Check that the server may make outgoing connections.' => 'Službu %s se nepodařilo kontaktovat. Zkontrolujte, že server smí navazovat odchozí spojení.',
    'The %s API key is not valid. Check it under Features.' => 'Klíč API služby %s není platný. Zkontrolujte ho v nabídce Funkce.',
    '%s is busy right now or the key\'s limit is used up. Try again shortly.' => 'Služba %s je teď vytížená nebo je vyčerpaný limit klíče. Zkuste to za chvíli.',
    'The %s account has run out of credit.' => 'Na účtu služby %s došel kredit.',
    '%s does not know the model. Check its name under Features.' => 'Služba %s nezná zadaný model. Zkontrolujte jeho název v nabídce Funkce.',
    '%s is down. Try again shortly.' => 'Služba %s má výpadek. Zkuste to za chvíli.',
    'Describe the section in at least one sentence – what it should contain and for whom.' => 'Popište sekci aspoň jednou větou – co v ní má být a pro koho.',
    'The assistant did not return a usable section. Try refining the description.' => 'Asistent nevrátil použitelnou sekci. Zkuste popis upřesnit.',
    'The element has no text to rewrite.' => 'Prvek nemá text, který by šel přepsat.',
    'Add variant' => 'Přidat variantu',
    'not on any page yet' => 'zatím na žádné stránce',
    'on pages: %s' => 'na stránkách: %s',
    'variant' => 'varianta',
    'Delete the variant? The selected pages will get the default version.' => 'Smazat variantu? Vybrané stránky dostanou výchozí podobu.',
    'A variant applies only to the selected pages; elsewhere the default stays. For example a landing page with a simpler header. If you leave the variant empty in the builder, the page will have no header (footer).' => 'Varianta platí jen na vybraných stránkách, jinde zůstává výchozí podoba. Třeba landing page s jednodušším záhlavím. Když v builderu necháte variantu prázdnou, stránka záhlaví (patičku) mít nebude.',
    'Variant name' => 'Název varianty',
    'e.g. Landing page' => 'např. Landing page',
    'Only the header and footer can have variants.' => 'Varianty mají jen záhlaví a patička.',
    'Variant: %s' => 'Varianta: %s',
    'The variant needs a name.' => 'Varianta musí mít název.',
    'The variant was deleted – the selected pages have the default version again.' => 'Varianta byla smazána – vybrané stránky mají zase výchozí podobu.',
    'by field – ascending' => 'podle pole – vzestupně',
    'by field – descending' => 'podle pole – sestupně',
    'Sort field (key, e.g. price)' => 'Pole pro řazení (klíč, např. cena)',
    'Filter by field (key, optional)' => 'Filtrovat podle pole (klíč, nepovinné)',
    'Filter buttons for visitors (by the field above)' => 'Tlačítka filtru pro návštěvníky (podle pole výše)',
    'Paginate (by “Maximum items”)' => 'Stránkovat (po „Nejvýš položek“)',
    'In the builder, new sections from a description and text rewrites; in news, headlines, intro, SEO description, tags, proofreading, image descriptions and translation. Needs your own Claude, OpenAI, Google or Mistral key (below); text is sent only when you click an assistant button.' => 'V builderu nové sekce podle popisu a přepisy textů, v novinkách titulky, perex, SEO popis, štítky, korektura, popisy obrázků a překlad. Potřebuje vlastní klíč Claude, OpenAI, Google nebo Mistral (níže); text se posílá jen po kliknutí na tlačítko asistenta.',
    'MCP server at /mcp: Claude builds pages in the builder with your account\'s permissions, edits the header, footer, collections and look, and writes news. Pages and news are saved as drafts that you publish, the menu and look go into the draft look; settings apply straight away. Everyone creates their access token under My account.' => 'MCP server na adrese /mcp: Claude s právy vašeho účtu staví stránky v builderu, upravuje záhlaví, patičku, kolekce a vzhled a píše novinky. Stránky a novinky ukládá jako koncepty, které zveřejníte vy, menu a vzhled jdou do konceptu vzhledu; nastavení platí hned. Přístupový token si každý vytvoří v nabídce Můj účet.',
    'Someone else has edited this page in the meantime (or you opened it in another window).' => 'Stránku mezitím upravil někdo jiný (nebo jste ji otevřeli v jiném okně).',
    '%d files in use were not deleted – remove them from the site first (the list shows where they are used).' => 'Nesmazáno %d použitých souborů – nejdřív je odeberte z webu (kde jsou použité, ukáže výpis).',
    'page' => 'stránka',
    'site part' => 'část webu',
    'collection' => 'kolekce',
    'collection item' => 'položka kolekce',
    'component' => 'komponenta',
    'class' => 'třída',
    'settings' => 'nastavení',
    'Unused' => 'Nepoužité',
    'Used in: %s' => 'Použito: %s',
    'Shown under a news item\'s main photo unless it has its own photo credit.' => 'Uvede se pod hlavní fotkou novinky, pokud novinka nemá vlastního autora fotky.',
    'Site menu (Appearance → Menu) with submenus and the language switcher; collapsible on phones.' => 'Menu webu (Vzhled → Menu) i s podmenu a přepínač jazyků; na telefonu rozbalovací.',
    'Main menu' => 'Hlavní menu',
    'Footer menu' => 'Menu v patičce',
    'Link to news (in the automatic menu)' => 'Odkaz na novinky (u automatického menu)',
    'Language version:' => 'Jazyková verze:',
    'The menu is currently built automatically from pages ticked “in navigation”. Once you edit and save it here, this version applies.' => 'Menu se zatím skládá samo ze stránek zaškrtnutých „v navigaci“. Když ho tady upravíte a uložíte, bude platit tahle podoba.',
    'Reorder by dragging or with the arrows. The right arrow moves an item into the submenu of the one above.' => 'Pořadí měníte přetažením nebo šipkami. Šipkou vpravo zařadíte položku do podmenu té nad ní.',
    'Links in the site footer (privacy policy, contact, careers…). Used by the default footer and by a Navigation element set to the footer menu.' => 'Odkazy v patičce webu (zásady ochrany soukromí, kontakt, kariéra…). Použije je výchozí patička i prvek Navigace nastavený na menu v patičce.',
    'The menu is empty – add the first item.' => 'Menu je prázdné – přidejte první položku.',
    'Add page' => 'Přidat stránku',
    'Custom link' => 'Vlastní odkaz',
    'Group' => 'Skupina',
    'An item without a link that only opens a submenu' => 'Položka bez odkazu, která jen otevírá podmenu',
    'Save menu' => 'Uložit menu',
    'Return the menu to being built automatically from pages? Your changes will be discarded.' => 'Vrátit menu k automatickému skládání ze stránek? Vaše úpravy se zahodí.',
    'Empty the footer menu?' => 'Vyprázdnit menu v patičce?',
    'Back to automatic menu' => 'Vrátit na automatické menu',
    'Empty the menu' => 'Vyprázdnit menu',
    'The menu has been saved.' => 'Menu bylo uloženo.',
    'The menu could not be saved – please try again.' => 'Menu se nepodařilo uložit – zkuste to prosím znovu.',
    'The menu is again built automatically from pages in the navigation.' => 'Menu se zase skládá samo ze stránek zařazených do navigace.',
    'The footer menu is empty.' => 'Menu v patičce je prázdné.',
    'The site has a custom menu – the page is added to its end. Change the order and submenus in Appearance → Menu.' => 'Web má sestavené menu – stránka se přidá na jeho konec. Pořadí a podmenu upravíte ve Vzhled → Menu.',
    'Lower number = earlier in the page list and in the automatic menu.' => 'Menší číslo = dřív v seznamu stránek a v automatickém menu.',
    'Which menu' => 'Které menu',
    'First fill in the Site e-mail on the General tab.' => 'Nejprve vyplňte E-mail webu v záložce Základní.',
    'The page is in the trash. You can restore it for %d days.' => 'Stránka je v koši. Obnovit ji můžete %d dní.',
    '%s (copy)' => '%s (kopie)',
    'The page shows the text from the editor (the build\'s content without the layout). You will find the build in versions when you open the builder.' => 'Stránka zobrazuje text z editoru (obsah stavby bez rozložení). Stavbu najdete ve verzích, když otevřete builder.',
    'The home page cannot be deleted. First choose another home page in Settings → General.' => 'Úvodní stránku nejde smazat. Nejdřív v Nastavení → Základní vyberte jinou úvodní stránku.',
    'The home page cannot be hidden. First choose another home page in Settings → General.' => 'Úvodní stránku nejde skrýt. Nejdřív v Nastavení → Základní vyberte jinou úvodní stránku.',
    'A page in the trash uses this address – restore it or delete it permanently.' => 'Tuto adresu má stránka v koši – obnovte ji, nebo ji smažte natrvalo.',
    'The page has been restored as hidden – publish it in its settings.' => 'Stránka je obnovená jako skrytá – zveřejníte ji v jejím nastavení.',
    'The page has been permanently deleted.' => 'Stránka byla smazána natrvalo.',
    'The copy of the page is hidden – edit it and publish it.' => 'Kopie stránky je skrytá – upravte ji a zveřejněte.',
    'Tag deleted. The news items remain, they just no longer carry it.' => 'Štítek byl smazán. Novinky zůstaly, jen ho už nemají.',
    'Page' => 'Stránka',
    'The editor now contains the version from %s. It takes effect once you save the news item.' => 'V editoru je verze z %s. Platit začne, až novinku uložíte.',
    'News items moved to the trash: %d. They can be restored for 30 days (News → Trash).' => 'Do koše přesunuto novinek: %d. Obnovit je jde 30 dní (Novinky → Koš).',
    'News items restored: %d. They are back as drafts.' => 'Obnoveno novinek: %d. Vrátily se jako koncepty.',
    'News items permanently deleted: %d.' => 'Natrvalo smazáno novinek: %d.',
    'The news item does not exist or you do not have access to it.' => 'Novinka neexistuje nebo k ní nemáte přístup.',
    'Only an editor or administrator can edit a published news item.' => 'Vydanou novinku může upravit jen editor nebo správce.',
    'Save the news item first, then it can be translated.' => 'Novinku nejdřív uložte, pak ji půjde přeložit.',
    'This version of the news item does not exist.' => 'Verze novinky neexistuje.',
    'The news item will be checked again within a few minutes.' => 'Novinka se zkontroluje znovu během několika minut.',
    'Categories' => 'Kategorie',
    'The category does not exist.' => 'Kategorie neexistuje.',
    'Category saved.' => 'Kategorie byla uložena.',
    'The category cannot be deleted while it contains news items (including those in the trash). Move them elsewhere first.' => 'Kategorii nelze smazat, dokud v ní jsou novinky (i v koši). Nejprve je přesuňte jinam.',
    'Category deleted.' => 'Kategorie byla smazána.',
    'Fill in the category name.' => 'Vyplňte název kategorie.',
    'Site appearance' => 'Vzhled webu',
    'The site appearance has been saved.' => 'Vzhled webu byl uložen.',
    'Does not write news' => 'Nepíše novinky',
    'Writes, edits and publishes news by all authors' => 'Píše, upravuje a vydává novinky všech autorů',
    'Writes and edits their own news; an editor publishes it' => 'Píše a upravuje vlastní novinky, vydává je editor',
    'The user has been deleted. Their news items remain, without an author.' => 'Uživatel byl smazán. Jeho novinky zůstaly zachované bez autora.',
    'The build is not valid JSON.' => 'Stavba nemá platný tvar JSON.',
    'There is nothing to publish.' => 'Není co publikovat.',
    'The section is not in the library.' => 'Sekce v knihovně není.',
    'Class name: lowercase letters without accents, digits and hyphens (e.g. card, card--highlighted).' => 'Název třídy: malá písmena bez diakritiky, číslice a pomlčky (např. karta, karta--zvyraznena).',
    'Declaration not allowed: %s' => 'Nepovolená deklarace: %s',
    'The version does not exist.' => 'Verze neexistuje.',
    '/new-address or https://…' => '/nova-adresa nebo https://…',
    'A redirect is only used when nothing exists at the old address. It is created automatically when the address of a page, news item or category changes.' => 'Přesměrování se použije jen tehdy, když na staré adrese nic není. Při změně adresy stránky, novinky nebo kategorie vzniká samo.',
    'Nothing to do – when you change the address of a page or news item, a redirect is created automatically.' => 'Nic nemusíte dělat – když změníte adresu stránky nebo novinky, přesměrování vznikne samo.',
    'Addresses visitors could not find (404)' => 'Adresy, které návštěvníci nenašli (404)',
    'Write a news item' => 'Napsat novinku',
    'Images used in the news item “%s”.' => 'Obrázky použité v novince „%s“.',
    'Upload your first photos with the form above – or drag them straight into the text in the editor.' => 'Nahrajte první fotky formulářem nahoře – nebo je přetáhněte přímo do textu v editoru.',
    'Really delete the selected files? Files the site still uses are skipped.' => 'Opravdu smazat označené soubory? Soubory, které web ještě používá, se přeskočí.',
    'Image credit' => 'Autor obrázku',
    'Scheduled news is published and dates are shown according to it. It is now %s.' => 'Podle něj se vydávají naplánované novinky a zobrazují data. Teď je %s.',
    'The site texts (Search, News, Read more…) are in this language, and the site declares it to search engines.' => 'V tomto jazyce jsou texty webu (Hledat, Novinky, Číst dál…) a web se tak hlásí vyhledávačům.',
    'Each version has its own pages, categories and news. A news item\'s language is set by its category. Link translations in the editor.' => 'Každá verze má své stránky, kategorie a novinky. Jazyk novinky určuje její kategorie. Překlad propojíte v editoru.',
    'Home page and news' => 'Úvodní stránka a novinky',
    'Site home page' => 'Úvodní stránka webu',
    '– news list –' => '– výpis novinek –',
    'The page shown at the site address. News is always at %s.' => 'Stránka, která se ukáže na adrese webu. Novinky jsou vždy na %s.',
    'The site sends password reset links and system notifications, and enquiries from forms. With your own SMTP server, messages go out from a verified mailbox and do not end up in spam.' => 'Web posílá odkazy pro obnovu hesla a upozornění systému; s formuláři přibudou i poptávky. Přes vlastní SMTP server zprávy odcházejí z ověřené schránky a nekončí ve spamu.',
    'Send a test e-mail to the site address' => 'Odeslat zkušební e-mail na adresu webu',
    'Scheduled news, notifications and outgoing mail run on site visits. A low-traffic site makes them more precise by calling this address every 5 minutes from your hosting\'s cron:' => 'Naplánované novinky, oznámení a odeslání pošty se spouštějí při návštěvách webu. Web s menší návštěvností je zpřesní, když tuto adresu zavoláte každých 5 minut cronem hostingu:',
    'Restore the database from this backup? Everything added to the site since it was created (pages, news, enquiries, settings) will be lost. The current state is saved to a new backup first.' => 'Obnovit databázi z této zálohy? Všechno, co na webu přibylo po jejím vytvoření (stránky, novinky, poptávky, nastavení), se ztratí. Současný stav se předtím uloží do nové zálohy.',
    'The database backup contains pages, news, settings and users; uploaded images are in the media backup. Backups are stored in the backups folder storage/zalohy/, which is not accessible from the web – download copies off the server too.' => 'Záloha databáze obsahuje stránky, novinky, nastavení a uživatele; nahrané obrázky jsou v záloze médií. Zálohy leží ve složce storage/zalohy/, která není z webu přístupná – stahujte si je i mimo server.',
    'Language' => 'Jazyk',
    'unpublished changes' => 'nepublikované změny',
    'Category name' => 'Název kategorie',
    'The part of the address after %s.' => 'Část adresy za %s.',
    'Shown above the category\'s news list and used as the description for search engines.' => 'Zobrazí se nad výpisem novinek kategorie a použije se jako popis pro vyhledávače.',
    'Higher number = higher in the list.' => 'Vyšší číslo = výš v seznamu.',
    'News in this category belongs to this language version of the site.' => 'Novinky v kategorii patří do této jazykové verze webu.',
    'New category' => 'Nová kategorie',
    'Back to news' => 'Zpět na novinky',
    'No category has been created yet.' => 'Zatím není založena žádná kategorie.',
    'Every news item belongs to one category – without it, the news item cannot be saved.' => 'Každá novinka patří do jedné kategorie – bez ní novinka nepůjde uložit.',
    'Create the first category' => 'Založit první kategorii',
    'News items' => 'Novinek',
    'Really delete the category?' => 'Opravdu smazat kategorii?',
    'Open the builder' => 'Otevřít builder',
    'This page\'s content is built in the builder.' => 'Obsah této stránky se skládá v builderu.',
    'Want to build the page from sections, columns and buttons?' => 'Chcete stránku poskládat ze sekcí, sloupců a tlačítek?',
    'Open in the builder' => 'Otevřít v builderu',
    'Search engines and sharing' => 'Vyhledávače a sdílení',
    'empty = page name' => 'prázdné = název stránky',
    'One or two sentences on what visitors will find on the page (up to 160 characters).' => 'Jedna až dvě věty, co na stránce návštěvník najde (do 160 znaků).',
    'empty = default image from Settings' => 'prázdné = výchozí obrázek z Nastavení',
    'Shown when the link is shared on Facebook, LinkedIn or Teams (ideally 1200 × 630 px).' => 'Ukáže se při sdílení odkazu na Facebooku, LinkedInu nebo v Teams (ideálně 1200 × 630 px).',
    'site home page' => 'úvodní stránka webu',
    'Show in the site\'s main navigation' => 'Zobrazit v hlavní navigaci webu',
    'Save and open in the builder' => 'Uložit a otevřít v builderu',
    'Duplicate page' => 'Duplikovat stránku',
    'Return the page to plain text? The build stays in versions and you can go back to it.' => 'Vrátit stránku k obyčejnému textu? Stavba zůstane ve verzích a můžete se k ní vrátit.',
    'Return page to text' => 'Vrátit stránku k textu',
    'The builder needs JavaScript. The page content can also be edited without it in the page form.' => 'Builder potřebuje JavaScript. Obsah stránky jde upravit i bez něj ve formuláři stránky.',
    'Name or address contains:' => 'Název nebo adresa obsahuje:',
    'Deleted pages stay here for 30 days, then they are deleted permanently.' => 'Smazané stránky tu zůstávají 30 dní, potom se smažou natrvalo.',
    'Back to pages' => 'Zpět na stránky',
    'No page matches the search.' => 'Hledání neodpovídá žádná stránka.',
    'Try another word.' => 'Zkuste jiné slovo.',
    'Clear search' => 'Zrušit hledání',
    'A business website usually consists of Home, About us, Services and Contact.' => 'Firemní web obvykle tvoří Úvod, O nás, Služby a Kontakt.',
    'Pages in the trash are not on the site. A restored page comes back hidden; after 30 days it is permanently deleted from the trash.' => 'Stránky v koši nejsou na webu. Obnovená stránka se vrátí jako skrytá; po 30 dnech se z koše smaže natrvalo.',
    'Delete the page permanently? This cannot be undone.' => 'Smazat stránku natrvalo? Nejde to vrátit.',
    'home' => 'úvodní',
    'The builder has changes that are not on the site yet.' => 'V builderu jsou změny, které ještě nejsou na webu.',
    'The builder has work-in-progress changes that are not on the site yet.' => 'V builderu jsou rozpracované změny, které ještě nejsou na webu.',
    'You are building this page in the builder. The site still shows the text below – once you publish in the builder, the build replaces it.' => 'Stránku skládáte v builderu. Na webu je zatím text níže – po publikování v builderu ho nahradí stavba.',
    'Preview hidden page' => 'Náhled skryté stránky',
    'Duplicate' => 'Duplikovat',
    'Move the page to the trash? It disappears from the site; you can restore it for 30 days.' => 'Přesunout stránku do koše? Z webu zmizí, obnovit ji můžete 30 dní.',
    'Most read news' => 'Nejčtenější novinky',
    'Where visitors come from' => 'Odkud návštěvníci přicházejí',
    'You cannot remove administrator rights from your own account.' => 'Vlastní účet nemůžete zbavit práv správce.',
    'Really delete the user? Their news items will remain, without an author.' => 'Opravdu smazat uživatele? Jeho novinky zůstanou zachované bez autora.',
    'Categories (those with posts are created)' => 'Kategorie (založí se ty, které mají příspěvky)',
    'User accounts and passwords – the news items will belong to you. Comments are not transferred.' => 'Účty a hesla uživatelů – novinky budou patřit vám. Komentáře se nepřenášejí.',
    'Menus, widgets, appearance and plugin settings – you will rebuild the navigation on the new site.' => 'Nabídky (menu), widgety, vzhled a nastavení doplňků – navigaci si na novém webu sestavíte znovu.',
    'Which language version of the site the new categories and pages belong to.' => 'Do které jazykové verze webu nové kategorie a stránky patří.',
    'Put posts without a category into' => 'Příspěvky bez kategorie dát do',
    'a new “Uncategorised” category' => 'nové kategorie „Nezařazené“',
    'Imported news is not announced: no webhook or IndexNow. Before a larger import, create a database backup in Settings → Backups and updates.' => 'Importované novinky se neoznamují: žádný webhook ani IndexNow. Před větším importem si v Nastavení → Zálohy a aktualizace vytvořte zálohu databáze.',
    'Downloading images from the old site: %s of %s news items and pages done, %s images downloaded. Keep this page open, I will continue automatically.' => 'Stahuji obrázky ze starého webu: hotovo %s z %s novinek a stránek, staženo %s obrázků. Nechte stránku otevřenou, pokračuji sám.',
    'New news items' => 'Nové novinky',
    'New categories' => 'Nové kategorie',
    'Show news' => 'Zobrazit novinky',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded only from the domain %s, and the old site must still be available.' => 'Novinky a stránky zatím ukazují obrázky ze starého webu. Stažením se hlavní obrázky novinek a obrázky v textech uloží do Médií (zmenší se, vzniknou náhledy a WebP) a odkazy v textech se přepíší. Stahuje se výhradně z domény %s a starý web musí být ještě dostupný.',
    'In WordPress, open Tools → Export, choose “All content” and download the .xml file. Then upload it here. Pages, posts (as news), categories and tags are converted and redirects from the old addresses are created; nothing changes on the site until you confirm the import in the next step.' => 'Ve WordPressu otevřete Nástroje → Export, zvolte „Veškerý obsah“ a stáhněte soubor .xml. Ten pak nahrajte sem. Převedou se stránky, příspěvky (jako novinky), kategorie a štítky a vzniknou přesměrování ze starých adres; na webu se nic nezmění, dokud import v dalším kroku nepotvrdíte.',
    'One archive gives you the whole site in an open format (JSON): pages, news, categories, tags, redirects, menus, collections, pop-ups, site parts, components, shared classes and uploaded files – as a content backup or for moving elsewhere. Enquiries, passwords, keys and accounts are not included.' => 'Jedním archivem dostanete celý web v otevřeném formátu (JSON): stránky, novinky, kategorie, štítky, přesměrování, menu, kolekce, pop-up okna, části webu, komponenty, sdílené třídy a nahrané soubory – jako zálohu obsahu nebo pro převod jinam. Poptávky, hesla, klíče ani účty v něm nejsou.',
    'Back to the news list' => 'Zpět na přehled novinek',
    'Shown in lists and at the start of the news item – do not repeat it in the text.' => 'Zobrazuje se ve výpisech i na začátku novinky – v textu ho neopakujte.',
    'To embed a video, put its address (YouTube, Vimeo) on a line of its own. It loads for the visitor only after a click.' => 'Video vložíte tak, že jeho adresu (YouTube, Vimeo) dáte na samostatný řádek. Návštěvníkovi se načte až po kliknutí.',
    'Draft' => 'Koncept',
    'An editor or site administrator publishes the news item.' => 'Novinku vydá editor nebo správce webu.',
    'A future date = the news item is published automatically at that time.' => 'Budoucí datum = novinka se vydá sama v daný čas.',
    'Mark as updated (with today\'s date)' => 'Označit jako aktualizovanou (s dnešním datem)',
    'Comma-separated. Visitors can use a tag to see related news.' => 'Oddělené čárkou. Návštěvník si podle štítku zobrazí související novinky.',
    'Image caption' => 'Popisek obrázku',
    'Empty field = caption and credit from the Media library.' => 'Prázdné pole = popisek a autor z knihovny Médií.',
    'Translation' => 'Překlad',
    'Language versions' => 'Jazykové verze',
    'Translate the saved version with the assistant? A draft is created for you to read before publishing. Translation can take up to a minute.' => 'Přeložit uloženou verzi asistentem? Vznikne koncept, který před vydáním přečtete. Překlad může trvat i minutu.',
    'address or number of the original news item' => 'adresa nebo číslo původní novinky',
    'Fill in only for a news item in another language version (the category sets the language).' => 'Vyplňte jen u novinky v jiné jazykové verzi (jazyk určuje kategorie).',
    'SEO and more settings' => 'SEO a další nastavení',
    'The part of the address after %s. If you change it after publishing, the old address redirects automatically.' => 'Část adresy za %s. Když ji po vydání změníte, stará adresa se sama přesměruje.',
    'empty = news item title' => 'prázdné = titulek novinky',
    'Question on one line, the answer below it, an empty line between pairs. Shown below the text and in structured data (FAQ).' => 'Otázka na jednom řádku, odpověď pod ní, mezi dvojicemi prázdný řádek. Zobrazí se pod textem a ve strukturovaných datech (FAQ).',
    'In the background, the system goes through published news – one every five minutes, each once a month – and checks whether its links still work. News items checked: %s of %s.' => 'Systém na pozadí prochází vydané novinky – jednu za pět minut, každou jednou za měsíc – a zkouší, jestli odkazy v nich ještě fungují. Zkontrolováno novinek: %s z %s.',
    'New news item' => 'Nová novinka',
    'News status' => 'Stav novinek',
    'Category:' => 'Kategorie:',
    'Total:' => 'Celkem:',
    'Deleted news items stay here for 30 days, then they are deleted permanently.' => 'Smazané novinky tu zůstávají 30 dní, potom se smažou natrvalo.',
    'No news item matches the filter.' => 'Filtru neodpovídá žádná novinka.',
    'Try another word, category or status.' => 'Zkuste jiné slovo, kategorii nebo stav.',
    'There are no news items yet.' => 'Zatím tu není žádná novinka.',
    'Until you publish a news item, it stays a draft that nobody sees on the site.' => 'Než novinku vydáte, zůstává konceptem, který na webu nikdo nevidí.',
    'Write the first news item' => 'Napsat první novinku',
    'News items in the trash are not on the site. A restored news item comes back as a draft; after 30 days it is permanently deleted from the trash.' => 'Novinky v koši nejsou na webu. Obnovená novinka se vrátí jako koncept; po 30 dnech se z koše smaže natrvalo.',
    'Delete the selected news items permanently? This cannot be undone.' => 'Smazat označené novinky natrvalo? Nejde to vrátit.',
    'Back to the news item' => 'Zpět do novinky',
    'Tags are created automatically as you write news. When you add a description to a tag, its page becomes a topic – an introduction to a field or project with all its news in one place.' => 'Štítky vznikají samy při psaní novinek. Když štítku doplníte popis, stane se z jeho stránky téma – úvod k oboru nebo projektu se všemi novinkami na jednom místě.',
    'Optional. Shown above the news list and as the description for search engines.' => 'Nepovinné. Zobrazí se nad výpisem novinek a jako popis pro vyhledávače.',
    'The news items get the selected tag, this one is removed and its address redirects. Useful for typos and duplicate spellings.' => 'Novinky dostanou vybraný štítek, tento zanikne a jeho adresa se přesměruje. Hodí se na překlepy a dvojí psaní.',
    'Add them in the news editor in the Tags field. Here you can then merge them and turn them into topic pages.' => 'Přidáte je v editoru novinky v poli Štítky. Tady je pak půjde slučovat a měnit na stránky témat.',
    'Delete the tag? The news items stay, they just lose this tag.' => 'Smazat štítek? Novinky zůstanou, jen ho už nebudou mít.',
    'Changed by an administrator in Users.' => 'Mění správce v sekci Uživatelé.',
    'Shown with news items on the site.' => 'Zobrazuje se u novinek na webu.',
    'Position in the company' => 'Pozice ve firmě',
    'e.g. head of sales' => 'např. vedoucí obchodu',
    'Shown as a short profile under your news items. What you do in the company and your background.' => 'Zobrazí se jako medailonek pod vašimi novinkami. Čím se ve firmě zabýváte a co máte za sebou.',
    'It creates new news items as drafts and new pages as hidden. All its changes are in the Change log. Protect the token like a password.' => 'Nové novinky zakládá jako koncepty a nové stránky jako skryté. Všechny jeho zásahy najdete v Protokolu změn. Token chraňte jako heslo.',
    'Colours' => 'Barvy',
    'Shades (muted text, lines, soft primary colour) and the button text colour are derived automatically.' => 'Odstíny (tlumený text, linky, jemná hlavní barva) a barva textu na tlačítkách se dopočítají samy.',
    'Readability' => 'Čitelnost',
    'according to the visitor\'s device' => 'podle zařízení návštěvníka',
    'Check your logo: a dark logo on a transparent background would disappear on a dark site.' => 'Zkontrolujte logo: tmavé logo na průhledném pozadí by na tmavém webu zaniklo.',
    'Sizes' => 'Velikosti',
    'Type and spacing grow smoothly with the window width – from phone to large monitor. Headings are multiples of the base font size.' => 'Písmo i mezery rostou plynule s šířkou okna – od telefonu po velký monitor. Nadpisy jsou násobky základního písma.',
