    'section saved to library' => 'uložení sekce do knihovny',
    'The copy of the news item is saved as a draft.' => 'Kopie novinky je uložená jako koncept.',
    'The copy of the item is hidden – edit it and publish it.' => 'Kopie položky je skrytá – upravte ji a zveřejněte.',
    'Roles' => 'Role',
