    'The role has been saved.' => 'Role byla uložena.',
    'The role has been deleted. Its members kept their current access.' => 'Role byla smazána. Její členové si ponechali dosavadní přístup.',
    'Writes own content' => 'Píše vlastní obsah',
    'Only own news and without publishing – an editor publishes.' => 'Novinky jen své a bez vydávání – vydává editor.',
    'Manages everyone\'s content' => 'Spravuje obsah všech',
    'Edits and publishes news by all authors.' => 'Upravuje a vydává novinky všech autorů.',
    'Back to users' => 'Zpět na uživatele',
    'The built-in roles News author, Editor and Administrator are enough for most websites. A custom role is useful when someone should see only part of the administration – for example a salesperson only Enquiries.' => 'Vestavěné role Autor novinek, Editor a Správce stačí většině webů. Vlastní role se hodí, když má někdo vidět jen část administrace – třeba obchodník jen Poptávky.',
    'No custom roles yet.' => 'Zatím žádné vlastní role.',
    'Delete the role? Its members will keep their current access.' => 'Smazat roli? Její členové si ponechají dosavadní přístup.',
    'Back to roles' => 'Zpět na role',
    'Role name' => 'Název role',
    'e.g. Salesperson' => 'např. Obchodník',
    'Website settings, users and appearance stay with the administrator.' => 'Nastavení webu, uživatele a vzhled zůstávají správci.',
    'Saving also changes the permissions of these users:' => 'Uložení změní práva i těmto uživatelům:',
    'Custom role' => 'Vlastní role',
    'a named set of sections, for example only Enquiries for a salesperson.' => 'pojmenovaná sada sekcí, třeba jen Poptávky pro obchodníka.',
    'An author usually has only News, an editor all content sections, an administrator everything. With a custom role, the role\'s sections apply.' => 'Autor má běžně jen Novinky, editor všechny obsahové sekce, správce vše. U vlastní role platí sekce z role.',
    'Tap the place on the page to move the element to (top or bottom part of an element = before or after, middle of a container = inside). Esc cancels.' => 'Klepněte na místo na stránce, kam prvek přesunout (horní nebo dolní část prvku = před nebo za, střed kontejneru = dovnitř). Esc zruší.',
    'Drag or tap to move' => 'Přetažením nebo klepnutím přesunete',
