    'How to connect Claude' => 'Jak připojit Clauda',
    'Links for a feature appear once it is switched on and saved.' => 'Odkazy u funkce se objeví po jejím zapnutí a uložení.',
    'Claude connection – how to connect' => 'Napojení na Claude – jak připojit',
    'In the Claude app open Settings → Connectors → Add custom connector.' => 'V aplikaci Claude otevřete Nastavení → Konektory → Přidat vlastní konektor.',
    'Enter this address:' => 'Jako adresu zadejte:',
    'Claude sends you here to sign in and confirm access. It then works with your account\'s permissions – builds and news are saved as drafts.' => 'Claude vás pošle sem přihlásit a potvrdit přístup. Pracuje pak s právy vašeho účtu – stavby a novinky ukládá jako koncept.',
    'In Claude Code, just run:' => 'V Claude Code stačí příkaz:',
    'Connected applications and personal tokens for other tools are in' => 'Připojené aplikace a osobní tokeny pro jiné nástroje najdete v',
    'The connector needs the site on HTTPS in the domain root.' => 'Konektor potřebuje web na HTTPS v kořeni domény.',
    'Administrator' => 'Správce',
    'Published pages' => 'Zveřejněné stránky',
    'Pages with unpublished changes' => 'Stránky s nepublikovanými změnami',
    'Published news' => 'Vydané novinky',
