    'Secondary colour on background' => 'Doplňková barva na pozadí',
    'subtle (1.125)' => 'jemný (1,125)',
    'calm (1.2)' => 'klidný (1,2)',
    'balanced (1.25)' => 'vyvážený (1,25)',
