    'Save answers' => 'Uložit odpovědi',
    'Everything the blueprint checks is in place.' => 'Vše, co plán kontroluje, je v pořádku.',
    'Apply a blueprint' => 'Použít oborový plán',
    'No other blueprints are available. Upload a blueprint file below.' => 'Další plány nejsou k dispozici. Nahrajte soubor s plánem níže.',
