    'Job opening without a closing date – set “true until” to the application deadline: the job then hides itself and search engines get validThrough, which they need to tell an open job from an expired one.' => 'Pracovní místo bez uzávěrky – nastavte „platí do“ na termín pro přihlášky: pozice se pak sama skryje a vyhledávače dostanou validThrough, podle kterého poznají otevřenou pozici od uzavřené.',
    '%d job applications older than %d months were deleted, including the CVs.' => 'Smazáno %d žádostí o místo starších než %d měsíců, včetně životopisů.',
    'Delete job applications after' => 'Žádosti o místo mazat po',
    'Applications sent from the pages of a Job openings collection carry CVs and are usually kept only for a limited time after the selection. 0 = like other enquiries.' => 'Žádosti odeslané ze stránek kolekce Volná místa obsahují životopisy a obvykle se uchovávají jen omezenou dobu po výběrovém řízení. 0 = jako ostatní poptávky.',
    'Usual practice in %s: %d months – check with your lawyer.' => 'Obvyklá praxe v %s: %d měsíců – ověřte u svého právníka.',
