    'New branches (store locator)' => 'Nové pobočky (vyhledávač poboček)',
    'Address, location, phone, e-mail, opening hours, photo and a page for each branch or store; the Store locator element lists them with search, the nearest one and a map.' => 'Adresa, poloha, telefon, e-mail, otevírací doba, fotka a stránka pro každou pobočku nebo prodejnu; prvek Vyhledávač poboček je vypíše s hledáním, nejbližší pobočkou a mapou.',
