    'A TV or a tablet in the reception, showroom or waiting room opens the address below and rotates slides by itself: the latest news, items of the chosen collections and today\'s opening hours. The address has a secret part, so nobody finds the screen by guessing; it is not indexed and sets no cookies.' => 'Televize nebo tablet na recepci, v showroomu či čekárně otevře adresu níže a sám střídá snímky: nejnovější novinky, položky zvolených kolekcí a dnešní otevírací dobu. Adresa má tajnou část, takže obrazovku nikdo nenajde hádáním; neindexuje se a nenastavuje cookies.',
    'Seconds per slide' => 'Sekund na jeden snímek',
    'Collections to show' => 'Zobrazované kolekce',
    'The site has no collections yet.' => 'Web zatím nemá žádné kolekce.',
    'A collection with a date field (events, courses) shows only the upcoming items.' => 'Kolekce s polem termínu (akce, kurzy) ukazuje jen nadcházející položky.',
    'Show the latest news' => 'Ukazovat nejnovější novinky',
