    'Screen address' => 'Adresa obrazovky',
    'Copy address' => 'Kopírovat adresu',
    'Open it on the screen in full-screen (kiosk) mode. Anyone with the address sees the screen – do not publish it.' => 'Otevřete ji na obrazovce v celoobrazovkovém (kiosk) režimu. Obrazovku vidí každý, kdo adresu zná – nezveřejňujte ji.',
    'Save the settings with the screen mode on – the address is created then.' => 'Uložte nastavení se zapnutým režimem obrazovky – adresa vznikne při uložení.',
    'Official notice board' => 'Úřední deska',
    'New notice board' => 'Nová úřední deska',
    'Posting and takedown dates, reference number, issuer, category, document and summary; the board shows what is posted now, the archive what was taken down. Notices are never deleted and every change is logged.' => 'Datum vyvěšení a sejmutí, číslo jednací, původce, kategorie, dokument a shrnutí; deska ukazuje, co je právě vyvěšeno, archiv to, co bylo sejmuto. Oznámení se nikdy nemažou a každá změna se zapisuje.',
