    'Notice status' => 'Stav oznámení',
    'Notices stay in the archive – change the takedown date instead.' => 'Oznámení zůstávají v archivu – změňte místo toho datum sejmutí.',
    'A notice that is or was posted cannot be hidden – it stays on the board until its takedown date and then in the archive. Change the dates instead.' => 'Oznámení, které je nebo bylo vyvěšeno, nelze skrýt – zůstává na desce do dne sejmutí a potom v archivu. Změňte místo toho data.',
    'The notice board has %s notices – they stay in the archive, so the collection cannot be deleted.' => 'Úřední deska má %s oznámení – zůstávají v archivu, kolekci proto nelze smazat.',
    'The collection is not an official notice board.' => 'Kolekce není úřední deska.',
    'Notice log (%s)' => 'Protokol oznámení (%s)',
    'Every creation and change of the notice and the day it was posted and taken down. The log is append-only – nothing in it can be edited or deleted.' => 'Každé založení a změna oznámení a den, kdy bylo vyvěšeno a sejmuto. Do protokolu se jen přidává – nic v něm nelze upravit ani smazat.',
