    'Only create the link' => 'Jen vytvořit odkaz',
    'The customer gets a personal link for 30 days; what they write arrives as a hidden draft in References, with the consent they gave.' => 'Zákazník dostane osobní odkaz na 30 dní; co napíše, přijde jako skrytý koncept do Referencí i se souhlasem, který dal.',
