    'Hotspots' => 'Aktivní body',
    'Timeline' => 'Časová osa',
    'Plans side by side – name, price, features and a button; one plan can be highlighted.' => 'Balíčky vedle sebe – název, cena, funkce a tlačítko; jeden balíček může být zvýrazněný.',
    'Two photos with a draggable divider – a renovation, a cleaning, a makeover.' => 'Dvě fotky s posuvným dělítkem – rekonstrukce, úklid, proměna.',
    'An image with numbered points – a tap on a point shows its label and text (a product, a floor plan, a map of premises).' => 'Obrázek s číslovanými body – klepnutí na bod ukáže jeho název a text (produkt, půdorys, plán areálu).',
