    'The site talks only to the services listed here, only after you connect them. Sign-ins and keys are stored encrypted and never shown again – not here, not to Claude, not in the site export.' => 'Web komunikuje jen se službami uvedenými zde a jen po jejich napojení. Přihlášení a klíče se ukládají šifrovaně a už se nikdy neukážou – ani tady, ani Claudovi, ani v exportu webu.',
    'Connected' => 'Napojeno',
    'Not connected' => 'Nenapojeno',
    'since %s' => 'od %s',
    'Create an OAuth app (a web application) with %s and enter its client ID and secret. The redirect address to enter there:' => 'Vytvořte u služby %s aplikaci OAuth (webovou aplikaci) a zadejte její ID klienta a tajný klíč. Adresa pro přesměrování, kterou tam zadáte:',
    'Where to get it' => 'Kde ho získat',
    'Client ID' => 'ID klienta',
    'Client secret' => 'Tajný klíč klienta',
    'stored – type to replace' => 'uloženo – napište nový pro nahrazení',
    'Where to get the key' => 'Kde získat klíč',
    'Connect %s' => 'Napojit %s',
    'Disconnect %s? The stored sign-in is deleted; what was already sent stays there.' => 'Odpojit %s? Uložené přihlášení se smaže; co už se odeslalo, tam zůstane.',
    'Last calls' => 'Poslední volání',
    '%d deliveries are waiting or being retried.' => '%d doručení čeká nebo se opakuje.',
    'No calls yet.' => 'Zatím žádná volání.',
    'The sign-in was cancelled: %s' => 'Přihlášení bylo zrušeno: %s',
    '%s is connected.' => '%s je napojený.',
    'Disconnected – the stored sign-in was deleted.' => 'Odpojeno – uložené přihlášení je smazané.',
    'Enter the client ID and secret of your OAuth app first.' => 'Nejdřív zadejte ID klienta a tajný klíč své aplikace OAuth.',
    'The sign-in could not be verified. Try connecting again.' => 'Přihlášení se nepodařilo ověřit. Zkuste napojení znovu.',
    '%s did not accept the sign-in: %s' => '%s přihlášení nepřijal(a): %s',
    '%s was connected.' => '%s byl napojen.',
    'The sign-in expired – connect %s again.' => 'Přihlášení vypršelo – napojte %s znovu.',
    '%s is not connected.' => '%s není napojený.',
    'Too many calls to %s this minute – it will be tried again.' => 'Příliš mnoho volání %s za tuto minutu – zkusí se to znovu.',
    'A delivery to an outside service failed: %s' => 'Doručení do externí služby selhalo: %s',
    'Deliveries to connected services' => 'Doručení do napojených služeb',
    'An outside service was connected.' => 'Byla napojena externí služba.',
    'A delivery to an outside service failed after all retries.' => 'Doručení do externí služby selhalo i po všech opakováních.',
    'Links to /%s now lead to %s (%d places).' => 'Odkazy na /%s teď vedou na %s (%d míst).',
    'Personal data of one address were erased on request.' => 'Osobní údaje jedné adresy byly na žádost vymazány.',
    'Only an administrator can handle personal data requests.' => 'Žádosti o osobní údaje vyřizuje jen administrátor.',
    'Tick that you want to erase the data.' => 'Zaškrtněte, že chcete údaje vymazat.',
    'Erased: %d enquiries, %d subscriptions, %d e-mails in the queue, %d testimonial requests.' => 'Vymazáno: poptávky %d, odběry %d, e-maily ve frontě %d, žádosti o referenci %d.',
    'A testimonial the person sent stays in References (items %s) – remove it there if they ask.' => 'Reference, kterou člověk poslal, zůstává v Referencích (položky %s) – smažte ji tam, pokud o to požádá.',
    'Personal data request' => 'Žádost o osobní údaje',
    'find, export or erase everything about one e-mail address' => 'najít, vyexportovat nebo vymazat vše o jedné e-mailové adrese',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent and testimonial requests.' => 'Když se někdo zeptá, co o něm web uchovává, nebo požádá o výmaz: zadejte jeho e-mailovou adresu. Hledá se v poptávkách (odesílatel i všechna pole), v odběru newsletteru, v e-mailech čekajících na odeslání a v žádostech o referenci.',
    'E-mail address' => 'E-mailová adresa',
    'Find' => 'Najít',
    'What the site keeps about %s' => 'Co web uchovává o %s',
    'Nothing – the site keeps no data about this address.' => 'Nic – web o této adrese žádné údaje neuchovává.',
    'Enquiries: %d' => 'Poptávky: %d',
    'Newsletter subscription since %s' => 'Odběr newsletteru od %s',
    'not confirmed' => 'nepotvrzený',
    'E-mails in the outgoing queue: %d' => 'E-maily ve frontě k odeslání: %d',
    'Testimonial requests: %d' => 'Žádosti o referenci: %d',
    'An account of the administration (%s) – change or remove it in Users; it is not erased here.' => 'Účet administrace (%s) – změňte nebo smažte ho v Uživatelích; zde se nemaže.',
    'Download as a file for the person (JSON)' => 'Stáhnout jako soubor pro daného člověka (JSON)',
    'Erase everything listed above for good? This cannot be undone.' => 'Vymazat vše uvedené natrvalo? Nelze to vrátit.',
    'I want to erase this data for good' => 'Chci tyto údaje natrvalo vymazat',
    'Erase' => 'Vymazat',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails and testimonial requests are deleted. Backups keep older copies until they expire.' => 'Smažou se poptávky s přílohami, odběr (i v napojené mailingové službě), e-maily ve frontě a žádosti o referenci. Zálohy si starší kopie drží, dokud nevyprší.',
    'The page password must have at least %d characters.' => 'Heslo stránky musí mít aspoň %d znaků.',
    'Page password' => 'Heslo stránky',
    'protected – type a new password to change it' => 'chráněná – pro změnu napište nové heslo',
    'none – the page is public' => 'žádné – stránka je veřejná',
    'Remove the password' => 'Zrušit heslo',
    'Visitors see the page only after entering the password – e.g. a price list for partners. It is not an account: whoever knows the password reads the page. A protected page is never in search engines, the sitemap or the site search.' => 'Návštěvníci uvidí stránku až po zadání hesla – např. ceník pro partnery. Nejde o účet: kdo heslo zná, stránku přečte. Chráněná stránka nikdy není ve vyhledávačích, v mapě webu ani ve vyhledávání na webu.',
    '%d files in Media. The site found what can be cleaned up – nothing changes until you decide.' => 'Souborů v Médiích: %d. Web našel, co jde uklidit – nic se nezmění, dokud nerozhodnete.',
    '%d images have no description for blind visitors (alt).' => 'Obrázků bez popisu pro nevidomé (alt): %d.',
    'Add language versions in Settings → General; this screen then shows which translations are missing.' => 'Jazykové verze přidáte v Nastavení → Základní; tato obrazovka pak ukáže, které překlady chybí.',
    'Apply the action to the selected items?' => 'Provést akci s vybranými položkami?',
    'Back to draft' => 'Zpět do konceptu',
    'Back to media' => 'Zpět na média',
    'Category…' => 'Kategorie…',
    'Clean-up' => 'Úklid',
    'Content check' => 'Kontrola obsahu',
    'Delete %s' => 'Smazat %s',
    'Delete selected files' => 'Smazat vybrané soubory',
    'Delete the selected files for good? Media has no trash. Files the site still uses are skipped.' => 'Smazat vybrané soubory natrvalo? Média nemají koš. Soubory, které web ještě používá, se přeskočí.',
    'Describe what each image shows – screen readers and search engines read it. Empty fields are skipped; the rest is saved together.' => 'Popište, co je na každém obrázku – čtou to čtečky obrazovky i vyhledávače. Prázdná pole se přeskočí, ostatní se uloží najednou.',
    'Duplicates' => 'Duplicity',
    'Every file is used somewhere on the site.' => 'Každý soubor je někde na webu použitý.',
    'Every image has a description (alt).' => 'Každý obrázek má popis (alt).',
