    'Spam check: the passed challenge' => 'Kontrola spamu: splněná ověřovací úloha',
    'Spam check: accessibility of the challenge' => 'Kontrola spamu: přístupnost ověřovací úlohy',
    'Cookies and storage this site uses' => 'Cookies a úložiště, které tento web používá',
    'What Kaleta itself sets, what the known embeds and tags found in your pages and settings set (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) and what the server answers with. Put {{cookie_table}} into your cookie policy page – the table appears there in the site language.' => 'Co nastavuje sama Kaleta, co nastavují známá vložení a kódy nalezené ve vašich stránkách a nastavení (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) a s čím odpovídá server. Vložte {{cookie_table}} do stránky zásad cookies – tabulka se tam objeví v jazyce webu.',
    'Last scan of the site’s own pages: %s, %d pages, %d cookies set by the server.' => 'Poslední sken vlastních stránek webu: %s, %d stránek, %d cookies nastavených serverem.',
    'The server could not reach the site: %s.' => 'Server se k webu nedostal: %s.',
    'The site’s own pages have not been scanned yet – the background tasks do it daily.' => 'Vlastní stránky webu ještě nebyly skenovány – úlohy na pozadí to dělají denně.',
    'Scan the site now' => 'Skenovat web teď',
    'Documents from the configuration' => 'Dokumenty z nastavení',
    'Templates assembled from what the site is set up to do – review and complete them, they are not legal advice.' => 'Šablony sestavené z toho, co má web nastaveno – zkontrolujte a doplňte je, nejsou právní radou.',
    'Record of processing' => 'Záznam o zpracování',
    'Show the record' => 'Zobrazit záznam',
    'GDPR Art. 30 style: forms and their fields, enquiries and applications with their retention, newsletter, statistics, connected services, mail, backups, the writing assistant, cookies.' => 'Ve stylu čl. 30 GDPR: formuláře a jejich pole, poptávky a uchazeči s dobou uchování, newsletter, statistika, propojené služby, pošta, zálohy, asistent psaní, cookies.',
    'Accessibility statement' => 'Prohlášení o přístupnosti',
    'published' => 'zveřejněno',
    'hidden draft' => 'skrytý koncept',
    'Regenerate the draft from the audit' => 'Znovu vytvořit koncept z auditu',
    'Create the draft from the audit' => 'Vytvořit koncept z auditu',
    'Filled from the site audit: the standard (EN 301 549 / WCAG 2.1 AA), the status by the accessibility findings, the known barriers and the contact. Created as a hidden page – review it, then publish it. Regenerating updates the draft.' => 'Vyplněno z auditu webu: norma (EN 301 549 / WCAG 2.1 AA), stav podle nálezů přístupnosti, známé bariéry a kontakt. Vznikne jako skrytá stránka – zkontrolujte ji a pak zveřejněte. Opakované vytvoření aktualizuje koncept.',
    'Accessibility toolbar for visitors' => 'Lišta přístupnosti pro návštěvníky',
    'A small button on every page: larger text, higher contrast, underlined links, reduced motion. Remembered in the visitor’s browser, no cookies.' => 'Malé tlačítko na každé stránce: větší písmo, vyšší kontrast, podtržené odkazy, omezený pohyb. Pamatuje si prohlížeč návštěvníka, bez cookies.',
    'The scan could not reach the site from the server (%s). The table shows what Kaleta and the known embeds set.' => 'Sken se ze serveru k webu nedostal (%s). Tabulka ukazuje, co nastavuje Kaleta a známá vložení.',
    'Scanned %d pages: %d cookies set by the server.' => 'Skenováno %d stránek: %d cookies nastavených serverem.',
    'The accessibility statement is ready as a hidden page – review it, then publish it: %s' => 'Prohlášení o přístupnosti je připraveno jako skrytá stránka – zkontrolujte ho a pak zveřejněte: %s',
    'Generated on %s from the site’s configuration. A template to review and complete – not legal advice.' => 'Vygenerováno %s z nastavení webu. Šablona ke kontrole a doplnění – není právní radou.',
    'Add what the site does not know about (paper files, accounting, other systems) and keep the record with your documentation; print it from the browser.' => 'Doplňte, o čem web neví (papírové spisy, účetnictví, další systémy), a uložte záznam ke své dokumentaci; vytisknete ho z prohlížeče.',
    'As Markdown (to copy)' => 'Jako Markdown (ke zkopírování)',
    'After that period' => 'Po uplynutí této doby',
    'delete them including attachments' => 'smazat včetně příloh',
    'anonymise them – the row stays for statistics (date, form, page, topic, kind) without the name, e-mail, phone, message and attachments' => 'anonymizovat – řádek zůstane pro statistiku (datum, formulář, stránka, téma, druh) bez jména, e-mailu, telefonu, zprávy a příloh',
    'Anonymised' => 'Anonymizováno',
    'the row stays for statistics without the person' => 'řádek zůstává pro statistiku bez údajů o osobě',
    'Blank the name, e-mail, phone, message and attachments of this enquiry? The row stays for statistics.' => 'Vymazat jméno, e-mail, telefon, zprávu a přílohy této poptávky? Řádek zůstane pro statistiku.',
    'Anonymise' => 'Anonymizovat',
    'The enquiry was anonymised – the row stays for statistics without the person.' => 'Poptávka byla anonymizována – řádek zůstává pro statistiku bez údajů o osobě.',
    'What cookies the site sets' => 'Jaké cookies web nastavuje',
    'Controller' => 'Správce',
    'Company: %s' => 'Firma: %s',
    'Company: not filled in (Business details)' => 'Firma: nevyplněno (Údaje o firmě)',
    'Address: %s' => 'Adresa: %s',
    'Contact: %s' => 'Kontakt: %s',
    'Contact: no site e-mail (Settings → General)' => 'Kontakt: web nemá e-mail (Nastavení → Základní)',
    'Website: %s' => 'Web: %s',
    'Form “%s” on %s: fields %s; notification to %s%s' => 'Formulář „%s“ na %s: pole %s; oznámení na %s%s',
    'the site e-mail' => 'e-mail webu',
    'the sender gets a confirmation e-mail' => 'odesílatel dostane potvrzovací e-mail',
    'Enquiries and form messages' => 'Poptávky a zprávy z formulářů',
    'No form on the published site.' => 'Na zveřejněném webu není žádný formulář.',
    'Purpose: answering the enquiry and the business relationship that follows. Legal basis: performance of a contract or steps before it (Art. 6(1)(b)), legitimate interest in answering.' => 'Účel: vyřízení poptávky a navazující obchodní vztah. Právní základ: plnění smlouvy nebo kroky před jejím uzavřením (čl. 6 odst. 1 písm. b), oprávněný zájem na odpovědi.',
    'Retention: %d months, then %s automatically.' => 'Uchování: %d měsíců, poté automaticky %s.',
    'anonymised (the row stays for statistics without the person)' => 'anonymizováno (řádek zůstává pro statistiku bez údajů o osobě)',
    'deleted including attachments' => 'smazáno včetně příloh',
    'Retention: not limited – set it in Enquiries → Settings.' => 'Uchování: neomezeno – nastavte ho v Poptávky → Nastavení.',
    'Recipients: the people with access to Enquiries in the administration%s.' => 'Příjemci: lidé s přístupem k Poptávkám v administraci%s.',
    'a webhook at %s' => 'webhook na %s',
    'Job applications' => 'Uchazeči o práci',
    'Applications to job openings arrive as enquiries from the job pages, with CVs as attachments.' => 'Reakce na pracovní pozice přicházejí jako poptávky ze stránek pozic, s CV jako přílohami.',
    'Retention: %d months, then deleted including the CVs.' => 'Uchování: %d měsíců, poté smazáno včetně CV.',
    'Retention: the same as other enquiries (%d months).' => 'Uchování: stejně jako ostatní poptávky (%d měsíců).',
    'Legal basis: steps before a contract (Art. 6(1)(b)); keeping an application longer needs the applicant’s consent.' => 'Právní základ: kroky před uzavřením smlouvy (čl. 6 odst. 1 písm. b); delší uchování vyžaduje souhlas uchazeče.',
    'Subscribers: %d confirmed, %d waiting for confirmation (double opt-in; unconfirmed sign-ups are deleted after 30 days).' => 'Odběratelé: %d potvrzených, %d čeká na potvrzení (double opt-in; nepotvrzené přihlášky se po 30 dnech mažou).',
    'Data: e-mail address, date and language of the sign-up%s.' => 'Údaje: e-mailová adresa, datum a jazyk přihlášení%s.',
    'the first page of the visit and its campaign (with consent to marketing)' => 'první stránka návštěvy a její kampaň (se souhlasem s marketingem)',
    'Legal basis: consent (Art. 6(1)(a)); every e-mail carries an unsubscribe link.' => 'Právní základ: souhlas (čl. 6 odst. 1 písm. a); každý e-mail má odkaz pro odhlášení.',
    'Processor: the mailing service %s (confirmed subscribers are passed to it).' => 'Zpracovatel: mailingová služba %s (potvrzení odběratelé se do ní předávají).',
    'Processor: none – the newsletter is sent from this site.' => 'Zpracovatel: žádný – newsletter se posílá z tohoto webu.',
    'Built-in statistics: page views, devices and campaigns counted without cookies; the visitor’s address is hashed with a daily salt and never stored.' => 'Vestavěná statistika: zobrazení stránek, zařízení a kampaně počítané bez cookies; adresa návštěvníka se hashuje s denní solí a nikdy se neukládá.',
    '%s – a third-party service (processor); runs only after consent in the cookie bar unless the bar is off.' => '%s – služba třetí strany (zpracovatel); běží až po souhlasu v cookie liště, pokud lišta není vypnutá.',
    'No traffic statistics.' => 'Žádná statistika návštěvnosti.',
    '%s (account %s) – data the deliveries send leaves the site to this service.' => '%s (účet %s) – data odesílaná doručeními odcházejí z webu do této služby.',
    'Connected services and processors' => 'Propojené služby a zpracovatelé',
    'E-mail: sent through the SMTP server %s.' => 'E-mail: odesílán přes SMTP server %s.',
    'E-mail: sent by the hosting server’s mail function.' => 'E-mail: odesílá poštovní funkce hostingového serveru.',
    'Backups: automatic %s, an off-site copy over %s to %s.' => 'Zálohy: automatické %s, kopie mimo server přes %s na %s.',
    'Backups: automatic %s, kept on this server only.' => 'Zálohy: automatické %s, jen na tomto serveru.',
    'Writing assistant: %s – texts the administrators ask about%s are sent to it.' => 'Asistent psaní: %s – texty, na které se správci ptají%s, se mu odesílají.',
    'and new enquiries (triage)' => 'a nové poptávky (třídění)',
    'Writing assistant: off.' => 'Asistent psaní: vypnutý.',
    'Claude (MCP): administrators’ assistants work with the content; enquiries are shown to them as the Enquiries screen shows them.' => 'Claude (MCP): asistenti správců pracují s obsahem; poptávky vidí tak, jak je ukazuje obrazovka Poptávky.',
    'Spam check: %s receives the visitor’s address and browser details when a form is sent.' => 'Kontrola spamu: %s při odeslání formuláře dostává adresu návštěvníka a údaje o prohlížeči.',
    'Spam check: built-in only (a signed time, a trap field, a limit per address) – no third party.' => 'Kontrola spamu: jen vestavěná (podepsaný čas, pastové pole, limit na adresu) – bez třetí strany.',
    'Cookies and storage' => 'Cookies a úložiště',
    'Cookie bar: %s.' => 'Cookie lišta: %s.',
    'built-in, tracking starts after consent' => 'vestavěná, měření začíná po souhlasu',
    'an external service' => 'externí služba',
    'Consents are logged (time, a random identifier, the categories – no IP address)%s.' => 'Souhlasy se zaznamenávají (čas, náhodný identifikátor, kategorie – bez IP adresy)%s.',
    'and deleted after %d months' => 'a po %d měsících se mažou',
    'Consents are not logged.' => 'Souhlasy se nezaznamenávají.',
    'Security' => 'Zabezpečení',
    'Access to personal data: %d administration account(s); two-step sign-in %s.' => 'Přístup k osobním údajům: %d účet(ů) administrace; dvoufázové přihlášení %s.',
    'on for everyone' => 'zapnuto u všech',
    'not on for every account' => 'není zapnuto u všech účtů',
    'Firewall: on (rate limits, probes, country and address blocks).' => 'Firewall: zapnutý (limity požadavků, sondy, blokace zemí a adres).',
    'Transport: %s.' => 'Přenos: %s.',
    'HTTP – switch the site to HTTPS' => 'HTTP – přepněte web na HTTPS',
    '%s is committed to making its website accessible in line with the European Accessibility Act and the national legislation that implements it. This accessibility statement applies to %s.' => '%s se zavazuje zpřístupnit své webové stránky v souladu s Evropským aktem o přístupnosti a vnitrostátními předpisy, které ho provádějí. Toto prohlášení o přístupnosti se vztahuje na %s.',
    'The website aims to meet EN 301 549 and WCAG 2.1 level AA.' => 'Web usiluje o splnění normy EN 301 549 a WCAG 2.1 úrovně AA.',
    'Compliance status: this website is fully compliant – the automatic check found no barriers.' => 'Stav souladu: tyto webové stránky jsou plně v souladu – automatická kontrola nenašla žádné bariéry.',
    'Compliance status: this website is partially compliant because of the non-compliances listed below.' => 'Stav souladu: tyto webové stránky jsou částečně v souladu kvůli níže uvedeným nedostatkům.',
    'Non-accessible content:' => 'Nepřístupný obsah:',
    'This statement was prepared on %s from an automatic check of the site. The automatic check does not cover everything a person would notice; the owner reviews the statement before publishing it.' => 'Toto prohlášení bylo vypracováno %s na základě automatické kontroly webu. Automatická kontrola nepokrývá vše, čeho by si všiml člověk; provozovatel prohlášení před zveřejněním zkontroluje.',
    'Feedback and contact: if you find a barrier or need content in another form, write to %s. We will answer as soon as we can.' => 'Zpětná vazba a kontakt: narazíte-li na bariéru nebo potřebujete obsah v jiné podobě, napište na %s. Odpovíme co nejdříve.',
    'Feedback and contact: add the e-mail address people can write to about barriers (Settings → General → Site e-mail).' => 'Zpětná vazba a kontakt: doplňte e-mailovou adresu, na kterou mohou lidé psát o bariérách (Nastavení → Základní → E-mail webu).',
    'Enforcement: if you are not satisfied with our answer, you can contact the body in your country that supervises the accessibility of websites.' => 'Vymáhání: nebudete-li s naší odpovědí spokojeni, můžete se obrátit na orgán ve své zemi, který dohlíží na přístupnost webových stránek.',
    'Pages nobody links to' => 'Stránky, na které nikdo neodkazuje',
    'No published page, menu or text links here – visitors and search engines reach it only by its address. Add a link from a related page (Claude: suggest_internal_links).' => 'Žádná zveřejněná stránka, menu ani text sem neodkazuje – návštěvníci a vyhledávače se sem dostanou jen přes adresu. Přidejte odkaz z příbuzné stránky (Claude: suggest_internal_links).',
    '/%s now redirects to /%s by itself (score %d of 100). Undo: Administration → Redirects.' => '/%s teď samo přesměrovává na /%s (skóre %d ze 100). Zpět: Administrace → Přesměrování.',
    'Created by the site itself from an address visitors could not find. Delete it to undo.' => 'Vytvořil web sám z adresy, kterou návštěvníci nenašli. Zpět to vezmete smazáním.',
    'automatic, score %d' => 'automaticky, skóre %d',
    'By themselves' => 'Samo',
    'Create redirects for missing addresses by themselves' => 'Vytvářet přesměrování chybějících adres samo',
    'Once a day the site redirects an address visitors could not find to the page it is sure they meant (the same address written differently, moved to another section or language). Such a redirect is marked automatic; deleting it undoes it. Less certain candidates stay below as suggestions.' => 'Jednou denně web přesměruje adresu, kterou návštěvníci nenašli, na stránku, o které je si jistý (stejná adresa napsaná jinak, přesunutá do jiné sekce nebo jazyka). Takové přesměrování je označené jako automatické; smazáním ho vrátíte. Méně jisté kandidáty zůstávají níže jako návrhy.',
    'Needed score' => 'Potřebné skóre',
    '0–100; 100 = the same address written differently, 95 = another section or language, 90 = the same last part of the address, lower = a similar address.' => '0–100; 100 = stejná adresa napsaná jinak, 95 = jiná sekce nebo jazyk, 90 = stejná poslední část adresy, méně = podobná adresa.',
    'Create redirect – one click accepts the page the site thinks the visitor meant (the score says how sure it is).' => 'Vytvořit přesměrování – jedním kliknutím přijmete stránku, kterou podle webu návštěvník myslel (skóre říká, jak si je jistý).',
    'Probably meant' => 'Asi myslel',
    'score %d' => 'skóre %d',
    'no similar page' => 'žádná podobná stránka',
    'Create redirect' => 'Vytvořit přesměrování',
    'It will be checked again within a few minutes.' => 'Během několika minut se zkontroluje znovu.',
    'In the background, the system goes through published news, pages and collection items – one every five minutes, each once a month – and checks whether their links still work. Checked: %s of %s.' => 'Systém na pozadí prochází vydané novinky, stránky a položky kolekcí – jednu za pět minut, každou jednou za měsíc – a kontroluje, zda jejich odkazy stále fungují. Zkontrolováno: %s z %s.',
    'Item' => 'Položka',
    'element %s' => 'prvek %s',
    'Redirects for addresses visitors could not find' => 'Přesměrování adres, které návštěvníci nenašli',
    'Item “%s”' => 'Položka „%s“',
    'An internal reporting channel for the EU Whistleblower Directive (2019/1937) and the national laws built on it. Reports are stored encrypted and only the readers chosen below can open them – other administrators see case numbers and dates. Acknowledge a report within %d days and give feedback within %d months.' => 'Vnitřní oznamovací systém podle směrnice EU o ochraně oznamovatelů (2019/1937) a navazujících národních zákonů. Oznámení jsou uložena šifrovaně a otevřou je jen níže zvolení čtenáři – ostatní správci vidí čísla případů a data. Přijetí potvrďte do %d dnů a vyrozumění dejte do %d měsíců.',
    'This is a tool, not legal advice: your company must appoint the person responsible for reports and check the rules of its country (who must have a channel, what the deadlines and the records are).' => 'Je to nástroj, ne právní rada: firma musí určit příslušnou osobu pro oznámení a ověřit pravidla své země (kdo musí mít kanál, jaké jsou lhůty a evidence).',
    'The channel is switched off – the public address answers with a 404 error.' => 'Kanál je vypnutý – veřejná adresa odpovídá chybou 404.',
    'No reader is chosen – reports arrive, but nobody can open them.' => 'Není zvolen žádný čtenář – oznámení přicházejí, ale nikdo je nemůže otevřít.',
    'No reports yet.' => 'Zatím žádná oznámení.',
    'The form is at %s – put a link to it in the footer menu (Menu) or on a page.' => 'Formulář je na adrese %s – odkaz na něj dejte do menu v patičce (Menu) nebo na stránku.',
    'Switch the channel on below and put a link to the form in the footer menu.' => 'Níže kanál zapněte a odkaz na formulář dejte do menu v patičce.',
    '%d open, %d in total.' => 'Otevřených %d, celkem %d.',
    'Case' => 'Případ',
    'Acknowledge by' => 'Potvrdit do',
    'Feedback by' => 'Vyrozumět do',
    'Acknowledged' => 'Potvrzeno',
    'In progress' => 'Řeší se',
    'Case closed' => 'Případ uzavřen',
    'acknowledged %s' => 'potvrzeno %s',
    'overdue' => 'po lhůtě',
    'closed %s' => 'uzavřeno %s',
    'You are not among the readers, so the cases do not open for you.' => 'Nejste mezi čtenáři, případy se vám proto neotevřou.',
    'Setup' => 'Nastavení kanálu',
    'The channel is on' => 'Kanál je zapnutý',
    'The public form: %s. Add a link to it to the footer menu or a page – the site does not add it by itself.' => 'Veřejný formulář: %s. Odkaz na něj přidejte do menu v patičce nebo na stránku – web ho sám nepřidá.',
    'Shown above the form: who handles reports in your company, what belongs here, where the whistleblowing policy is.' => 'Zobrazí se nad formulářem: kdo ve firmě oznámení řeší, co sem patří, kde je vnitřní předpis.',
    'Who may read reports' => 'Kdo smí číst oznámení',
    'no e-mail – will not be notified' => 'bez e-mailu – nebude upozorněn',
    'Only these people open the reports – other administrators see case numbers and dates. A new report is announced to them by e-mail with the case number only.' => 'Oznámení otevřou jen tito lidé – ostatní správci vidí čísla případů a data. Nové oznámení jim e-mail ohlásí jen číslem případu.',
    'Delete closed cases after' => 'Uzavřené případy smazat po',
    'Closed cases are deleted with their attachments and messages; open cases are kept. Check the retention period your national law requires.' => 'Uzavřené případy se smažou včetně příloh a zpráv; otevřené zůstávají. Ověřte si dobu uchování, kterou vyžaduje zákon vaší země.',
    'Claude and other connected tools never see the reports: no MCP tool reads or lists them, and the site export leaves them out.' => 'Claude ani jiné připojené nástroje oznámení nikdy nevidí: žádný nástroj MCP je nečte ani nevypisuje a export webu je vynechává.',
    'All cases' => 'Všechny případy',
    'Reporter' => 'Oznamovatel',
    'anonymous' => 'anonymní',
    'Report' => 'Oznámení',
    'Attachments' => 'Přílohy',
    'Messages' => 'Zprávy',
    'No messages yet. Your first answer acknowledges the receipt.' => 'Zatím žádné zprávy. Vaše první odpověď potvrdí přijetí.',
    'Handler' => 'Příslušná osoba',
    'Reply to the reporter' => 'Odpověď oznamovateli',
    'The reporter reads it after opening the case with the case number and the access code. Nothing is e-mailed.' => 'Oznamovatel si ji přečte po otevření případu číslem a přístupovým kódem. Nic se neposílá e-mailem.',
    'Send the reply' => 'Odeslat odpověď',
    'Change the status' => 'Změnit stav',
    'A closed case is deleted after the retention period set in the channel.' => 'Uzavřený případ se smaže po době uchování nastavené u kanálu.',
    'Case %s' => 'Případ %s',
    'Only the appointed readers and administrators see the whistleblowing channel.' => 'Oznamovací kanál vidí jen určení čtenáři a správci.',
    'Saved. Choose at least one reader – until then nobody can open the reports.' => 'Uloženo. Zvolte alespoň jednoho čtenáře – do té doby oznámení nikdo neotevře.',
    'Only the appointed readers open reports. An administrator can add readers in the setup of the channel.' => 'Oznámení otevřou jen určení čtenáři. Správce může čtenáře přidat v nastavení kanálu.',
    'The case does not exist.' => 'Případ neexistuje.',
    'Write the message first.' => 'Nejdřív napište zprávu.',
    'The message was added – the reporter sees it after opening the case with the code.' => 'Zpráva byla přidána – oznamovatel ji uvidí po otevření případu kódem.',
    'The status is saved.' => 'Stav je uložen.',
    'Whistleblowing: due deadlines and the retention of closed cases' => 'Whistleblowing: blížící se lhůty a uchování uzavřených případů',
    'Search Console property' => 'Vlastnost v Search Console',
    'sc-domain:example.com or https://example.com/ – load the list with the button below; empty = this site’s address.' => 'sc-domain:example.com nebo https://example.com/ – seznam načtete tlačítkem níže; prázdné = adresa tohoto webu.',
    'Site in Bing Webmaster Tools' => 'Web v Bing Webmaster Tools',
    'The address as it is registered there, e.g. https://example.com/ – empty = this site’s address.' => 'Adresa, jak je tam zaregistrovaná, např. https://example.com/ – prázdné = adresa tohoto webu.',
    'Load my properties' => 'Načíst moje vlastnosti',
    'The account has no Search Console property. Add the site at search.google.com/search-console first.' => 'Účet nemá v Search Console žádnou vlastnost. Nejdřív web přidejte na search.google.com/search-console.',
