    'Search Console has no sitemap of this site yet.' => 'Search Console zatím nemá žádnou mapu tohoto webu.',
    'Search engines' => 'Vyhledávače',
    'Connect Google Search Console or Bing Webmaster Tools in Administration → Connections; the queries and pages arrive with the daily job.' => 'Napojte Google Search Console nebo Bing Webmaster Tools v Administrace → Napojení; dotazy a stránky přinese denní úloha.',
    'Search engines: the latest snapshot of the period (%s), each covering the 28 days before it; the position is the average place in the results, 1 = first.' => 'Vyhledávače: poslední snímek v období (%s), každý pokrývá 28 dní před ním; pozice je průměrné místo ve výsledcích, 1 = první.',
    '%s on %s' => '%s na %s',
    '%s clicks' => '%s kliknutí',
    'Searches that brought visitors' => 'Hledání, která přivedla návštěvníky',
    'Social post drafts' => 'Návrhy příspěvků na sítě',
    'When a news item is published, a post draft per network is prepared under the news item – with a tracked link and the image. You copy and post it yourself; the site never posts anywhere.' => 'Po vydání novinky se u ní připraví návrh příspěvku pro každou síť – se sledovaným odkazem a obrázkem. Zkopírujete a zveřejníte ho sami; web nikam nic nepublikuje.',
    'Social posts' => 'Příspěvky na sítě',
    'No network is chosen. Pick the networks under Settings → General → More options and the drafts appear here.' => 'Není vybraná žádná síť. Vyberte sítě v Nastavení → Obecné → Další možnosti a návrhy se tu objeví.',
    'Prepared when the news item was published, with a tracked link – the statistics show the visits from each network. Edit the text, copy it and post it yourself; the site never posts anywhere.' => 'Připraveno při vydání novinky, se sledovaným odkazem – statistika ukáže návštěvy z každé sítě. Text upravte, zkopírujte a zveřejněte sami; web nikam nic nepublikuje.',
    'Rewrite all the drafts with the assistant? Your edits to them are replaced. Hashtags and the link are added back.' => 'Přepsat všechny návrhy asistentem? Vaše úpravy se nahradí. Hashtagy a odkaz se doplní zpět.',
    'Suggest with the assistant' => 'Navrhnout asistentem',
    'posted %s' => 'zveřejněno %s',
    'Post for %s' => 'Příspěvek pro %s',
    'At most %d characters; a link counts as %d.' => 'Nejvýš %d znaků; odkaz se počítá jako %d.',
    'Image:' => 'Obrázek:',
    'Link for the bio:' => 'Odkaz do bia:',
    'Not posted yet' => 'Ještě nezveřejněno',
    'Mark as posted' => 'Označit jako zveřejněné',
