    'Marked as posted.' => 'Označeno jako zveřejněné.',
    'Marked as not posted yet.' => 'Označeno jako ještě nezveřejněné.',
    'The assistant rewrote the drafts – read them before posting.' => 'Asistent návrhy přepsal – před zveřejněním si je přečtěte.',
    'The draft does not exist.' => 'Návrh neexistuje.',
    'The post needs a text.' => 'Příspěvek potřebuje text.',
    'The post is too long (at most 3000 characters).' => 'Příspěvek je příliš dlouhý (nejvýš 3000 znaků).',
    'X allows 280 characters with a link counted as 23 – this post is longer.' => 'X dovolí 280 znaků, odkaz se počítá jako 23 – tento příspěvek je delší.',
    'There are no drafts to rewrite.' => 'Nejsou žádné návrhy k přepsání.',
    'Link in bio' => 'Odkaz v biu',
    'Business Profile' => 'Firemní profil',
    'The opening hours from Business details and their exceptions go to the chosen location whenever they change and once a day; the newest reviews and the rating come back for the Google reviews element and the facts {{fact.google_rating}} and {{fact.google_reviews}}.' => 'Otevírací doba z Údaje o firmě a její výjimky se posílají do vybrané pobočky při každé změně a jednou denně; zpět přicházejí nejnovější recenze a hodnocení pro prvek Recenze Google a fakta {{fact.google_rating}} a {{fact.google_reviews}}.',
    '– none, nothing is synced –' => '– žádná, nic se nesynchronizuje –',
