    'Form names separated by commas; empty = every form' => 'Názvy formulářů oddělené čárkou; prázdné = každý formulář',
    'Include job applications' => 'Včetně odpovědí na volná místa',
    'They carry CVs – only the file name goes out, never the file' => 'Nesou životopisy – odejde jen název souboru, nikdy soubor',
    'Enquiries to a sheet' => 'Poptávky do tabulky',
    'Spreadsheet ID' => 'ID tabulky',
    'Filled in by “Create the sheet”; clear it to have a new sheet created' => 'Vyplní tlačítko „Vytvořit tabulku“; smažte ho a vytvoří se nová tabulka',
