    'Create the sheet' => 'Vytvořit tabulku',
    'Open the sheet' => 'Otevřít tabulku',
    'Create the sheet first – without it no enquiry is sent.' => 'Nejdřív vytvořte tabulku – bez ní se žádná poptávka neodešle.',
    'The sheet was created – tick “Enquiries to a sheet” and new enquiries will appear in it.' => 'Tabulka je vytvořená – zaškrtněte „Poptávky do tabulky“ a nové poptávky se v ní objeví.',
    '%s – enquiries' => '%s – poptávky',
    'Connect Google first.' => 'Nejdřív napojte Google.',
    'Google did not return the sheet.' => 'Google tabulku nevrátil.',
    'No sheet – create it in Administration → Connections.' => 'Tabulka chybí – vytvořte ji v Administrace → Napojení.',
