    'Enter the Raynet instance name in Connections.' => 'Zadejte název instance Raynet v Napojení.',
    'Fields' => 'Pole',
    'Why: %s' => 'Proč: %s',
    'Guardrails for Claude' => 'Mantinely pro Clauda',
    'They hold for every Claude connection on top of its access. Claude is told why when it hits one, so it can tell you.' => 'Platí pro každé napojení Clauda navíc k jeho oprávnění. Když na některý narazí, Claude se dozví proč a může vám to říct.',
    'Changes per connection and hour' => 'Změn za hodinu na jedno napojení',
    '0 = no limit. A long run of changes stops here until the next hour.' => '0 = bez omezení. Dlouhá řada změn se tu zastaví do další hodiny.',
    'Deleting' => 'Mazání',
    'Claude may delete, trash and discard drafts' => 'Claude smí mazat, vyhazovat do koše a zahazovat koncepty',
    'Off: those tools are refused for every connection; you do them in the admin.' => 'Vypnuto: tyto nástroje budou pro každé napojení odmítnuty; uděláte je v administraci.',
    'Protected pages' => 'Chráněné stránky',
    'Page numbers (shown in the page editor’s address) that Claude must not change – neither their settings nor their build.' => 'Čísla stránek (jsou v adrese editoru stránky), které Claude nesmí měnit – ani jejich nastavení, ani stavbu.',
    'Notebook' => 'Zápisník',
    'New note' => 'Nová poznámka',
    'The note does not exist.' => 'Poznámka neexistuje.',
    'The note is saved.' => 'Poznámka je uložená.',
    'The note is deleted.' => 'Poznámka je smazaná.',
    'A note needs a title.' => 'Poznámka potřebuje název.',
    'A note needs a text.' => 'Poznámka potřebuje text.',
    'The topic must be one of: %s.' => 'Téma musí být jedno z: %s.',
    'Notes for whoever works on the site next – Claude in a new conversation, or a colleague: decisions, wording rules, photo credits, the history of the site, what the client is sensitive about. Claude reads them with read_notebook before larger changes and writes decisions down with write_notebook – a drafts-only connection too. Nothing here is shown on the site.' => 'Poznámky pro toho, kdo bude na webu pracovat příště – Clauda v nové konverzaci nebo kolegu: rozhodnutí, pravidla formulací, autoři fotek, historie webu, na co je klient citlivý. Claude si je před většími změnami přečte nástrojem read_notebook a rozhodnutí zapisuje nástrojem write_notebook – i s napojením jen pro koncepty. Nic z toho se na webu nezobrazuje.',
    'All topics' => 'Všechna témata',
    'Decisions' => 'Rozhodnutí',
    'Style and wording' => 'Styl a formulace',
    'Credits' => 'Autorství a zdroje',
    'Search (title, text):' => 'Hledat (název, text):',
    'No note matches the filter.' => 'Filtru neodpovídá žádná poznámka.',
    'Try another word or topic.' => 'Zkuste jiné slovo nebo téma.',
    'No notes yet.' => 'Zatím žádné poznámky.',
    'Write down what the next person – or Claude – should know: a decision, a wording rule, who took the photos, why a page looks the way it does.' => 'Zapište, co má vědět další člověk – nebo Claude: rozhodnutí, pravidlo formulace, kdo fotil, proč stránka vypadá tak, jak vypadá.',
    'pinned' => 'připnuto',
    'Unpin' => 'Odepnout',
    'Pin' => 'Připnout',
    'Delete the note? It cannot be brought back.' => 'Smazat poznámku? Nejde vrátit zpět.',
    'Only the first %d notes are shown – narrow the list by a topic or a search.' => 'Zobrazuje se jen prvních %d poznámek – zužte výpis tématem nebo hledáním.',
    'All notes' => 'Všechny poznámky',
    'e.g. We never use the word “cheap”' => 'např. Nikdy nepoužíváme slovo „levný“',
    'Plain text. Write it for someone who knows nothing about the site yet – what was decided, why, and what to keep to.' => 'Prostý text. Pište ho pro někoho, kdo o webu ještě nic neví – co se rozhodlo, proč a čeho se držet.',
    'Pinned' => 'Připnutá',
    'Pinned notes come first and Claude sees their titles as soon as it connects.' => 'Připnuté poznámky jsou první a Claude vidí jejich názvy hned po připojení.',
    'Written by %s, %s; last changed %s.' => 'Zapsal(a) %s, %s; poslední změna %s.',
    'Requests' => 'Požadavky',
    'New request' => 'Nový požadavek',
    'New' => 'Nový',
    'Declined' => 'Zamítnuto',
    '(no longer exists)' => '(už neexistuje)',
    'A new request for Claude: %s' => 'Nový požadavek pro Clauda: %s',
    '(account removed)' => '(účet odstraněn)',
    'New request for Claude: %s' => 'Nový požadavek pro Clauda: %s',
    'A colleague wrote a new request for Claude: %s' => 'Kolega napsal nový požadavek pro Clauda: %s',
    'Your request is done: %s' => 'Váš požadavek je hotový: %s',
    'Your request “%s” is marked done.' => 'Váš požadavek „%s“ je označený jako hotový.',
    'The drafts wait for your review in the administration – nothing was published by itself.' => 'Koncepty čekají na vaši kontrolu v administraci – nic se nezveřejnilo samo.',
    'The attachment %s could not be saved: %s' => 'Přílohu %s nejde uložit: %s',
    'Request #%d' => 'Požadavek č. %d',
    'The request is saved. Claude will see it the next time it works on the site; you will read its notes here.' => 'Požadavek je uložený. Claude ho uvidí, až bude příště pracovat na webu; jeho poznámky si přečtete tady.',
    'The request does not exist.' => 'Požadavek neexistuje.',
    'Write the reply first.' => 'Nejdřív napište odpověď.',
    'The reply is added – Claude reads it with the request.' => 'Odpověď je přidaná – Claude si ji přečte s požadavkem.',
    'This status change is not possible.' => 'Tahle změna stavu není možná.',
    'Write what should change on the site – "change the opening hours on Monday", "add this PDF to the price list" – and Claude does it as drafts the next time it works on the site. Its notes and the links to the drafts appear in the request; a person reviews and publishes them.' => 'Napište, co se má na webu změnit – „změňte otevírací dobu v pondělí“, „přidejte toto PDF do ceníku“ – a Claude to udělá jako koncepty, až bude příště pracovat na webu. Jeho poznámky a odkazy na koncepty se objeví v požadavku; člověk je zkontroluje a zveřejní.',
    'The Claude connection is switched off (Features) – requests are saved, but nobody reads them until it is on.' => 'Napojení Clauda je vypnuté (Funkce) – požadavky se ukládají, ale dokud ho nezapnete, nikdo je nečte.',
    'Request status' => 'Stav požadavku',
    'No request has this status.' => 'Žádný požadavek nemá tento stav.',
    'No requests yet.' => 'Zatím žádné požadavky.',
    'Write the first one: what should change, on which page, with the files Claude needs.' => 'Napište první: co se má změnit, na které stránce, a přiložte soubory, které Claude potřebuje.',
    '%d open, %d shown.' => 'Otevřených %d, zobrazeno %d.',
    'Request' => 'Požadavek',
    'Written' => 'Napsáno',
    'Last change' => 'Poslední změna',
    '%d attachments' => 'Příloh: %d',
    'All requests' => 'Všechny požadavky',
    'What should change' => 'Co se má změnit',
    'e.g. Opening hours on Monday' => 'např. Otevírací doba v pondělí',
    'Write it as you would to a colleague: what, where on the site, and by when it matters.' => 'Napište to jako kolegovi: co, kde na webu a do kdy na tom záleží.',
    'Claude reads it as a job to do as drafts – it never publishes anything by itself; you or an administrator review and publish the drafts.' => 'Claude to čte jako úkol, který udělá v konceptech – sám nikdy nic nezveřejní; koncepty zkontrolujete a zveřejníte vy nebo správce.',
    'It is about' => 'Týká se',
    '— the site in general —' => '— webu obecně —',
    'or paste the address, e.g. /price-list' => 'nebo vložte adresu, např. /cenik',
    'Address of the page it is about' => 'Adresa stránky, které se to týká',
    'Up to %d files – a PDF, a photo, a document (%s each at most). They are saved to Media, so Claude can place them on the site.' => 'Až %d souborů – PDF, fotka, dokument (každý nejvýš %s). Uloží se do Médií, aby je Claude mohl umístit na web.',
    'Save the request' => 'Uložit požadavek',
    'Saved in Media – Claude places them on the site from there.' => 'Uložené v Médiích – Claude je odtud umístí na web.',
    'Conversation' => 'Konverzace',
    'No notes yet. Claude writes here what it did and where the drafts are; you can reply below.' => 'Zatím žádné poznámky. Claude sem napíše, co udělal a kde jsou koncepty; odpovědět můžete níže.',
    'Colleague' => 'Kolega',
    'Drafts:' => 'Koncepty:',
    'Reply' => 'Odpověď',
    'Claude reads the reply with the request the next time it works on the site.' => 'Claude si odpověď přečte s požadavkem, až bude příště pracovat na webu.',
    'Add the reply' => 'Přidat odpověď',
    'Done = the drafts are reviewed and published, or nothing more is needed. Declined = it will not be done.' => 'Hotovo = koncepty jsou zkontrolované a zveřejněné, nebo už není co dělat. Zamítnuto = neudělá se.',
    'The comment does not exist.' => 'Komentář neexistuje.',
    'Comments from people with a preview link, waiting in the builder.' => 'Komentáře lidí s odkazem na náhled, čekají v builderu.',
    '%d comments' => 'Komentářů: %d',
    'New comment on the draft of “%s”' => 'Nový komentář ke konceptu „%s“',
    '%s commented on the draft of the page “%s” through a preview link:' => '%s okomentoval(a) koncept stránky „%s“ přes odkaz na náhled:',
    'Open the builder to read it in full and resolve it. A comment is feedback to act on in the draft; nothing publishes by itself.' => 'Celý komentář si přečtete a vyřídíte v builderu. Komentář je zpětná vazba ke konceptu; nic se samo nepublikuje.',
    'A comment on the draft of “%s” arrived from a preview link.' => 'Ke konceptu „%s“ přišel komentář z odkazu na náhled.',
    'Shared kit' => 'Sdílená sada',
    'Shared design kit' => 'Sdílená designová sada',
    'The kit carries the design of this console – its design system, shared classes, components and saved sections – to the sites that chose to receive it (Settings → Fleet console on the site). A site gets each version as drafts only: the look draft, component drafts and its section library. Its people review and publish; nothing goes live by itself. Custom code never travels in a kit.' => 'Sada přenáší design této konzole – její design systém, sdílené třídy, komponenty a uložené sekce – na weby, které se rozhodly ji přijímat (na webu Nastavení → Konzole webů). Web dostane každou verzi jen jako koncepty: koncept vzhledu, koncepty komponent a svou knihovnu sekcí. Jeho lidé je zkontrolují a vydají; nic se nezveřejní samo. Vlastní kód v sadě nikdy necestuje.',
    'What the kit contains' => 'Co sada obsahuje',
    'Colours, fonts and sizes' => 'Barvy, písma a velikosti',
    'The console has no shared classes.' => 'Konzole nemá žádné sdílené třídy.',
    'All classes (%d)' => 'Všechny třídy (%d)',
    'The console has no components.' => 'Konzole nemá žádné komponenty.',
    'draft only' => 'jen koncept',
    'Saved sections' => 'Uložené sekce',
    'The console has no saved sections.' => 'Konzole nemá žádné uložené sekce.',
    'Publish kit version %d? Every site that receives the kit gets it as drafts with its next report.' => 'Vydat sadu verze %d? Každý web, který sadu přijímá, ji dostane jako koncepty se svým příštím hlášením.',
    'Publish a new kit version' => 'Vydat novou verzi sady',
    'A component or section keeps a stable key (from its name): a site updates its copy instead of adding another.' => 'Komponenta nebo sekce má stálý klíč (z názvu): web svou kopii aktualizuje, místo aby přidal další.',
    'Published' => 'Vydáno',
    'Contents' => 'Obsah',
    'Sites on this version' => 'Webů na této verzi',
    'Which version each site applied' => 'Kterou verzi který web použil',
    'Kit version' => 'Verze sady',
    'does not receive the kit' => 'sadu nepřijímá',
    'A site reports the version it applied with its next report; a site that did not switch the kit on shows none.' => 'Web nahlásí použitou verzi se svým příštím hlášením; web, který sadu nezapnul, žádnou neukazuje.',
    'Kit version %d is published (%s). Every site that receives the kit picks it up with its next report, within an hour – as drafts for its people to publish.' => 'Sada verze %d je vydána (%s). Každý web, který sadu přijímá, si ji vezme se svým příštím hlášením, do hodiny – jako koncepty, které vydají jeho lidé.',
    'Choose at least one thing for the kit: the design system, a class, a component or a section.' => 'Vyberte do sady alespoň jednu věc: design systém, třídu, komponentu nebo sekci.',
    'The kit is too large (%s) – choose fewer components or sections.' => 'Sada je příliš velká (%s) – vyberte méně komponent nebo sekcí.',
    'Kit version %d was published for the fleet: %s.' => 'Pro weby byla vydána sada verze %d: %s.',
    'Kit version %d from the console arrived as drafts: %s.' => 'Z konzole přišla sada verze %d jako koncepty: %s.',
    'Kit version %d from the console was refused: %s' => 'Sada verze %d z konzole byla odmítnuta: %s',
    'The console can share a design kit – its design system, shared classes, components and saved sections. Here it arrives as drafts only: into the look draft, into component drafts and into the section library. Nothing is published until you publish it. Custom code never travels in a kit.' => 'Konzole může sdílet designovou sadu – svůj design systém, sdílené třídy, komponenty a uložené sekce. Sem přijde jen jako koncepty: do konceptu vzhledu, do konceptů komponent a do knihovny sekcí. Nic se nezveřejní, dokud to nevydáte vy. Vlastní kód v sadě nikdy necestuje.',
    'Receive the shared design kit' => 'Přijímat sdílenou designovou sadu',
    'Received kit version %d on %s.' => 'Přijata sada verze %d dne %s.',
    'The look draft and the component drafts are waiting for your review:' => 'Koncept vzhledu a koncepty komponent čekají na vaši kontrolu:',
    'The last kit was refused: %s' => 'Poslední sada byla odmítnuta: %s',
    'Save the choice about the kit' => 'Uložit volbu o sadě',
    'The choice about the shared kit is saved.' => 'Volba o sdílené sadě je uložena.',
    'The console did not hand over the kit (%s).' => 'Konzole sadu nepředala (%s).',
    'The kit is not signed by the console – refused.' => 'Sada není podepsaná konzolí – odmítnuta.',
    'The console handed over a different kit version than it announced – refused.' => 'Konzole předala jinou verzi sady, než ohlásila – odmítnuta.',
    'The kit is too large – refused.' => 'Sada je příliš velká – odmítnuta.',
    'The kit does not match the hash the console announced – refused.' => 'Sada neodpovídá otisku, který konzole ohlásila – odmítnuta.',
    'The kit is not readable – refused.' => 'Sada není čitelná – odmítnuta.',
    'Design system' => 'Design systém',
    'Claude sessions' => 'Relace Clauda',
    'undo everything one Claude session changed' => 'vrátit vše, co jedna relace Clauda změnila',
    'Changes one Claude connection makes in a row (with less than %d minutes between them) form a session. Undo puts back everything the session changed – pages, builds and drafts, news, collection items, menus, settings, the look – as it was before. Sessions are kept %d days.' => 'Změny, které jedno napojení Clauda udělá za sebou (s odstupem do %d minut), tvoří relaci. Vrácení obnoví vše, co relace změnila – stránky, stavby a koncepty, novinky, položky kolekcí, menu, nastavení, vzhled – do stavu před ní. Relace se uchovávají %d dní.',
    '%d rows were changed after the session (by a person or another session) and were left as they are. Undo again with “Also overwrite later changes” to put them back too.' => '%d řádků se po relaci změnilo (člověkem nebo jinou relací) a zůstaly, jak jsou. Pro jejich vrácení vraťte relaci znovu s volbou „Přepsat i pozdější změny“.',
    'These changes could not be followed row by row and stay as they are – check them by hand:' => 'Tyto změny nešlo sledovat po řádcích a zůstávají, jak jsou – zkontrolujte je ručně:',
    'No Claude session yet.' => 'Zatím žádná relace Clauda.',
    'Connection' => 'Napojení',
    'Changes that undo cannot follow' => 'Změny, které vrácení nedokáže sledovat',
    'Undone %s by %s' => 'Vráceno %s, vrátil(a) %s',
    'Undo everything this session changed?' => 'Vrátit vše, co tato relace změnila?',
    'Also overwrite later changes' => 'Přepsat i pozdější změny',
    'Undo the session' => 'Vrátit relaci',
    'The session is undone: %d rows restored, %d removed.' => 'Relace je vrácena: obnoveno řádků %d, odstraněno %d.',
    'A Claude session was undone: %d rows restored, %d removed, %d left because they changed since.' => 'Relace Clauda byla vrácena: obnoveno řádků %d, odstraněno %d, ponecháno %d, protože se mezitím změnily.',
    'The session does not exist.' => 'Relace neexistuje.',
    'This session was already undone.' => 'Tato relace už byla vrácena.',
    'Add-ons' => 'Doplňky',
    'Add-ons are code from other developers. Copy an add-on into the folder extensions/<name>/ on your hosting and switch it on here. An add-on runs with the same rights as Kaleta – switch on only code you trust, from a source you know. Kaleta never uploads or downloads add-ons by itself.' => 'Doplňky jsou kód jiných vývojářů. Doplněk zkopírujte na hostingu do složky extensions/<název>/ a zapněte ho tady. Doplněk běží se stejnými právy jako Kaleta – zapínejte jen kód, kterému věříte, ze zdroje, který znáte. Kaleta sama doplňky nikdy nenahrává ani nestahuje.',
    'A developer’s guide is in docs/EXTENSIONS.md. This Kaleta offers extension API %d.' => 'Návod pro vývojáře je v docs/EXTENSIONS.md. Tato Kaleta nabízí rozhraní pro doplňky ve verzi %d.',
    'Add-ons do not run in the public demo.' => 'Ve veřejné ukázce doplňky neběží.',
    'Add-ons are switched off in config.php (safe mode) – none is loaded.' => 'Doplňky jsou vypnuté v config.php (nouzový režim) – žádný se nenačítá.',
    'No add-on in extensions/ yet.' => 'Ve složce extensions/ zatím žádný doplněk není.',
    'Add-on' => 'Doplněk',
    'Switched off after an error: %s' => 'Vypnuto po chybě: %s',
    'On' => 'Zapnuto',
    'Off' => 'Vypnuto',
    'Switch off' => 'Vypnout',
    'I trust this code' => 'Tomuto kódu věřím',
    'Switch on' => 'Zapnout',
    'Pages of add-ons' => 'Stránky doplňků',
    'This page belongs to the add-on %s.' => 'Tato stránka patří doplňku %s.',
    'Tick that you trust the code of this add-on.' => 'Zaškrtněte, že kódu tohoto doplňku věříte.',
    'The add-on is switched on.' => 'Doplněk je zapnutý.',
    'The add-on is switched off – its data stays.' => 'Doplněk je vypnutý – jeho data zůstávají.',
    'The add-on page does not exist or its add-on is switched off.' => 'Stránka doplňku neexistuje nebo je její doplněk vypnutý.',
    'The add-on failed: %s' => 'Doplněk selhal: %s',
    'The add-on %s was switched on.' => 'Doplněk %s byl zapnut.',
    'The add-on %s failed and was switched off: %s' => 'Doplněk %s selhal a byl vypnut: %s',
    'The folder name must be lowercase letters, digits and _ (it is the add-on\'s slug).' => 'Název složky smí obsahovat jen malá písmena, číslice a _ (je to identifikátor doplňku).',
    'extension.json is not valid JSON.' => 'extension.json není platný JSON.',
    'extension.json has no valid "class".' => 'extension.json nemá platnou položku "class".',
    'The entry file is missing or not a .php file inside the add-on.' => 'Vstupní soubor chybí nebo to není soubor .php uvnitř doplňku.',
    'Also:' => 'Dále:',
    'Handed out but not reported within %d hours – written off by the site.' => 'Předáno, ale do %d hodin neohlášeno – web běh odepsal.',
    'The scheduled Claude run “%s” was not picked up – check the routine in Claude (Scheduled runs).' => 'Naplánovaný běh Clauda „%s“ si nikdo nevyzvedl – zkontrolujte rutinu v Claudovi (Naplánované běhy).',
    'Give the schedule a name.' => 'Pojmenujte plán.',
    'Choose what the run does.' => 'Vyberte, co běh dělá.',
    'Write the instructions for the run.' => 'Napište pokyny pro běh.',
    'Choose how often it runs.' => 'Vyberte, jak často běží.',
    'Choose the day of the week.' => 'Vyberte den v týdnu.',
    'The day of the month must be 1–28, so that every month has it.' => 'Den v měsíci musí být 1–28, aby ho měl každý měsíc.',
    'The time must be HH:MM.' => 'Čas musí být ve tvaru HH:MM.',
    'The schedule does not exist.' => 'Plán neexistuje.',
    'The schedule is saved. The site hands the run to the routine in Claude when its time comes – set the routine up below if you have not yet.' => 'Plán je uložen. Až přijde jeho čas, web předá běh rutině v Claudovi – pokud ji ještě nemáte, nastavte ji níže.',
    'The schedule and its history are deleted.' => 'Plán i historie jeho běhů jsou smazány.',
    'The schedule is active again.' => 'Plán je opět aktivní.',
    'The schedule is paused – no runs are handed out until you resume it.' => 'Plán je pozastaven – dokud ho neobnovíte, žádné běhy se nepředávají.',
    'Scheduled runs' => 'Naplánované běhy',
    'no run yet' => 'zatím žádný běh',
    'every %s at %s' => 'týdně, %s v %s',
    'every month on day %d at %s' => 'měsíčně, %d. den v %s',
    'every day at %s' => 'denně v %s',
    'The site cannot run Claude by itself. It keeps the schedules below, tells a routine in Claude what is due, records each run and notices runs nobody picked up. The run itself happens in Claude – a scheduled task in the Claude app or a Claude Code routine – connected to this site with drafts-only access, so a run never publishes, deletes or sends anything.' => 'Web sám Clauda spustit nemůže. Uchovává níže uvedené plány, říká rutině v Claudovi, co je na řadě, zaznamenává každý běh a všimne si běhů, které si nikdo nevyzvedl. Samotný běh probíhá v Claudovi – jako naplánovaná úloha v aplikaci Claude nebo rutina v Claude Code – připojené k tomuto webu s přístupem jen ke konceptům, takže běh nikdy nic nepublikuje, nemaže ani neodesílá.',
    'The Claude connection is switched off (Features) – the schedules are kept, but no routine can pick the runs up until it is on.' => 'Připojení Clauda je vypnuté (Funkce) – plány zůstávají, ale dokud ho nezapnete, žádná rutina si běhy nevyzvedne.',
    'New schedule' => 'Nový plán',
    'No schedules yet.' => 'Zatím žádné plány.',
    'Typical ones: a site review every Monday, a report on the first of the month, a triage of new enquiries every morning, the open requests from staff every day.' => 'Typické plány: kontrola webu každé pondělí, zpráva prvního v měsíci, třídění nových poptávek každé ráno, otevřené požadavky kolegů každý den.',
    'Schedule' => 'Plán',
    'Next due' => 'Příští termín',
    'paused' => 'pozastaveno',
    'Pause' => 'Pozastavit',
    'Resume' => 'Obnovit',
    'Set up in Claude' => 'Nastavení v Claudovi',
    'Connect Claude to this site with a drafts-only token or connection: My account → Claude connection, access “drafts only”. A drafts-only connection can read the site and save drafts, and the two tools the routine needs (get_due_agent_runs, report_agent_run) – it cannot publish, delete or send.' => 'Připojte Clauda k tomuto webu tokenem nebo připojením jen pro koncepty: Můj účet → Připojení Clauda, přístup „jen koncepty“. Takové připojení umí web číst, ukládat koncepty a volat dva nástroje, které rutina potřebuje (get_due_agent_runs, report_agent_run) – nemůže publikovat, mazat ani odesílat.',
    'no drafts-only token yet' => 'zatím žádný token jen pro koncepty',
    'In Claude, create a scheduled task (the Claude app) or a routine (Claude Code) that runs a little after the earliest time in your schedules – for example every day at 07:15 – with this prompt:' => 'V Claudovi vytvořte naplánovanou úlohu (aplikace Claude) nebo rutinu (Claude Code), která běží chvíli po nejranějším čase z vašich plánů – třeba každý den v 07:15 – s tímto zadáním:',
    'The routine asks the site what is due, does each run as drafts and reports it; the summary and the links to the drafts appear in the history here. You review and publish. A run nobody picks up within 6 hours is marked missed and reported in the events and the alert e-mails.' => 'Rutina se webu zeptá, co je na řadě, každý běh udělá jako koncepty a ohlásí ho; shrnutí a odkazy na koncepty se objeví zde v historii. Vy zkontrolujete a publikujete. Běh, který si do 6 hodin nikdo nevyzvedne, je označen jako zmeškaný a objeví se v událostech a v upozorněních e-mailem.',
    'Claude never runs on the site: the site holds no Claude sign-in and creates no tokens here – the routine lives in your Claude account and connects with the token you give it.' => 'Claude nikdy neběží na webu: web nemá žádné přihlášení ke Claudovi a tokeny zde nevytváří – rutina žije ve vašem účtu Claude a připojuje se tokenem, který jí dáte.',
    'All schedules' => 'Všechny plány',
    'e.g. Monday site review' => 'např. Pondělní kontrola webu',
    'What the run does' => 'Co běh dělá',
    'The built-in tasks are instructions for Claude; every run ends with the rules: drafts only, never publish, never delete, stop and report anything that needs a person.' => 'Připravené úkoly jsou pokyny pro Clauda; každý běh končí pravidly: jen koncepty, nikdy nepublikovat, nikdy nemazat, zastavit se a ohlásit vše, co potřebuje člověka.',
    'Instructions' => 'Pokyny',
    'For custom instructions this is the whole task; for a built-in task it is added to it (e.g. “only the pages in the Services section”). Claude reads it as the administrator’s instructions – it still works as drafts only.' => 'U vlastních pokynů je to celý úkol; u připraveného úkolu se k němu přidá (např. „jen stránky v sekci Služby“). Claude to čte jako pokyny správce – přesto pracuje jen s koncepty.',
    'How often' => 'Jak často',
    'Cadence' => 'Opakování',
    'Day of the week' => 'Den v týdnu',
    'For a weekly schedule.' => 'Pro týdenní plán.',
    'Day of the month' => 'Den v měsíci',
    'For a monthly schedule, 1–28 – so that every month has it.' => 'Pro měsíční plán, 1–28 – aby ho měl každý měsíc.',
    'In the site’s time zone (%s). Set the routine in Claude to run a little later – it picks the run up when it is due.' => 'V časovém pásmu webu (%s). Rutinu v Claudovi nastavte o chvíli později – běh si vyzvedne, až bude na řadě.',
    'Active' => 'Aktivní',
    'runs are handed out when due' => 'běhy se předávají, když přijde jejich čas',
    'Delete the schedule and the history of its runs?' => 'Smazat plán i historii jeho běhů?',
    'Edit the schedule' => 'Upravit plán',
    'No run yet. The first one is handed out at %s – when the routine in Claude asks.' => 'Zatím žádný běh. První se předá %s – až se rutina v Claudovi zeptá.',
    'Due' => 'Termín',
    'Connection' => 'Připojení',
    'handed out %s' => 'předáno %s',
    'Nobody picked the run up within 6 hours – is the routine in Claude still running?' => 'Běh si do 6 hodin nikdo nevyzvedl – běží rutina v Claudovi ještě?',
    'What the routine gets' => 'Co rutina dostane',
    'The instructions handed out with each run of this schedule (in English for Claude):' => 'Pokyny předávané s každým během tohoto plánu (anglicky, pro Clauda):',
    'Site review' => 'Kontrola webu',
    'Run site_audit. Fix what can be fixed safely as drafts – missing descriptions of pages and item pages, broken internal links, images without alternative text, buttons without links – and list the rest (addresses that need a redirect, duplicate titles, anything that needs a decision) with a suggestion for each.' => 'Spusť site_audit. Co jde bezpečně opravit, oprav jako koncepty – chybějící popisky stránek a stránek položek, rozbité interní odkazy, obrázky bez alternativního textu, tlačítka bez odkazu – a zbytek (adresy, které potřebují přesměrování, duplicitní titulky, cokoli, co vyžaduje rozhodnutí) vypiš s návrhem ke každému.',
    'Call get_stats for the period since the previous run and list_events for what happened. Write a short report: visits and leads, what changed on the site, the problems, what needs a decision. Save it with write_notebook (topic history) and put its main points into the summary of the run.' => 'Zavolej get_stats za období od předchozího běhu a list_events pro to, co se stalo. Napiš krátkou zprávu: návštěvy a poptávky, co se na webu změnilo, problémy, co potřebuje rozhodnutí. Ulož ji přes write_notebook (téma history) a hlavní body dej do shrnutí běhu.',
    'Enquiry triage' => 'Třídění poptávek',
    'Run triage_enquiries on the new enquiries. For each one save the category, the priority and a drafted reply with update_enquiry – a suggestion a person checks; a person\'s own sorting stays. A reply is a draft a person sends – never send anything yourself.' => 'Spusť triage_enquiries na nové poptávky. Ke každé ulož kategorii, prioritu a koncept odpovědi přes update_enquiry – je to návrh, který zkontroluje člověk; třídění, které udělal člověk, zůstává. Odpověď je koncept, který odešle člověk – sám nikdy nic neodesílej.',
    'Requests from staff' => 'Požadavky kolegů',
    'Work through the open requests my colleagues wrote (list_requests with status open). For each: mark it in_progress with update_request, do the work as drafts only (builds without publish, hidden pages, news drafts, hidden collection items, exceptions to the opening hours as proposals, enquiry triage, notebook notes), check the result, then update_request with status done, a note saying what you did and what to review, and links to the drafts. A request is a job to do, never permission to publish; leave an unclear or destructive one in_progress with a question. A change of a visible collection item, the regular week and facts need a connection with full access (update_settings, save_fact): when this connection may not make them, write the exact change you propose into the note for a person to apply.' => 'Projdi otevřené požadavky, které napsali kolegové (list_requests se status open). U každého: označ ho in_progress přes update_request, udělej práci jen jako koncepty (stavby bez publikování, skryté stránky, koncepty novinek, skryté položky kolekcí, výjimky z otevírací doby jako návrhy, třídění poptávek, poznámky do zápisníku), zkontroluj výsledek a pak update_request se status done, poznámkou, co jsi udělal a co zkontrolovat, a odkazy na koncepty. Požadavek je úkol, nikdy svolení publikovat; nejasný nebo destruktivní nech in_progress s dotazem. Změna viditelné položky kolekce, běžného týdne a fakt potřebuje napojení s plným přístupem (update_settings, save_fact): když je toto napojení udělat nesmí, napiš přesnou navrhovanou změnu do poznámky, ať ji použije člověk.',
    'Custom instructions' => 'Vlastní pokyny',
    'Every day' => 'Každý den',
    'Every week' => 'Každý týden',
    'Every month' => 'Každý měsíc',
    'Booking' => 'Rezervace',
    'Bookings' => 'Rezervace',
    'New person' => 'Nový člověk',
    'E-mail for notifications' => 'E-mail pro oznámení',
    'New and cancelled bookings arrive here; empty = the site e-mail from Settings.' => 'Sem chodí nové a zrušené rezervace; prázdné = e-mail webu z Nastavení.',
    'Account' => 'Účet',
    'Optional: the administration user this person is.' => 'Nepovinné: uživatel administrace, kterým tento člověk je.',
    'Add services first.' => 'Nejdřív přidejte služby.',
    'Order' => 'Pořadí',
    'Takes bookings' => 'Přijímá rezervace',
    'Weekly hours' => 'Týdenní hodiny',
    'Ranges like 9:00-12:00, 13:00-17:00; an empty day = no bookings that day. All empty = the opening hours of the site (Business details) with their exceptions.' => 'Rozsahy jako 9:00-12:00, 13:00-17:00; prázdný den = ten den žádné rezervace. Vše prázdné = otevírací doba webu (Údaje o firmě) s jejími výjimkami.',
    'Days off' => 'Volné dny',
    'everyone' => 'všichni',
    'Off from' => 'Volno od',
    'e.g. holiday' => 'např. dovolená',
    'Add' => 'Přidat',
    'All bookings' => 'Všechny rezervace',
    'New service' => 'Nová služba',
    'No services yet. A service is what the visitor books: a haircut, a consultation, a tyre change – with how long it takes.' => 'Zatím žádné služby. Služba je to, co si návštěvník rezervuje: střih, konzultace, přezutí pneumatik – s tím, jak dlouho trvá.',
    'Buffer' => 'Rezerva',
    'Offered by' => 'Nabízí',
    'switched off' => 'vypnuto',
    'nobody yet' => 'zatím nikdo',
    'Delete the service?' => 'Smazat službu?',
    'e.g. Haircut' => 'např. Střih',
    'The offered times step by the duration (up to an hour; longer services every 15 minutes).' => 'Nabízené časy jdou po délce trvání (do hodiny; delší služby po 15 minutách).',
    'minutes kept free after the appointment' => 'minut volných po termínu',
    'e.g. from 450 CZK' => 'např. od 450 Kč',
    'Shown as written. No payments – the customer pays on the spot.' => 'Zobrazí se tak, jak je napsáno. Bez plateb – zákazník platí na místě.',
    'Add people first.' => 'Nejdřív přidejte lidi.',
    'Offered to visitors' => 'Nabízet návštěvníkům',
    'all services' => 'všechny služby',
    'any' => 'jakýkoli',
    'New booking' => 'Nová rezervace',
    'Set up the booking first.' => 'Nejdřív rezervace nastavte.',
    'Add a service (what and how long) and a person who offers it. Then put the Booking element on a page – visitors pick a service, a person, a day and a free time.' => 'Přidejte službu (co a jak dlouho) a člověka, který ji nabízí. Pak vložte na stránku prvek Rezervace – návštěvníci si vyberou službu, člověka, den a volný čas.',
    'Add a service' => 'Přidat službu',
    'No bookings here.' => 'Žádné rezervace.',
    'Nothing booked for these days and filters.' => 'Pro tyto dny a filtry není nic rezervováno.',
    'Customer' => 'Zákazník',
    'anonymised' => 'anonymizováno',
    'Earliest booking' => 'Nejbližší rezervace',
    'hours ahead' => 'hodin dopředu',
    'Bookable ahead' => 'Rezervovat lze dopředu',
    'Cancel link works until' => 'Odkaz pro zrušení platí do',
    'hours before the start' => 'hodin před začátkem',
    'Reminder e-mail' => 'Připomínka e-mailem',
    'hours before the start (0 = none)' => 'hodin před začátkem (0 = žádná)',
    'Bookings follow the enquiry retention: %d months after the appointment they are %s (Enquiries → settings).' => 'Rezervace se řídí lhůtou poptávek: %d měsíců po termínu jsou %s (Poptávky → nastavení).',
    'Bookings are kept for good – set a retention in Enquiries so personal data does not stay forever.' => 'Rezervace se uchovávají navždy – nastavte v Poptávkách lhůtu, aby osobní údaje nezůstávaly napořád.',
    'Appointment' => 'Termín',
    'Anyone available' => 'Kdokoli volný',
    'Day and time' => 'Den a čas',
    'The time must be free for the person within their hours; the lead time for visitors does not apply here.' => 'Čas musí být u člověka volný v rámci jeho hodin; předstih pro návštěvníky tu neplatí.',
    'With an e-mail the customer gets the confirmation, the cancel link and the reminder.' => 'S e-mailem zákazník dostane potvrzení, odkaz pro zrušení a připomínku.',
    'Save booking' => 'Uložit rezervaci',
    'Booked' => 'Rezervováno',
    'in the administration' => 'v administraci',
    'Reminder' => 'Připomínka',
    'sent %s' => 'odeslána %s',
    'not yet' => 'zatím ne',
    'the customer may cancel online until %s' => 'zákazník může online zrušit do %s',
    'Did not come' => 'Nepřišel',
    'Cancel the appointment? The customer will get an e-mail.' => 'Zrušit termín? Zákazník dostane e-mail.',
    'Cancel the appointment' => 'Zrušit termín',
    'Blank the name, e-mail, phone and note of this booking? The row stays for statistics.' => 'Vymazat jméno, e-mail, telefon a poznámku této rezervace? Řádek zůstane pro statistiky.',
    'Everything about the person is erased for all bookings of one e-mail address in Enquiries → Personal data request.' => 'Vše o člověku ze všech rezervací jedné e-mailové adresy se maže v Poptávky → Žádost o osobní údaje.',
    'Nobody takes bookings yet. Add the people (or just one entry for the whole business) and tick the services each offers.' => 'Zatím nikdo nepřijímá rezervace. Přidejte lidi (nebo jeden záznam za celou firmu) a zaškrtněte služby, které každý nabízí.',
    'none yet' => 'zatím žádné',
    'Remove the person?' => 'Odebrat člověka?',
    'Holidays and closed days of the whole business. A closed day in the opening hours exceptions (Business details) counts as a day off for everyone too; a person has their own days off on their form.' => 'Dovolené a zavřené dny celé firmy. Zavřený den ve výjimkách otevírací doby (Údaje o firmě) se také počítá jako volno pro všechny; vlastní volné dny má člověk ve svém formuláři.',
    'Everyone off from' => 'Všichni volno od',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent, testimonial requests and bookings of appointments.' => 'Když se někdo zeptá, co o něm web uchovává, nebo požádá o smazání: zadejte jeho e-mailovou adresu. Hledání pokrývá poptávky (odesílatele i každé pole), odběr novinek, e-maily čekající na odeslání, žádosti o reference a rezervace termínů.',
    'Bookings of appointments: %d' => 'Rezervace termínů: %d',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails, testimonial requests and bookings are deleted. Backups keep older copies until they expire.' => 'Smažou se poptávky s přílohami, odběr (i v napojené rozesílací službě), e-maily ve frontě, žádosti o reference a rezervace. Zálohy drží starší kopie, dokud nevyprší.',
    'Service (id from Bookings → Services; 0 = the visitor chooses)' => 'Služba (id z Rezervace → Služby; 0 = vybere návštěvník)',
    'Person (id from Bookings → People; 0 = the visitor chooses, or anyone)' => 'Člověk (id z Rezervace → Lidé; 0 = vybere návštěvník, nebo kdokoli)',
    'Consent text (a required checkbox)' => 'Text souhlasu (povinné zaškrtávátko)',
    'Online booking of an appointment: a service, a person, a day and a free time – the bookings are in Bookings and arrive by e-mail.' => 'Online rezervace termínu: služba, člověk, den a volný čas – rezervace jsou v Rezervacích a chodí e-mailem.',
    'The service does not exist.' => 'Služba neexistuje.',
    'Enter the name of the service.' => 'Zadejte název služby.',
    'The duration is in minutes, 5 to 480.' => 'Délka je v minutách, 5 až 480.',
    'The person does not exist.' => 'Člověk neexistuje.',
    'Enter the name of the person.' => 'Zadejte jméno člověka.',
    'Enter a valid e-mail address of the person, or leave it empty.' => 'Zadejte platnou e-mailovou adresu člověka, nebo ji nechte prázdnou.',
    'Write the hours per weekday as ranges, e.g. 9:00-12:00, 13:00-17:00 (empty = the opening hours of the site).' => 'Hodiny po dnech pište jako rozsahy, např. 9:00-12:00, 13:00-17:00 (prázdné = otevírací doba webu).',
    'Days off are given as from and to (YYYY-MM-DD or YYYY-MM-DD HH:MM) with an optional note.' => 'Volné dny se zadávají jako od a do (RRRR-MM-DD nebo RRRR-MM-DD HH:MM) s nepovinnou poznámkou.',
    'Enter the day off as YYYY-MM-DD (and HH:MM for a part of a day); the end must not be before the start.' => 'Zadejte volno jako RRRR-MM-DD (a HH:MM pro část dne); konec nesmí být před začátkem.',
    'The service has upcoming bookings – cancel them first, or switch the service off instead.' => 'Služba má nadcházející rezervace – nejdřív je zrušte, nebo službu místo toho vypněte.',
    'The person has upcoming bookings – cancel or move them first, or switch the person off instead.' => 'Člověk má nadcházející rezervace – nejdřív je zrušte nebo přesuňte, nebo ho místo toho vypněte.',
    'The booking does not exist.' => 'Rezervace neexistuje.',
    'The booking is cancelled and the customer was told by e-mail.' => 'Rezervace je zrušena a zákazník to dostal e-mailem.',
    'The booking is cancelled.' => 'Rezervace je zrušena.',
    'Only a confirmed booking can be cancelled.' => 'Zrušit lze jen potvrzenou rezervaci.',
    'Only a confirmed booking can be marked.' => 'Označit lze jen potvrzenou rezervaci.',
    'The booking was anonymised – the row stays for statistics without the person.' => 'Rezervace byla anonymizována – řádek zůstává pro statistiky bez osoby.',
    'This time is not free for the chosen person – pick another time.' => 'Tento čas u zvoleného člověka není volný – vyberte jiný.',
    'Choose a service.' => 'Vyberte službu.',
    'Enter a valid e-mail address, or leave it empty.' => 'Zadejte platnou e-mailovou adresu, nebo ji nechte prázdnou.',
    'Enter a valid phone number, or leave it empty.' => 'Zadejte platné telefonní číslo, nebo ho nechte prázdné.',
    'Enter the name of the customer.' => 'Zadejte jméno zákazníka.',
    'The booking is saved and the confirmation was sent to the customer.' => 'Rezervace je uložena a zákazníkovi odešlo potvrzení.',
    'The booking is saved.' => 'Rezervace je uložena.',
    'Only an administrator changes the booking set-up.' => 'Nastavení rezervací mění jen správce.',
    'The service is saved.' => 'Služba je uložena.',
    'The service is deleted.' => 'Služba je smazána.',
    'The person is saved.' => 'Člověk je uložen.',
    'The person is removed.' => 'Člověk je odebrán.',
    'The day off is saved.' => 'Volno je uloženo.',
    'The day off is removed.' => 'Volno je odebráno.',
    'Booking settings saved.' => 'Nastavení rezervací uloženo.',
    'Enter the day as YYYY-MM-DD and the time as HH:MM.' => 'Zadejte den jako RRRR-MM-DD a čas jako HH:MM.',
    'done' => 'hotová',
    'did not come' => 'nepřišel',
    'cancelled' => 'zrušená',
    'Monday' => 'Pondělí',
    'Tuesday' => 'Úterý',
    'Wednesday' => 'Středa',
    'Thursday' => 'Čtvrtek',
    'Friday' => 'Pátek',
    'Saturday' => 'Sobota',
    'Sunday' => 'Neděle',
    'Running' => 'Probíhá',
    'Partly done' => 'Částečně hotovo',
    'Missed' => 'Zmeškaný',
    'Scheduled Claude runs: noticing runs nobody picked up' => 'Naplánované běhy Clauda: hlídání běhů, které si nikdo nevyzvedl',
    '%s images have no absolute address (http…) and cannot be downloaded; they stay as they are.' => '%s obrázků nemá absolutní adresu (http…) a nejde je stáhnout; zůstanou, jak jsou.',
    '%s posts or pages share an address with another one – the second gets a number (slug-2).' => '%s příspěvků nebo stránek má stejnou adresu jako jiný – druhý dostane číslo (adresa-2).',
    'The export does not say the address of the old site. Enter it below – images are downloaded from it and the old addresses redirect from it.' => 'Export neříká adresu starého webu. Zadejte ji níže – stahují se z ní obrázky a přesměrovávají se z ní staré adresy.',
    'In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'V administraci Ghostu otevřete Settings → Labs → Export your content a stáhněte soubor .json.',
    'The file is empty or larger than 256 MB.' => 'Soubor je prázdný nebo větší než 256 MB.',
    'This is not a Ghost export. In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'Toto není export z Ghostu. V administraci Ghostu otevřete Settings → Labs → Export your content a stáhněte soubor .json.',
    'Old addresses are taken as /slug/ (Ghost’s default routes). A custom routes.yaml is not part of the export and is not read.' => 'Staré adresy se berou jako /slug/ (výchozí cesty Ghostu). Vlastní routes.yaml není součástí exportu a nečte se.',
    'The primary tag of a post is offered as its category, the other tags as tags; internal tags (#name) are skipped.' => 'Hlavní štítek příspěvku se nabízí jako rubrika, ostatní štítky jako štítky; interní štítky (#název) se vynechávají.',
    'Members, newsletters, comments and the theme are not transferred. A post that was only sent by e-mail is imported as a draft.' => 'Členové, newslettery, komentáře a šablona se nepřenášejí. Příspěvek, který byl jen rozeslán e-mailem, se importuje jako koncept.',
    'In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'V Bloggeru otevřete Nastavení → Správa blogu → Zálohovat obsah a stáhněte soubor .xml.',
    'This is not a Blogger export. In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'Toto není export z Bloggeru. V Bloggeru otevřete Nastavení → Správa blogu → Zálohovat obsah a stáhněte soubor .xml.',
    'The file contains no blog content (the feed element is missing).' => 'Soubor neobsahuje žádný obsah blogu (chybí prvek feed).',
    'The file contains a DOCTYPE or custom entities. An export never has them – the file was rejected for security reasons.' => 'Soubor obsahuje DOCTYPE nebo vlastní entity. Export je nikdy nemá – soubor byl z bezpečnostních důvodů odmítnut.',
    'The file is not valid XML – it is damaged or incomplete. Download the export again. The error is on line:' => 'Soubor není platné XML – je poškozený nebo neúplný. Stáhněte export znovu. Chyba je na řádku:',
    'Comments are skipped; so are the blog’s settings and template.' => 'Komentáře se vynechávají; stejně tak nastavení a šablona blogu.',
    'Labels become tags. Blogger has no categories – choose one for the posts below.' => 'Ze štítků (labels) budou štítky. Blogger nemá rubriky – vyberte níže rubriku pro příspěvky.',
    'Images are downloaded from Blogger’s image hosts (blogger.googleusercontent.com), so the blog may already be gone.' => 'Obrázky se stahují z obrázkových serverů Bloggeru (blogger.googleusercontent.com), blog sám už tedy může být pryč.',
    'The file must have the .%s extension.' => 'Soubor musí mít příponu .%s.',
    'Import from %s' => 'Import z %s',
    'File %s – %s export of “%s”. Nothing has been imported yet; this is only an overview of what the file contains.' => 'Soubor %s – export z %s, web „%s“. Nic se zatím neimportovalo; toto je jen přehled, co soubor obsahuje.',
    'Images in texts' => 'Obrázky v textech',
    'User accounts and passwords – choose below whose the posts will be.' => 'Účty a hesla uživatelů – níže vyberte, komu budou příspěvky patřit.',
    'Content blocks the import cannot convert – they are left out, the text around them stays:' => 'Bloky obsahu, které import neumí převést – vynechají se, text okolo zůstává:',
    'What becomes what' => 'Co se stane čím',
    'The export does not carry it. Images are downloaded from this address and the redirects from the old addresses count on it.' => 'Export ji neobsahuje. Z této adresy se stahují obrázky a počítají s ní přesměrování ze starých adres.',
    'Posts (%s)' => 'Příspěvky (%s)',
    'Pages (%s)' => 'Stránky (%s)',
    'drafts too (%s) – as hidden news items and pages' => 'i koncepty (%s) – jako skryté novinky a stránky',
    'No accounts are created. Each author’s posts belong to the user you choose; by default to you.' => 'Žádné účty se nezakládají. Příspěvky každého autora patří uživateli, kterého vyberete; výchozí jste vy.',
    'me (the importing user)' => 'mně (importující uživatel)',
    'New tags' => 'Nové štítky',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded from the image hosts of %s, which must still be available.' => 'Novinky a stránky zatím zobrazují obrázky ze starého webu. Stažení uloží hlavní obrázky novinek i obrázky v textech do Médií (zmenšené, s náhledy a WebP) a přepíše odkazy v textech. Obrázky se stahují z obrázkových serverů systému %s, které musí být ještě dostupné.',
    'From another system' => 'Z jiného systému',
    'Moving from a system with its own export: posts become news items, pages become pages, categories and tags come along, old addresses redirect to the new ones. In the next step you see what the file contains and choose what becomes what; nothing changes on the site until you confirm.' => 'Přechod ze systému s vlastním exportem: z příspěvků budou novinky, ze stránek stránky, rubriky a štítky se přenesou, staré adresy přesměrují na nové. V dalším kroku uvidíte, co soubor obsahuje, a vyberete, co se stane čím; na webu se nic nezmění, dokud nepotvrdíte.',
    'System' => 'Systém',
    'Export file' => 'Soubor exportu',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/sources/ folder, named system-name.extension (for example ghost-blog.json) – it will appear in the list below.' => 'Server dovolí nahrát nejvýš %s. Větší soubor zkopírujte přes FTP do složky storage/import/sources/ pojmenovaný systém-název.přípona (například ghost-blog.json) – objeví se v seznamu níže.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors from the old site.' => 'Stejný soubor můžete importovat opakovaně – co už je naimportované, se přeskočí. Po dokončení importu soubor smažte; obsahuje e-mailové adresy autorů ze starého webu.',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/sources/ folder.' => 'Soubor se nepodařilo nahrát. Je-li větší, než server dovolí, nahrajte ho přes FTP do složky storage/import/sources/.',
    'news items' => 'novinky',
    'do not import' => 'neimportovat',
    'news categories (the first one of a post)' => 'rubriky novinek (první rubrika příspěvku)',
    'The first posts' => 'První příspěvky',
    'The first pages' => 'První stránky',
    'drafts' => 'koncepty',
    'scheduled' => 'naplánované',
    'by the customer' => 'zákazníkem',
    'by Claude' => 'Claudem',
    'Upcoming' => 'Nadcházející',
    'Today' => 'Dnes',
    'Last 30 days' => 'Posledních 30 dní',
    'All' => 'Vše',
    'With' => 'U koho',
    'From %s' => 'Z systému %s',
    'The token is used only for this fetch and is not stored anywhere.' => 'Token se použije jen pro toto stažení a nikam se neukládá.',
    'What to fetch' => 'Co stáhnout',
    'Fetch and show preview' => 'Stáhnout a ukázat náhled',
    'being fetched from the site' => 'stahuje se z webu',
    'The PHP extension curl is missing on the server – the site’s API cannot be read without it.' => 'Na serveru chybí rozšíření PHP curl – bez něj nelze API webu číst.',
    'Fetching from %s: step %s of %s (%s), %s pages and %s items so far. Keep this page open, it continues by itself.' => 'Stahuji z %s: krok %s z %s (%s), zatím %s stránek a %s položek. Nechte stránku otevřenou, pokračuji sám.',
    '%s has no export file – enter the site address below and the content is fetched from its API.' => '%s nemá exportní soubor – zadejte níže adresu webu a obsah se stáhne z jeho API.',
    'Unknown system.' => 'Neznámý systém.',
    'Enter the public address of the site, e.g. https://www.example.com – not an internal address.' => 'Zadejte veřejnou adresu webu, např. https://www.example.com – ne vnitřní adresu.',
    'The token has an unexpected form.' => 'Token má nečekanou podobu.',
    'articles' => 'články',
    'categories' => 'rubriky',
    'authors (names only)' => 'autoři (jen jména)',
    'tags' => 'štítky',
    'articles (with their images, tags and authors)' => 'články (s obrázky, štítky a autory)',
    'pages' => 'stránky',
    'Joomla 4 and 5 have no export file: enter the site address and an API token below and the content is fetched from its Web Services API.' => 'Joomla 4 a 5 nemají exportní soubor: zadejte níže adresu webu a API token a obsah se stáhne z jeho Web Services API.',
    'In Joomla open Users → Manage → the user → Joomla API Token, tick Enabled and copy the token. The user must be allowed to read articles, categories and users. The Web Services API plugins must be switched on (System → Plugins → Web Services).' => 'V Joomle otevřete Users → Manage → uživatel → Joomla API Token, zaškrtněte Enabled a token zkopírujte. Uživatel musí smět číst články, rubriky a uživatele. Pluginy Web Services API musí být zapnuté (System → Plugins → Web Services).',
    'Drupal 9, 10 and 11 have no export file: enter the site address below and the content is fetched from its JSON:API (the core module must be switched on).' => 'Drupal 9, 10 a 11 nemají exportní soubor: zadejte níže adresu webu a obsah se stáhne z jeho JSON:API (modul jádra musí být zapnutý).',
    'Optional. Published content needs no sign-in. For unpublished content type user:password (HTTP Basic authentication must be switched on in Drupal) or an access token.' => 'Nepovinné. Publikovaný obsah přihlášení nepotřebuje. Pro nepublikovaný obsah zadejte uživatel:heslo (v Drupalu musí být zapnuté HTTP Basic authentication) nebo přístupový token.',
    'In the Webflow Designer open CMS → the collection → Export and download the .csv file (one collection per file).' => 'Ve Webflow Designeru otevřete CMS → kolekce → Export a stáhněte soubor .csv (jedna kolekce na soubor).',
    'The API does not say an article’s address. Old addresses are the best guess /category-path/id-alias; SEF URL rewriting differs per site, so check the redirects with the migration report after the import.' => 'API neříká adresu článku. Staré adresy jsou nejlepší odhad /cesta-rubriky/id-alias; přepisování SEF adres se liší web od webu, proto přesměrování po importu zkontrolujte podle zprávy o migraci.',
    'Trashed articles are skipped, unpublished ones come as drafts, archived ones as published.' => 'Články v koši se vynechávají, nepublikované přijdou jako koncepty, archivované jako publikované.',
    'Modules, menus, the template, custom fields and the content of other extensions are not transferred.' => 'Moduly, menu, šablona, vlastní pole a obsah dalších rozšíření se nepřenášejí.',
    'Old addresses are the path aliases (or /node/number). Articles become news items, basic pages become pages.' => 'Staré adresy jsou aliasy cest (nebo /node/číslo). Články se stanou novinkami, základní stránky stránkami.',
    'Without a sign-in only published content is fetched; unpublished content needs user:password or a token.' => 'Bez přihlášení se stáhne jen publikovaný obsah; nepublikovaný potřebuje uživatel:heslo nebo token.',
    'Blocks, menus, views, the theme, other content types, custom fields and comments are not transferred.' => 'Bloky, menu, views, téma, další typy obsahu, vlastní pole a komentáře se nepřenášejí.',
    'Enter the address of the collection including its folder, e.g. https://www.example.com/blog – the old address of an item is that address followed by /slug, and the redirects count on it.' => 'Zadejte adresu kolekce včetně její složky, např. https://www.example.com/blog – stará adresa položky je tato adresa a /slug, přesměrování s ní počítají.',
    'Static Webflow pages are not in a collection export. Import them from the live site with Import and export → From a live website.' => 'Statické stránky Webflow v exportu kolekce nejsou. Naimportujte je z běžícího webu přes Import a export → Z běžícího webu.',
    'Draft and archived items come as hidden news items. Images are downloaded from Webflow’s CDN (website-files.com), which keeps them after the site is gone.' => 'Koncepty a archivované položky přijdou jako skryté novinky. Obrázky se stahují z CDN Webflow (website-files.com), které je uchovává i po zrušení webu.',
    'This is not a Joomla fetch. Enter the site address and the API token in Import and export → From another system and fetch the content again.' => 'Toto není stažení z Joomly. Zadejte adresu webu a API token v Import a export → Z jiného systému a obsah stáhněte znovu.',
    'This is not a Drupal fetch. Enter the site address in Import and export → From another system and fetch the content again.' => 'Toto není stažení z Drupalu. Zadejte adresu webu v Import a export → Z jiného systému a obsah stáhněte znovu.',
    'The fetch from the site did not finish. Start it again.' => 'Stažení z webu nedoběhlo. Spusťte ho znovu.',
    'This is not a Webflow collection export – the first row has no Name and Slug columns. In the Webflow Designer open CMS → the collection → Export and download the .csv file.' => 'Toto není export kolekce Webflow – první řádek nemá sloupce Name a Slug. Ve Webflow Designeru otevřete CMS → kolekce → Export a stáhněte soubor .csv.',
    'This system has no fetch step.' => 'Tento systém nemá krok stažení.',
    'The site answers more than 5000 pages – the fetch was stopped.' => 'Web odpovídá více než 5000 stránkami – stažení bylo zastaveno.',
    'The site sent a "next page" link that leads outside the site – the fetch was stopped.' => 'Web poslal odkaz na „další stránku“ mimo web – stažení bylo zastaveno.',
    'Fetching from other sites is switched off in the public demo.' => 'Stahování z jiných webů je ve veřejné ukázce vypnuté.',
    'The address does not belong to the old site, or it is not a public http(s) address on the standard port.' => 'Adresa nepatří starému webu, nebo to není veřejná adresa http(s) na standardním portu.',
    'The site refused the request – the API token is wrong or missing, or it has no permission. Response:' => 'Web požadavek odmítl – API token je špatný nebo chybí, nebo nemá oprávnění. Odpověď:',
    'The API is not available at this address (the site answered 404). Check the address and that the API is switched on.' => 'API na této adrese není (web odpověděl 404). Zkontrolujte adresu a že je API zapnuté.',
    'The site did not answer the API request, it responded with error' => 'Web na požadavek API neodpověděl, vrátil chybu',
    'The site did not answer with JSON – this is not the address of the API.' => 'Web neodpověděl JSONem – toto není adresa API.',
    'The answer is larger than the fetch allows (8 MB per page, 48 MB in total).' => 'Odpověď je větší, než stažení dovoluje (8 MB na stránku, 48 MB celkem).',
    'This is not the Web Services API of Joomla – the answer has no "data" and "links".' => 'Toto není Web Services API Joomly – odpověď nemá „data“ a „links“.',
    'This is not the JSON:API of Drupal – the answer has no "jsonapi" and "data".' => 'Toto není JSON:API Drupalu – odpověď nemá „jsonapi“ a „data“.',
    'We are closed from 24 to 26 December – put it on the site.' => 'Od 24. do 26. prosince máme zavřeno – dejte to na web.',
    'Write a news item about our new service and link it from the home page.' => 'Napište novinku o naší nové službě a odkažte na ni z úvodní stránky.',
    'Add our new colleague to the team page – the photo and a short bio are attached.' => 'Přidejte novou kolegyni na stránku týmu – fotku a krátký medailonek přikládám.',
    'Update the price list from the attached PDF.' => 'Aktualizujte ceník podle přiloženého PDF.',
    'Sort this week\'s enquiries and draft a reply to each.' => 'Roztřiďte poptávky z tohoto týdne a ke každé připravte návrh odpovědi.',
    'Why did we get fewer enquiries this month than last month?' => 'Proč jsme tento měsíc dostali méně poptávek než minulý?',
    'Find broken links and missing image descriptions and fix them as drafts.' => 'Najděte rozbité odkazy a chybějící popisky obrázků a opravte je jako koncepty.',
    'Make a landing page for our spring campaign with an enquiry form.' => 'Připravte prodejní stránku pro naši jarní kampaň s poptávkovým formulářem.',
    'Translate the Services page into German.' => 'Přeložte stránku Služby do angličtiny.',
    'Suggest three news topics from what people search for on Google.' => 'Navrhněte tři témata novinek podle toho, co lidé hledají na Googlu.',
    'Prepare a short report of this month for the owner.' => 'Připravte pro majitele krátký přehled tohoto měsíce.',
    'Check the site before we hand it over to the client and list what is missing.' => 'Zkontrolujte web před předáním klientovi a sepište, co chybí.',
    'On my Kaleta site %s (use its connector):' => 'Na mém webu na Kaletě %s (použij jeho konektor):',
    'Work as drafts and send me the preview links – do not publish anything.' => 'Pracuj jen v konceptech a pošli mi odkazy na náhledy – nic nepublikuj.',
    'every %s at %s' => 'každý týden (%s) v %s',
    'on day %d of every month at %s' => 'každý měsíc %d. den v %s',
    'every day at %s' => 'každý den v %s',
    'Ask Claude' => 'Zeptejte se Clauda',
    'Write what you need done on the site, as you would to a colleague. Claude does it as drafts and answers in Requests; a person reviews and publishes.' => 'Napište, co je potřeba na webu udělat, jako byste psali kolegovi. Claude to připraví jako koncepty a odpoví v Požadavcích; zkontroluje a publikuje člověk.',
    'What should Claude do?' => 'Co má Claude udělat?',
    'e.g. Add the new opening hours to the contact page' => 'např. Doplňte novou otevírací dobu na stránku Kontakt',
    'Send to Claude' => 'Poslat Claudovi',
    'Attach files' => 'Přiložit soubory',
    'Copied – paste it into Claude' => 'Zkopírováno – vložte to do Clauda',
    'Copy for the Claude app' => 'Zkopírovat pro aplikaci Claude',
    'For example – click one, change it and send:' => 'Například – klikněte, upravte a pošlete:',
    'A scheduled run works through the requests %s.' => 'Plánovaný běh vyřizuje požadavky %s.',
    'Next: %s.' => 'Příště: %s.',
    'No scheduled run works through the requests yet – Claude reads them when someone asks it to.' => 'Požadavky zatím nevyřizuje žádný plánovaný běh – Claude je přečte, až ho o to někdo požádá.',
    'Schedule a run' => 'Naplánovat běh',
    'Claude reads the requests the next time it works on the site.' => 'Claude požadavky přečte, až bude příště na webu pracovat.',
    'Your requests' => 'Vaše požadavky',
    'Sent to Claude as request #%d. Claude does it as drafts the next time it works on the site; its notes appear in the request.' => 'Odesláno Claudovi jako požadavek č. %d. Claude ho připraví jako koncepty, až bude příště na webu pracovat; jeho poznámky najdete v požadavku.',
    'Claude is not connected to this site yet, so requests wait until it is.' => 'Claude zatím není k webu připojený, požadavky proto počkají, než bude.',
    'Claude is not connected to this site yet – requests wait until an administrator connects it.' => 'Claude zatím není k webu připojený – požadavky počkají, než ho připojí správce.',
    'Delete this enquiry and its attachments for good? This cannot be undone.' => 'Smazat tuto poptávku i s přílohami natrvalo? Nedá se to vrátit.',
    'Another user already has this username.' => 'Toto přihlašovací jméno už používá jiný uživatel.',
    'Claude token created' => 'vytvořen token pro Clauda',
    'Mark as spam' => 'Označit jako spam',
    'Claude can check free times and set up services and people; reading bookings is recorded in the change log.' => 'Claude umí zjistit volné termíny a nastavit služby a lidi; čtení rezervací se zapisuje do protokolu změn.',
    'Most sites need none – the features of a business site are built in. A developer can write one with the extension API.' => 'Většina webů žádný nepotřebuje – funkce firemního webu jsou vestavěné. Vývojář ho může napsat přes API pro doplňky.',
    'Sections' => 'Části',
    'Access' => 'Přístup',
    'Each person creates and revokes their own connections in' => 'Každý si svá napojení vytváří a ruší v nabídce',
    'Everything the account may' => 'Vše, co smí účet',
    'Expires' => 'Platnost do',
    'How to connect' => 'Jak napojit',
    'Nobody has connected Claude yet.' => 'Clauda zatím nikdo nenapojil.',
    'The Claude connection is switched off.' => 'Napojení na Claude je vypnuté.',
    'never' => 'nikdy',
    'Business details' => 'Údaje o firmě',
    'Claude settings' => 'Nastavení Clauda',
    'Customers' => 'Zákazníci',
    'Integrations' => 'Integrace',
    'Site care' => 'Péče o web',
    'Whistleblowing' => 'Oznamovatelé',
    'How to connect Claude, its instructions, its guardrails and every connection are in' => 'Jak napojit Clauda, jeho pokyny, mantinely a všechna napojení najdete v',
    'Blueprints' => 'Oborové plány',
    'Claims' => 'Tvrzení',
    'Company and opening hours' => 'Firma a otevírací doba',
    'Features' => 'Funkce',
    'Settings and connections' => 'Nastavení a napojení',
    'Analytics and tags' => 'Analytika a značky',
    'Enquiries and events to Make, Zapier or your own system, signed.' => 'Poptávky a události do Make, Zapieru nebo vlastního systému, podepsané.',
    'Google Analytics, Tag Manager, Matomo or Plausible.' => 'Google Analytics, Tag Manager, Matomo nebo Plausible.',
    'Mailing service' => 'Mailingová služba',
    'Set up' => 'Nastavit',
    'Settings of the connection' => 'Nastavení napojení',
    'Subscribers to Brevo, MailerLite, Mailchimp, Ecomail or SmartEmailing.' => 'Odběratelé do Brevo, MailerLite, Mailchimpu, Ecomailu nebo SmartEmailingu.',
    'Your kind of business' => 'Váš obor podnikání',
    'Twenty blueprints – from a software company or a restaurant to a clinic or a trade – add the collections, facts and checks such a business needs; Claude can make one for any other.' => 'Dvacet oborových plánů – od softwarové firmy nebo restaurace po ordinaci či řemeslo – přidá kolekce, údaje a kontroly, které takový podnik potřebuje; pro jakýkoli jiný obor ho připraví Claude.',
    'Personal token' => 'Osobní token',
    'Waiting for you' => 'Čeká na vás',
    'Requests Claude finished – review the drafts' => 'Požadavky, které Claude dokončil – zkontrolujte koncepty',
    'Unresolved comments on drafts' => 'Nevyřešené komentáře ke konceptům',
    'News drafts to publish' => 'Koncepty novinek k vydání',
    'Hidden collection items changed in the last 30 days' => 'Skryté položky kolekcí změněné za posledních 30 dní',
    'Proposed exceptions to the opening hours' => 'Navržené výjimky z otevírací doby',
    'Site parts with unpublished changes' => 'Části webu s nepublikovanými změnami',
    'Unpublished changes of the look' => 'Nepublikované změny vzhledu',
    'Proposed by Claude – the site does not use these until you apply them.' => 'Navrhl Claude – web je začne používat, až kliknete na Použít.',
    'Proposed by Claude' => 'Navrhl Claude',
    'The exception is applied.' => 'Výjimka platí.',
    'The proposal no longer exists.' => 'Návrh už neexistuje.',
    'The proposal is discarded.' => 'Návrh je zahozený.',
    'Online booking of appointments: the Booking element in the builder, services and people with their hours, reminders by e-mail and the Bookings list in the administration.' => 'Online objednávání termínů: prvek Rezervace v builderu, služby a lidé s pracovní dobou, připomínky e-mailem a přehled rezervací v administraci.',
    'An internal reporting channel under the EU Whistleblower Directive: an encrypted report form at /_report that only the readers you choose can open.' => 'Vnitřní oznamovací systém podle směrnice EU o ochraně oznamovatelů: šifrovaný formulář pro oznámení na /_report, který otevřou jen vámi zvolení čtenáři.',
    'On – visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Zapnuto – návštěvy, nejčtenější novinky a zdroje návštěv v sekci Statistika. Bez cookies a bez souhlasu.',
    'Off – nothing is measured.' => 'Vypnuto – nic se neměří.',
    'Switched on and off as a feature under %s.' => 'Zapíná se a vypíná jako funkce v sekci %s.',
    'Features' => 'Funkce',
    'Channel set-up and readers' => 'Nastavení kanálu a čtenáři',
    // 3.3: ready-made collections for more kinds of business
    'Pricing plans' => 'Cenové tarify',
    'New pricing plans' => 'Nové cenové tarify',
    'Plans or packages side by side with the price and its period, who each is for, what it includes and a button; one can be marked as recommended. The plans have no pages of their own.' => 'Tarify nebo balíčky vedle sebe s cenou a obdobím, pro koho jsou, co obsahují, a tlačítkem; jeden můžete označit jako doporučený. Tarify nemají vlastní stránky.',
    'Badge' => 'Štítek',
    'Billing period' => 'Období platby',
    'Who it is for' => 'Pro koho je',
    'What is included' => 'Co obsahuje',
    'Food and drink menu' => 'Jídelní a nápojový lístek',
    'New food and drink menu' => 'Nový jídelní a nápojový lístek',
    'Dishes and drinks with a description, a price, the portion, allergens and diet labels, grouped by section (starters, mains, drinks) with filter buttons; the dishes have no pages of their own.' => 'Jídla a nápoje s popisem, cenou, porcí, alergeny a označením stravy, seskupené podle oddílů (předkrmy, hlavní jídla, nápoje) s filtračními tlačítky; jídla nemají vlastní stránky.',
    'Menu section' => 'Oddíl lístku',
    'Portion' => 'Porce',
    'Diet labels' => 'Označení stravy',
    'Allergens' => 'Alergeny',
    'Rooms and accommodation' => 'Pokoje a ubytování',
    'New rooms' => 'Nové pokoje',
    'A page for each room, apartment or cottage with a photo, how many guests it takes, the beds, the size, the price per night from, the amenities and a booking link.' => 'Stránka pro každý pokoj, apartmán nebo chatu s fotkou, počtem hostů, lůžky, velikostí, cenou za noc od, vybavením a odkazem na rezervaci.',
    'Guests' => 'Počet hostů',
    'Beds' => 'Lůžka',
    'Size (m²)' => 'Velikost (m²)',
    'Price per night from' => 'Cena za noc od',
    'Amenities' => 'Vybavení',
    'Booking link' => 'Odkaz na rezervaci',
    'Book now' => 'Rezervovat',
    'Property listings' => 'Nabídka nemovitostí',
    'New property listings' => 'Nová nabídka nemovitostí',
    'A page for each property for sale or to let with a photo, the price, the location, the floor and plot area, the layout, the energy rating, parameters and a map; the list filters by offer.' => 'Stránka pro každou nemovitost na prodej nebo k pronájmu s fotkou, cenou, lokalitou, užitnou plochou a plochou pozemku, dispozicí, energetickou třídou, parametry a mapou; výpis filtruje podle typu nabídky.',
    'Offer' => 'Nabídka',
    'Floor area (m²)' => 'Užitná plocha (m²)',
    'Plot area (m²)' => 'Plocha pozemku (m²)',
    'Room layout' => 'Dispozice',
    'Energy rating' => 'Energetická třída',
    'Services and trades' => 'Služby a řemesla',
    'Health, sport and learning' => 'Zdraví, sport a vzdělávání',
    'Food and stays' => 'Jídlo a ubytování',
    'Shops and production' => 'Obchody a výroba',
    'Software and agencies' => 'Software a agentury',
    'Public and non-profit' => 'Veřejná správa a neziskovky',
    'Search blueprints' => 'Hledat oborové plány',
    'Apply the blueprint %s? It creates its collections with hidden list pages and adds its facts, questions and checks. You can take it off again.' => 'Použít oborový plán %s? Vytvoří své kolekce se skrytými stránkami výpisu a přidá svá fakta, otázky a kontroly. Kdykoli ho můžete zase odebrat.',
    'No blueprint matches the search.' => 'Hledání neodpovídá žádný oborový plán.',
    'None of them fits?' => 'Žádný nesedí?',
    'Ask Claude to make a blueprint for your kind of business: it asks you what it needs to know, shows you the draft and applies it only when you agree. In the Claude app, the prompt is called draft_blueprint.' => 'Požádejte Clauda, ať pro váš obor oborový plán připraví: zeptá se, co potřebuje vědět, ukáže vám návrh a použije ho, až když souhlasíte. V aplikaci Claude se ta výzva jmenuje draft_blueprint.',
    'Request for Claude' => 'Požadavek pro Clauda',
    'Make a blueprint for our kind of business. We are … (what we do and for whom). Ask me what you need to know.' => 'Připrav oborový plán pro náš obor. Jsme … (co děláme a pro koho). Zeptej se mě, co potřebuješ vědět.',
    'From a file' => 'Ze souboru',
    'Choose this plan' => 'Vybrat tarif',
    'The site redirected the API request from https to plain http – the token would travel unencrypted, so the fetch was stopped. Use the https address of the site.' => 'Web přesměroval požadavek na API z https na nešifrované http – token by šel po síti nezašifrovaný, proto se stahování zastavilo. Použijte https adresu webu.',
    'An update left a newer .htaccess.kaleta-nova next to your customised .htaccess – carry its new rules over (since 3.3.2 they keep the code of add-ons in extensions/ away from visitors), then delete the file.' => 'Aktualizace nechala vedle vašeho upraveného .htaccess novější .htaccess.kaleta-nova – přeneste z něj nová pravidla (od 3.3.2 drží kód doplňků ve složce extensions/ mimo dosah návštěvníků) a soubor pak smažte.',
    'The update source now offers version %s instead of %s – nothing was installed. Check for updates again.' => 'Zdroj aktualizací teď nabízí verzi %s místo %s – nic se nenainstalovalo. Zkontrolujte aktualizace znovu.',
    'The update source changed whether version %s is a security release – nothing was installed. Check for updates again.' => 'Zdroj aktualizací změnil, zda je verze %s bezpečnostní – nic se nenainstalovalo. Zkontrolujte aktualizace znovu.',
    'Categories are changed by an editor or an administrator.' => 'Kategorie mění editor nebo správce.',
    'The application sent an incomplete sign-in request, so it was stopped here. Please connect it again.' => 'Aplikace poslala neúplný požadavek na přihlášení, proto se zastavil tady. Připojte ji prosím znovu.',
    'A text fact cannot begin with an address scheme other than http, https, mailto or tel (javascript:, data:…). For a link use the type web address.' => 'Textový údaj nesmí začínat schématem adresy jiným než http, https, mailto nebo tel (javascript:, data:…). Pro odkaz použijte typ webová adresa.',
    'Imported content' => 'Importovaný obsah',
    'checked again with the sanitizers of 3.3.3: %d records, %d changed' => 'znovu zkontrolován čističi verze 3.3.3: %d záznamů, %d změněno',
    'being checked again with the sanitizers of 3.3.3 by the background tasks: %d records so far, %d changed' => 'úlohy na pozadí ho znovu kontrolují čističi verze 3.3.3: zatím %d záznamů, %d změněno',
    'only risky markup was removed; the version before is in the history of each news item, page or collection item' => 'odstraněny byly jen rizikové značky; předchozí verze je v historii každé novinky, stránky nebo položky kolekce',
    'Imported content checked again with today\'s sanitizers' => 'Importovaný obsah znovu zkontrolovaný současnými čističi',
    'Wrong user name or password, or the account is temporarily locked after a series of failed attempts. Try again in 15 minutes or reset your password.' => 'Chybné jméno nebo heslo, nebo je účet po řadě chybných pokusů dočasně zamčený. Zkuste to znovu za 15 minut, nebo si heslo obnovte.',
    'Enter your current password to change the e-mail address. Nothing was saved.' => 'Ke změně e-mailu zadejte své současné heslo. Nic se neuložilo.',
    'Enter your current password to add a passkey.' => 'K přidání přihlašovacího klíče zadejte své současné heslo.',
    'The e-mail address of your account was changed' => 'E-mail vašeho účtu byl změněn',
    'the e-mail address of the account %s in the administration of %s was changed to %s.' => 'e-mail účtu %s v administraci webu %s byl změněn na %s.',
    'If you did not change it, tell the administrator of the site at once – someone else may be using your account.' => 'Pokud jste ho neměnili vy, dejte hned vědět správci webu – váš účet možná používá někdo jiný.',
    'Needed only when you change the e-mail – a password reset goes there. The old address gets a notice.' => 'Jen při změně e-mailu – chodí na něj obnova hesla. Na původní adresu přijde upozornění.',
    'Needed to add a passkey.' => 'Potřeba k přidání klíče.',
    'received during a flood' => 'přijato během náporu',
    'At least %d reports arrived within the hour before this one – perhaps sent by a script. The channel still accepts every report; read this one as carefully as any other.' => 'V hodině před tímto oznámením jich přišlo nejméně %d – možná je posílal skript. Kanál přesto přijímá každé oznámení; čtěte ho stejně pozorně jako ostatní.',
    'After you allow it, the application returns to' => 'Po povolení se aplikace vrátí na',
    '%s is not an address of Claude’s own apps. Allow access only if you started this connection yourself and know this application – if a message or someone else sent you here, choose Deny.' => '%s není adresa vlastních aplikací Claude. Přístup povolte, jen pokud jste toto připojení spustili sami a aplikaci znáte – pokud vás sem poslala zpráva nebo někdo jiný, zvolte Nepovolit.',
    'new, not verified' => 'nová, neověřená',
    'This website has not connected this application before. An application chooses its name itself, so the name is not verified – check the address above.' => 'Tento web tuto aplikaci ještě nepřipojil. Název si aplikace volí sama, proto není ověřený – zkontrolujte adresu nahoře.',
    'You can revoke the connection at any time in My account → Connected applications.' => 'Připojení můžete kdykoli zrušit na stránce Můj účet → Připojené aplikace.',
    'What may the application do?' => 'Co smí aplikace dělat?',
    'The application builds pages, writes news drafts, adds hidden collection items, proposes exceptions to the opening hours, sorts enquiries and prepares look changes – you review and publish them. Nothing on the live site changes without you.' => 'Aplikace staví stránky, píše koncepty novinek, přidává skryté položky kolekcí, navrhuje výjimky z otevírací doby, třídí poptávky a připravuje změny vzhledu – vy je zkontrolujete a vydáte. Na živém webu se bez vás nic nezmění.',
    'The application reads pages, settings, the audit and the change log. It changes nothing.' => 'Aplikace čte stránky, nastavení, audit a protokol změn. Nic nemění.',
    'Connecting apps' => 'Připojování aplikací',
    'Only allow Claude’s own apps to connect' => 'Připojit se smí jen vlastní aplikace Claude',
    'On: only Claude on the web, desktop and phone (claude.ai, claude.com) and Claude Code on your computer can register and sign in. Connections that already exist keep working. Off: other MCP applications can connect too, after a warning on the consent screen.' => 'Zapnuto: zaregistrovat a přihlásit se může jen Claude na webu, v počítači a v telefonu (claude.ai, claude.com) a Claude Code ve vašem počítači. Existující připojení fungují dál. Vypnuto: připojit se mohou i jiné aplikace MCP, s varováním na obrazovce souhlasu.',
    'A replaced refresh token of the connected application “%s” was used again, so all its tokens were revoked. If it was you, connect the application again.' => 'Již vyměněný obnovovací token připojené aplikace „%s“ byl použit znovu, proto byly zrušeny všechny její tokeny. Pokud jste to byli vy, připojte aplikaci znovu.',
    'This website lets only Claude’s own apps connect. If you need to connect another application, ask the administrator of the website.' => 'Tento web dovoluje připojit jen vlastní aplikace Claude. Pokud potřebujete připojit jinou aplikaci, obraťte se na správce webu.',
    'Hours for %s' => 'Hodiny pro službu %s',
    'Only for this service: when set, these hours replace the weekly hours above for it. All empty = the weekly hours above. Bookings of all services share the same calendar of the person, so times never overlap.' => 'Jen pro tuto službu: když jsou vyplněné, nahradí pro ni týdenní hodiny výše. Vše prázdné = platí týdenní hodiny výše. Rezervace všech služeb sdílejí jeden kalendář osoby, termíny se tedy nikdy nepřekrývají.',
    'Hours per service need an existing service (the ids are listed by booking_availability).' => 'Hodiny podle služby potřebují existující službu (čísla služeb vypíše booking_availability).',
    'News URL' => 'Adresa novinek',
    'The first part of the news addresses in every language: blog gives /blog/…. Empty = the default address. Lowercase letters, digits and hyphens; not the address of a page, a collection or the system. The old addresses redirect to the new one.' => 'První část adres novinek ve všech jazycích: blog dá /blog/…. Prázdné = výchozí adresa. Malá písmena, číslice a pomlčky; ne adresa stránky, kolekce ani systému. Stará adresa přesměruje na novou.',
    'A page or a collection already uses this URL.' => 'Tuto adresu už používá stránka nebo kolekce.',
    'Use only lowercase letters without accents, digits and single hyphens (e.g. blog), at most 40 characters.' => 'Použijte jen malá písmena bez diakritiky, číslice a jednotlivé pomlčky (např. blog), nejvýš 40 znaků.',
    'The page has been restored with the address %s, because the news now uses its old address – publish it in its settings.' => 'Stránka je obnovená s adresou %s, protože její dřívější adresu teď používají novinky – zveřejněte ji v jejím nastavení.',
    'Trailing slash in URLs' => 'Lomítko na konci adres',
    'without – /page (canonical), /page/ redirects to it' => 'bez – /stranka (kanonická), /stranka/ na ni přesměruje',
    'with – /page/ (canonical), /page redirects to it' => 's – /stranka/ (kanonická), /stranka na ni přesměruje',
    'The other form redirects with 301 and the canonical URL always uses the chosen one. Does not apply to the home page, files such as sitemap.xml, or the API.' => 'Druhý tvar přesměruje kódem 301 a kanonická adresa vždy používá zvolený. Netýká se úvodní stránky, souborů jako sitemap.xml ani API.',
    '.html – /page.html (canonical), /page and /page/ redirect to it' => '.html – /stranka.html (kanonická), /stranka a /stranka/ na ni přesměrují',
    'Form of address in German' => 'Oslovení v němčině',
    'Formal (Sie)' => 'Formální (vykání)',
    'Informal (du)' => 'Neformální (tykání)',
    'How the German texts for visitors address them (forms, search, cookie bar). The administration has its own choice in My account.' => 'Jak německé texty pro návštěvníky oslovují (formuláře, hledání, cookie lišta). Administrace má vlastní volbu v Mém účtu.',
    'How the German administration addresses you. The texts for visitors have their own setting in Settings.' => 'Jak vás německá administrace oslovuje. Texty pro návštěvníky mají vlastní nastavení v Nastavení.',
    'Write German texts for visitors with the informal “du”.' => 'Pište německé texty pro návštěvníky s neformálním „du“ (tykání).',
    'Write German texts for visitors with the formal “Sie”.' => 'Pište německé texty pro návštěvníky s formálním „Sie“ (vykání).',
    'waiting for confirmation' => 'čeká na potvrzení',
    'declined' => 'odmítnuto',
    'Accept' => 'Přijmout',
    'Decline' => 'Odmítnout',
    'Propose other times' => 'Navrhnout jiné termíny',
    'Send the proposal' => 'Odeslat návrh',
    'Personal message (optional)' => 'Osobní zpráva (nepovinná)',
    'Free times (pick 1 to 3)' => 'Volné termíny (vyberte 1 až 3)',
    'Proposed to the customer' => 'Navrženo zákazníkovi',
    'The time is held until %s.' => 'Termín je držen do %s.',
    'The hold ran out on %s – the time is free for others, but you can still answer.' => 'Držení termínu vypršelo %s – termín je volný pro ostatní, ale stále můžete odpovědět.',
    'The customer gets the confirmation with the calendar and cancel links.' => 'Zákazník dostane potvrzení s odkazy do kalendáře a ke zrušení.',
    'Decline the request? The customer will get an e-mail.' => 'Odmítnout žádost? Zákazník dostane e-mail.',
    'confirmed and waiting' => 'potvrzené a čekající',
    '%d requests are waiting for your answer.' => 'Počet žádostí čekajících na vaši odpověď: %d.',
    'Hold a request for' => 'Držet žádost',
    'Services that need confirmation: the requested time is held this long. Then it is free again and you get a reminder; the customer hears nothing until you answer.' => 'Služby s potvrzením: požadovaný termín je držen takto dlouho. Pak je zase volný a dostanete připomenutí; zákazník nedostane nic, dokud neodpovíte.',
    'Thank-you after a request' => 'Poděkování po žádosti',
    'empty = the built-in text' => 'prázdné = vestavěný text',
    'Acknowledgement e-mail' => 'E-mail s potvrzením přijetí',
    'Decline e-mail' => 'E-mail s odmítnutím',
    'The opening text of the e-mail; the details follow. Write it in your own tone and form of address; {name} is the customer\'s name.' => 'Úvodní text e-mailu, následují podrobnosti. Napište ho vlastním tónem a oslovením; {name} je jméno zákazníka.',
    'The opening text; your personal message from the request follows it.' => 'Úvodní text; po něm následuje vaše osobní zpráva.',
    'requires confirmation' => 'vyžaduje potvrzení',
    'Requires confirmation' => 'Vyžaduje potvrzení',
    'A request, not a booking: the time is held, you accept it, decline it or propose other times. The customer is told by e-mail.' => 'Žádost, ne rezervace: termín je držen, vy ji přijmete, odmítnete, nebo navrhnete jiné termíny. Zákazník se to dozví e-mailem.',
    'Only a booking waiting for confirmation can be accepted.' => 'Přijmout lze jen rezervaci čekající na potvrzení.',
    'This time has been taken meanwhile – propose other times or decline the request.' => 'Termín mezitím obsadil někdo jiný – navrhněte jiné termíny, nebo žádost odmítněte.',
    'Only a booking waiting for confirmation can get other times.' => 'Jiné termíny lze navrhnout jen rezervaci čekající na potvrzení.',
    'The customer left no e-mail address – call them, or decline the request.' => 'Zákazník nezanechal e-mail – zavolejte mu, nebo žádost odmítněte.',
    'Propose one to three times.' => 'Navrhněte jeden až tři termíny.',
    'Enter every time as YYYY-MM-DD HH:MM.' => 'Zadejte každý termín jako RRRR-MM-DD HH:MM.',
    'One of the times is not free for this person – pick them from the free times.' => 'Některý z termínů není pro tuto osobu volný – vyberte je z volných termínů.',
    'The booking is accepted and the customer got the confirmation.' => 'Rezervace je přijata a zákazník dostal potvrzení.',
    'The booking is accepted.' => 'Rezervace je přijata.',
    'The request is declined and the customer was told by e-mail.' => 'Žádost je odmítnuta a zákazník se to dozvěděl e-mailem.',
    'Only a booking waiting for confirmation can be declined.' => 'Odmítnout lze jen rezervaci čekající na potvrzení.',
    'The other times were sent to the customer.' => 'Jiné termíny byly odeslány zákazníkovi.',
    'When to load the image' => 'Kdy obrázek načíst',
    'Automatically – at once if it is the first image of the page' => 'Automaticky – hned, je-li to první obrázek stránky',
    'At once – the main image of the page' => 'Hned – hlavní obrázek stránky',
    'When scrolled into view' => 'Až při posunu k němu',
    'Preview: draft look' => 'Náhled: koncept vzhledu',
    'Neither the site e-mail (Settings → General) nor a sender address is filled in.' => 'Není vyplněný e-mail webu (Nastavení → Základní) ani adresa odesílatele.',
    'This file type cannot be uploaded. Images and these attachments are allowed: %s.' => 'Tento typ souboru nahrát nejde. Povolené jsou obrázky a přílohy: %s.',
    'The folder %s cannot be created – check the write permissions.' => 'Nelze vytvořit složku %s - zkontrolujte práva k zápisu.',
    'The backup contains a foreign table %s – the restore was stopped.' => 'Záloha obsahuje cizí tabulku %s – obnova byla zastavena.',
    '(credentials)' => '(přihlašovací údaje)',
    'the connection' => 'připojení',
    'The mailing service is not set up.' => 'Mailingová služba není nastavená.',
    'The FTP server %s does not support an encrypted connection (FTPS). Kaleta does not use unencrypted FTP – choose S3 storage.' => 'FTP server %s nepodporuje šifrované spojení (FTPS). Nešifrované FTP Kaleta nepoužívá – zvolte úložiště S3.',
    'Signing in to the FTP server %s failed.' => 'K FTP serveru %s se nepodařilo přihlásit.',
    'The folder %s does not exist on the FTP server and cannot be created.' => 'Složka %s na FTP serveru neexistuje a nejde vytvořit.',
    'The file could not be uploaded to the FTP server.' => 'Soubor se na FTP server nepodařilo nahrát.',
    'The cURL extension is missing on the server.' => 'Na serveru chybí rozšíření cURL.',
    'Fill in the storage address (e.g. s3.eu-central-1.amazonaws.com) and the bucket name.' => 'Vyplňte adresu úložiště (např. s3.eu-central-1.amazonaws.com) a název bucketu.',
    'The storage refused the upload (code %s)' => 'Úložiště nahrání odmítlo (kód %s)',
    'could not connect' => 'nepodařilo se připojit',
    'connection tokens revoked: %d' => 'zrušeny tokeny napojení: %d',
    'with a passkey' => 'přihlašovacím klíčem',
    'two-factor' => 'dvoufázově',
    'invitation sent, account: %s' => 'pozvánka, účet: %s',
    'link sent, account: %s' => 'odeslán odkaz, účet: %s',
    'password changed, connection tokens revoked, account: %s' => 'heslo změněno, tokeny napojení zrušeny, účet: %s',
    'password reset' => 'obnova hesla',
    'e-mail changed' => 'změna e-mailu',
    'password changed' => 'změna hesla',
    'two-factor sign-in turned on' => 'zapnuto dvoufázové přihlášení',
    'two-factor sign-in turned off' => 'vypnuto dvoufázové přihlášení',
    'passkey added' => 'přidán přihlašovací klíč',
    'passkey removed' => 'odebrán přihlašovací klíč',
    'app connected' => 'připojení aplikace',
    'Fill in the title.' => 'Vyplňte titulek.',
    'Only a news item in the default language can be translated, into one of the other language versions of the site.' => 'Přeložit jde jen novinka ve výchozím jazyce, a to do některé z dalších jazykových verzí webu.',
    'There is no category in the target language yet. Create one in News → Categories (the Language version field).' => 'V cílovém jazyce zatím není žádná kategorie. Založte ji v Novinky → Kategorie (pole Jazyková verze).',
    'First write at least a bit of text – the assistant works from it.' => 'Nejdřív napište aspoň kousek textu – asistent z něj vychází.',
    'The text is too short to translate.' => 'Text je na překlad příliš krátký.',
    'The text is too long for the assistant to translate.' => 'Text je na překlad asistentem příliš dlouhý.',
    'The translation did not fit into the assistant\'s answer. Try splitting the text.' => 'Překlad se nevešel do odpovědi asistenta. Zkuste text rozdělit.',
    'The assistant reports an error (%s): %s' => 'Asistent hlásí chybu (%s): %s',
    'unknown error' => 'neznámá chyba',
    'look published' => 'vzhled publikován',
    'look draft discarded' => 'koncept vzhledu zahozen',
    'Page saved. It stays hidden until it has content – add text or publish it in the builder, and it goes on the site.' => 'Stránka je uložená. Zůstane skrytá, dokud nebude mít obsah – doplňte text nebo ji publikujte v builderu a objeví se na webu.',
    'Hidden until it has content: it goes on the site, and into the navigation, when you publish it in the builder or add text.' => 'Skrytá, dokud nemá obsah: na web i do navigace se dostane, až ji publikujete v builderu nebo doplníte text.',
    'A page from a template or the builder stays hidden until you publish it there.' => 'Stránka ze šablony nebo z builderu zůstane skrytá, dokud ji tam nepublikujete.',
    'hidden until published' => 'skrytá do publikování',
    'This site is not on HTTPS, so the Claude app cannot connect to it yet. Switch the site to HTTPS – most hosting does it for free – and open the administration at its https:// address.' => 'Web neběží na HTTPS, takže se k němu aplikace Claude zatím nepřipojí. Přepněte web na HTTPS – většina hostingů to udělá zdarma – a otevřete administraci na adrese https://.',
    'Build and edit the site by talking to Claude. Connect it once – it takes a minute – and Claude works on the site in your name and with your permissions.' => 'Stavějte a upravujte web rozhovorem s Claudem. Připojte ho jednou – zabere to minutu – a Claude pak pracuje na webu vaším jménem a s vašimi oprávněními.',
    'Paste the address above as the connector URL and add it.' => 'Vložte adresu výše jako URL konektoru a přidejte ho.',
    'Claude sends you here to sign in. Choose what it may do – then ask it anything about your site.' => 'Claude vás pošle sem k přihlášení. Zvolte, co smí dělat – a pak se ho zeptejte na cokoli o svém webu.',
    'Claude Code or another tool without sign-in? Create a personal token in' => 'Claude Code nebo jiný nástroj bez přihlášení? Osobní token vytvoříte na stránce',
    'Saved as request #%d – Claude picks it up once it is connected to the site.' => 'Uloženo jako požadavek č. %d – Claude si ho vezme, jakmile bude k webu připojený.',
    'The request is saved – Claude picks it up once it is connected to the site; you will read its notes here.' => 'Požadavek je uložený – Claude si ho vezme, jakmile bude k webu připojený; jeho poznámky si přečtete tady.',
    'Connected – Claude last worked on the site %s.' => 'Připojeno – Claude naposledy pracoval na webu %s.',
    'Not connected yet – no Claude connection has called the site.' => 'Zatím nepřipojeno – web zatím nevolalo žádné připojení Clauda.',
    'In a subfolder, the Claude app finds the sign-in on its own; for a tool that does not, use a personal token.' => 'V podsložce si aplikace Claude přihlášení najde sama; pro nástroj, který to neumí, použijte osobní token.',
    'Set up Bookings' => 'Nastavení rezervací',
    'Add a person' => 'Přidat člověka',
    'Who takes the bookings – or one entry for the whole business – with their weekly hours.' => 'Kdo rezervace přijímá – nebo jeden záznam za celou firmu – s týdenními hodinami.',
    'What visitors book and how long it takes – tick the person who offers it.' => 'Co si návštěvníci rezervují a jak dlouho to trvá – zaškrtněte osobu, která to nabízí.',
    'Create a Book page' => 'Vytvořit stránku Rezervace',
    'A page with the Booking element, where visitors pick a time.' => 'Stránka s prvkem Rezervace, kde si návštěvníci vyberou termín.',
    'A page with the Booking element opens in the builder. It stays hidden until you publish it.' => 'Stránka s prvkem Rezervace se otevře v builderu. Zůstane skrytá, dokud ji nepublikujete.',
    'Follow the three steps above: a person, a service, a page. Visitors then pick a service, a person, a day and a free time.' => 'Projděte tři kroky výše: osoba, služba, stránka. Návštěvníci si pak vyberou službu, osobu, den a volný čas.',
    'An administrator adds the people, the services and the booking page. Bookings then appear here.' => 'Správce přidá osoby, služby a stránku s rezervací. Rezervace se pak objeví tady.',
    'No free time in the next 14 days: %s has no weekly hours and the site has no opening hours, so no time is offered. Give them weekly hours, or fill in the opening hours in Business details.' => 'V příštích 14 dnech není volný žádný čas: %s nemá týdenní hodiny a web nemá otevírací dobu, takže se nenabízí žádný termín. Doplňte týdenní hodiny, nebo otevírací dobu v Údajích o firmě.',
    'No free time in the next 14 days – visitors see an empty calendar. Check the weekly hours and days off of the people, and the earliest booking and how far ahead visitors may book.' => 'V příštích 14 dnech není volný žádný čas – návštěvníci uvidí prázdný kalendář. Zkontrolujte týdenní hodiny a volna osob, nejdřívější rezervaci a jak daleko dopředu lze rezervovat.',
    'Add a person first' => 'Nejdřív přidejte člověka',
    'A service needs someone who offers it. Add the person (or one entry for the whole business) with their weekly hours, then the service.' => 'Službu musí někdo nabízet. Přidejte osobu (nebo jeden záznam za celou firmu) s týdenními hodinami a pak službu.',
    'Nobody can offer it yet –' => 'Zatím ji nemůže nikdo nabízet –',
    'add a person first' => 'nejdřív přidejte člověka',
    'Nobody takes bookings yet.' => 'Rezervace zatím nikdo nepřijímá.',
    'Add the people (or just one entry for the whole business) with their weekly hours. Then add the services and tick who offers each.' => 'Přidejte osoby (nebo jen jeden záznam za celou firmu) s týdenními hodinami. Pak přidejte služby a u každé zaškrtněte, kdo ji nabízí.',
    'No services yet – save the person, then add a service and tick them in it.' => 'Zatím žádné služby – osobu uložte, pak přidejte službu a v ní ji zaškrtněte.',
    'Set up Bookings →' => 'Nastavit rezervace →',
    'booking page created' => 'vytvoření stránky s rezervací',
    'Link (primary colour) on surface' => 'Odkaz (hlavní barva) na ploše',
    'Primary colour on its soft shade (current menu item, secondary button)' => 'Hlavní barva na svém jemném odstínu (aktuální položka menu, doplňkové tlačítko)',
    'Focus ring (secondary colour) on background' => 'Rámeček zaměření (doplňková barva) na pozadí',
    'Focus ring (secondary colour) on surface' => 'Rámeček zaměření (doplňková barva) na ploše',
    '%s has a contrast of %s : 1 – a focus ring needs at least 3 : 1.' => '%s má kontrast %s : 1 – rámeček zaměření potřebuje aspoň 3 : 1.',
    'Text should have a contrast of at least 4.5 : 1 (WCAG AA), a focus ring at least 3 : 1. Pairs marked in red will be hard to read for some visitors.' => 'Text by měl mít kontrast aspoň 4,5 : 1 (WCAG AA), rámeček zaměření aspoň 3 : 1. Červeně označené dvojice budou pro část návštěvníků špatně čitelné.',
    'Automatic primary and secondary colours keep the hue of the light ones, made lighter until links, buttons and focus rings are readable on the dark background. Pick a colour to set your own.' => 'Automatická hlavní a doplňková barva mají odstín světlých barev, jen zesvětlený tak, aby odkazy, tlačítka a rámečky zaměření byly na tmavém pozadí čitelné. Výběrem barvy nastavíte vlastní.',
    'Readability in dark mode' => 'Čitelnost v tmavém režimu',
    'Dark mode: some colour pairs are hard to read – see the readability list in the Dark mode tab.' => 'Tmavý režim: některé dvojice barev jsou špatně čitelné – podívejte se na seznam čitelnosti v záložce „Tmavý režim“.',
    'Menus go to the draft look with links to the new addresses: the navigation on the site changes only when you publish the look.' => 'Menu přijdou do konceptu vzhledu s odkazy na nové adresy: navigace na webu se změní, až vzhled publikujete.',
    'Menu “%s” (%s items): %s' => 'Menu „%s“ (položek: %s): %s',
    'left out – this site has a main and a footer menu' => 'vynechá se – tento web má hlavní menu a menu v patičce',
    '%s pages and posts were laid out with %s: the layout is not in the export, only the text in the post content comes over.' => 'Rozvržení %s stránek a příspěvků vzniklo v %s: v exportu není, přenese se jen text obsahu příspěvku.',
    'User accounts and passwords – no account is created. A news item belongs to the user here with the same e-mail as its WordPress author, otherwise to you. Comments are not transferred.' => 'Uživatelské účty a hesla – žádný účet nevznikne. Novinka bude patřit uživateli tohoto webu se stejným e-mailem, jaký má její autor ve WordPressu, jinak vám. Komentáře se nepřenášejí.',
    'Widgets, appearance and plugin settings.' => 'Widgety, vzhled a nastavení doplňků.',
    'navigation menus (%s) into the draft look' => 'navigační menu (%s) do konceptu vzhledu',
    'everything hidden – news as drafts, pages hidden; publish them when they are ready' => 'vše skryté – novinky jako koncepty, stránky skryté; zveřejníte je, až budou hotové',
    'Public on WordPress, imported hidden' => 'Na WordPressu veřejné, importováno jako skryté',
    'this site has a main and a footer menu, and other menus took them' => 'tento web má hlavní menu a menu v patičce a ta zabrala jiná menu',
    'none of its links lead to anything that was imported' => 'žádný jeho odkaz nevede na nic, co se importovalo',
    'the draft look already holds a different menu for this place – nothing was overwritten' => 'koncept vzhledu už pro toto místo obsahuje jiné menu – nic se nepřepsalo',
    'it was imported by an earlier run' => 'importoval ho už dřívější běh',
    'Menu “%s” is in the draft look – %s, %s items. Publish the look to show it on the site.' => 'Menu „%s“ je v konceptu vzhledu – %s, položek: %s. Na webu se ukáže, až vzhled publikujete.',
    'Menu “%s” was not imported: %s.' => 'Menu „%s“ se neimportovalo: %s.',
    'Open the menu' => 'Otevřít menu',
    '%s: the news items belong to you' => '%s: novinky patří vám',
    '%s: the news items belong to %s, who has the same e-mail' => '%s: novinky patří uživateli %s, který má stejný e-mail',
    '%s: the news items belong to %s' => '%s: novinky patří uživateli %s',
    'Old addresses that were not redirected (%s)' => 'Staré adresy, které se nepřesměrovaly (%s)',
    'the address is already in use on this site' => 'adresu už tento web používá',
    'the address already redirects elsewhere' => 'adresa už přesměrovává jinam',
    'The file is larger than the download limit.' => 'Soubor je větší, než kolik jde stáhnout.',
    'colours' => 'barvy',
    'fonts' => 'písma',
    'sizes' => 'velikosti',
    'design system' => 'design systém',
    'classes' => 'třídy',
    'Unpublished changes:' => 'Nepublikované změny:',
    'Visitors still see the published look until you publish.' => 'Návštěvníci vidí publikovaný vzhled, dokud změny nepublikujete.',
    'Review' => 'Prohlédnout',
    'The menu is published – visitors see it now.' => 'Menu je publikované – návštěvníci ho už vidí.',
    'Save and publish menu' => 'Uložit a publikovat menu',
    'Save to the draft look' => 'Uložit do konceptu vzhledu',
    'Publishing the menu leaves other unpublished look changes (colours, fonts, classes) waiting in the draft.' => 'Publikování menu nechá ostatní nepublikované změny vzhledu (barvy, písma, třídy) čekat v konceptu.',
    'menu published' => 'menu publikováno',
    'Enter the old address – a path on this site, e.g. /old-page.' => 'Zadejte starou adresu – cestu na tomto webu, např. /stara-stranka.',
    'An address may have at most 255 characters.' => 'Adresa může mít nejvýš 255 znaků.',
    'The old address must be a path on this site, e.g. /old-page (without ? or #).' => 'Stará adresa musí být cesta na tomto webu, např. /stara-stranka (bez ? a #).',
    'Use at most 3 wildcards (*) in the old address, never two in a row.' => 'Ve staré adrese použijte nejvýš 3 hvězdičky (*) a nikdy dvě za sebou.',
    'A pattern needs a fixed part besides the wildcards, e.g. /blog/*.' => 'Vzor potřebuje kromě hvězdiček i pevnou část, např. /blog/*.',
    'The target must be a path on this site or a full https://… address; a wildcard (*) only after the domain.' => 'Cíl musí být cesta na tomto webu nebo celá adresa https://…; hvězdička (*) jen za doménou.',
    'The target has more wildcards (*) than the old address.' => 'Cíl má víc hvězdiček (*) než stará adresa.',
    'The old address and the target are the same.' => 'Stará adresa a cíl jsou stejné.',
    'It would make a loop – the redirects would lead back to this address.' => 'Vznikla by smyčka – přesměrování by vedla zpět na tuto adresu.',
    'The site already has the most pattern rules it can use (500).' => 'Web už má nejvyšší možný počet pravidel se vzorem (500).',
    'Only 301 (permanent), 302 (temporary) and 410 (gone for good).' => 'Jen 301 (natrvalo), 302 (dočasně) a 410 (zrušeno navždy).',
    'Enter the target – a path on this site or a full https://… address.' => 'Zadejte cíl – cestu na tomto webu nebo celou adresu https://….',
    'The same old address is in an earlier row – the first one counts.' => 'Stejná stará adresa je už v dřívějším řádku – platí ten první.',
    'The rule is switched off in the file.' => 'Pravidlo je v souboru vypnuté.',
    'A regular expression – add this one by hand as a pattern with * (e.g. /blog/* → /news/*).' => 'Regulární výraz – přidejte ho ručně jako vzor s * (např. /blog/* → /novinky/*).',
    'Choose a CSV file or paste its rows (old address, target, code).' => 'Vyberte soubor CSV nebo vložte jeho řádky (stará adresa, cíl, kód).',
    'The file has no redirects – one per row: old address, target, code (301 or 302).' => 'Soubor neobsahuje žádná přesměrování – jedno na řádek: stará adresa, cíl, kód (301 nebo 302).',
    'Import redirects' => 'Import přesměrování',
    'Redirects imported: %d added, %d changed, %d refused.' => 'Přesměrování naimportována: %d přidáno, %d změněno, %d odmítnuto.',
    'An asterisk stands for the rest of the address: /blog/* → /news/* sends /blog/2019/post to /news/2019/post. An exact redirect always wins over a pattern, and the longer fixed beginning wins among patterns.' => 'Hvězdička zastupuje zbytek adresy: /blog/* → /novinky/* pošle /blog/2019/clanek na /novinky/2019/clanek. Přesné přesměrování má vždy přednost před vzorem a mezi vzory vyhrává delší pevný začátek.',
    'Leave it empty for “gone (410)”.' => 'Pro „zrušeno (410)“ nechte prázdné.',
    'gone (410) – removed for good, search engines drop it' => 'zrušeno (410) – odstraněno navždy, vyhledávače adresu vyřadí',
    'gone (410)' => 'zrušeno (410)',
    'Import from a CSV file' => 'Import ze souboru CSV',
    'One redirect per row: old address, target and code (301 or 302, empty = 301; 410 with an empty target = gone for good). A header row is optional; the CSV export of the WordPress Redirection plugin works as it is. You see what will be added, changed or refused before anything is saved.' => 'Jedno přesměrování na řádek: stará adresa, cíl a kód (301 nebo 302, prázdný = 301; 410 s prázdným cílem = zrušeno navždy). Řádek se záhlavím je nepovinný; export CSV z pluginu Redirection pro WordPress funguje tak, jak je. Než se cokoli uloží, uvidíte, co se přidá, změní nebo odmítne.',
    'CSV file' => 'Soubor CSV',
    'Or paste the rows' => 'Nebo vložte řádky',
    'Show what will change' => 'Ukázat, co se změní',
    'will be added' => 'přidá se',
    'will change' => 'změní se',
    'refused' => 'odmítnuto',
    '%d rows: %d will be added, %d will change, %d stay as they are, %d are refused.' => 'Řádků: %d – přidá se %d, změní se %d, beze změny zůstane %d, odmítnuto je %d.',
    'Row' => 'Řádek',
    'Save %d redirects' => 'Uložit přesměrování (%d)',
    'the news list' => 'výpis novinek',
    'items of %s' => 'položky kolekce %s',
    'pages under %s' => 'stránky pod %s',
    'also: %s' => 'také: %s',
    'Also on' => 'Také na',
    'Besides the pages above, the variant can take a kind of content. A page ticked above always gets its variant; otherwise the first variant (by name) whose choice fits wins.' => 'Kromě stránek výše může varianta platit pro druh obsahu. Stránka zaškrtnutá výše dostane svou variantu vždy; jinak vyhraje první varianta (podle názvu), jejíž výběr sedí.',
    'the news list, categories, tags and search' => 'výpis novinek, kategorie, štítky a hledání',
    'Pages under' => 'Stránky pod',
    'The export file changed after the preview, so the import stopped. Start it again with the file you want to import.' => 'Soubor s exportem se po náhledu změnil, proto se import zastavil. Spusťte ho znovu se souborem, který chcete importovat.',
    'A cron job that already calls the older address …/ulohy?token= keeps working – there is no need to change it.' => 'Cron, který už volá starší adresu …/ulohy?token=, funguje dál – není potřeba ho měnit.',
    'English system addresses' => 'Anglické systémové adresy',
    'The site itself uses %s, so the system keeps writing the older address %s there – both keep working. Rename the page if you want the English address.' => 'Web sám používá %s, proto tam systém dál píše starší adresu %s – fungují obě. Pokud chcete anglickou adresu, stránku přejmenujte.',
    'Undo journal of Claude sessions: older than 30 days removed' => 'Deník relací Clauda pro vracení: záznamy starší 30 dnů odstraněny',
    'Online booking: reminders before the appointment' => 'Online rezervace: připomínky před termínem',
    'Imports not finished' => 'Nedokončené importy',
    '%s rows' => 'Řádků: %s',
    'A CSV file (from Excel or another system – comma, semicolon or tab) or a JSON list, up to %s rows. The first row names the columns; one row is one item. You pair the columns with the fields and see what will be added, changed or refused before anything is saved.' => 'Soubor CSV (z Excelu nebo jiného systému – čárka, středník nebo tabulátor) nebo seznam JSON, nejvýš %s řádků. První řádek pojmenuje sloupce, každý další řádek je jedna položka. Sloupce přiřadíte k polím a ještě před uložením uvidíte, co se přidá, změní nebo odmítne.',
    'Columns named like the fields are paired by themselves: %s.' => 'Sloupce pojmenované jako pole se přiřadí samy: %s.',
    'An image or file column with web addresses (https://…) is downloaded into Media after the items are saved.' => 'Sloupec s obrázky nebo soubory jako webovými adresami (https://…) se po uložení položek stáhne do Médií.',
    'CSV or JSON file' => 'Soubor CSV nebo JSON',
    'Another file' => 'Jiný soubor',
    '%s: %d rows – %d will be added, %d will change, %d stay as they are, %d are refused.' => '%s: %d řádků – %d se přidá, %d se změní, %d zůstane beze změny, %d se odmítne.',
    'Column in the file' => 'Sloupec v souboru',
    'Example' => 'Ukázka',
    'Goes to' => 'Uloží se do',
    '– not imported –' => '– neimportovat –',
    'Default language' => 'Výchozí jazyk',
    'For rows without a language column.' => 'Pro řádky bez sloupce s jazykem.',
    'Show new items on the site at once' => 'Nové položky hned zobrazit na webu',
    'Without it new items arrive hidden, so you can check them first. Items that change keep their visibility.' => 'Bez toho přijdou nové položky skryté, abyste je mohli nejdřív zkontrolovat. Měněné položky si viditelnost ponechají.',
    'An item is found by its address (slug), or by the address made from its name – importing the same file again updates the items instead of adding them twice. An empty cell leaves the value of an item as it is.' => 'Položka se najde podle adresy (slug), nebo podle adresy vytvořené z názvu – nový import stejného souboru položky aktualizuje, nepřidá je podruhé. Prázdná buňka hodnotu položky nemění.',
    'Update preview' => 'Obnovit náhled',
    'Save %d items' => 'Uložit položky (%d)',
    'Invalid value, left empty: %s' => 'Neplatná hodnota, zůstane prázdné: %s',
    'The first 100 rows are shown, then the refused ones and those with an invalid value.' => 'Zobrazeno je prvních 100 řádků, pak odmítnuté a ty s neplatnou hodnotou.',
    'File: %s' => 'Soubor: %s',
    'Saving: %s of %s rows. Keep this page open, it continues by itself.' => 'Ukládání: %s z %s řádků. Nechte stránku otevřenou, pokračuje sama.',
    'Downloading images: %s of %s. Keep this page open, it continues by itself.' => 'Stahování obrázků: %s z %s. Nechte stránku otevřenou, pokračuje sama.',
    'The import is finished.' => 'Import je hotový.',
    'The import is finished. New items are hidden until you check and show them.' => 'Import je hotový. Nové položky jsou skryté, dokud je nezkontrolujete a nezobrazíte.',
    'No change' => 'Beze změny',
    'Refused' => 'Odmítnuto',
    '%d items had a field with an invalid value – it was left empty. Check them in the list.' => 'U %d položek mělo pole neplatnou hodnotu – zůstalo prázdné. Zkontrolujte je ve výpisu.',
    'Refused rows: %d' => 'Odmítnuté řádky: %d',
    'Row %d' => 'Řádek %d',
    '%d images could not be downloaded' => 'Nepodařilo se stáhnout obrázků: %d',
    'Show items' => 'Zobrazit položky',
    'Import another file' => 'Importovat další soubor',
    'Import from CSV or JSON' => 'Import z CSV nebo JSON',
    'Import items: %s' => 'Import položek: %s',
    'The file is larger than %d MB.' => 'Soubor je větší než %d MB.',
    'The robots.txt of the old site asks robots not to read this page, so only the address was checked.' => 'Soubor robots.txt starého webu žádá roboty, aby tuto stránku nečetli, proto se zkontrolovala jen adresa.',
    'Address (slug)' => 'Adresa (slug)',
    'Title for search engines' => 'Titulek pro vyhledávače',
    'Description for search engines' => 'Popis pro vyhledávače',
    'Image for sharing' => 'Obrázek pro sdílení',
    'The file is empty.' => 'Soubor je prázdný.',
    'The file has no rows – the first row names the columns, every further row is one item.' => 'Soubor nemá žádné řádky – první řádek pojmenuje sloupce, každý další je jedna položka.',
    'The file has more than 5,000 rows – split it into smaller files.' => 'Soubor má víc než 5 000 řádků – rozdělte ho na menší soubory.',
    'The JSON file must be a list of items: [{"name":"…","price":"…"}, …].' => 'Soubor JSON musí být seznam položek: [{"name":"…","price":"…"}, …].',
    'The file could not be read.' => 'Soubor se nepodařilo přečíst.',
    'The item is in the trash – restore it first.' => 'Položka je v koši – nejdřív ji obnovte.',
    'The same item is in this batch twice – only the first one is saved.' => 'Stejná položka je v dávce dvakrát – uloží se jen první.',
    'Invalid item address.' => 'Neplatná adresa položky.',
    'The item could not be saved.' => 'Položku se nepodařilo uložit.',
    'Only https addresses are downloaded.' => 'Stahují se jen adresy https.',
    'This server cannot download files from other sites.' => 'Tento server neumí stahovat soubory z jiných webů.',
    'SVG files are not downloaded – upload them with upload_file.' => 'Soubory SVG se nestahují – nahrajte je přes Média.',
    'The robots.txt of the old site asks robots not to read this page.' => 'Soubor robots.txt starého webu žádá roboty, aby tuto stránku nečetli.',
    'Categories: %s' => 'Kategorie: %s',
    'Category page: %s' => 'Stránka kategorie: %s',
    'Category description' => 'Popis kategorie',
    'Number of items' => 'Počet položek',
    'Parent category' => 'Nadřazená kategorie',
    'Parent category page' => 'Stránka nadřazené kategorie',
    'Add category' => 'Přidat kategorii',
    'Category page template' => 'Šablona stránky kategorie',
    'Category page template (%s)' => 'Šablona stránky kategorie (%s)',
    'No categories yet.' => 'Zatím žádné kategorie.',
    'Categories sort the items into groups with their own pages – /%s/category and /%s/category/subcategory – with a description, breadcrumbs and a list of the items. Tick the categories on each item.' => 'Kategorie třídí položky do skupin s vlastními stránkami – /%s/kategorie a /%s/kategorie/podkategorie – s popisem, drobečkovou navigací a výpisem položek. Kategorie zaškrtnete u každé položky.',
    'Two levels: a category and its subcategories. A category page lists the items of the category and of its subcategories; an address can never be both a category and an item of this collection.' => 'Dvě úrovně: kategorie a její podkategorie. Stránka kategorie vypíše položky kategorie i jejích podkategorií; jedna adresa nikdy nepatří zároveň kategorii a položce této kolekce.',
    'Edit the %s version' => 'Upravit verzi %s',
    'Add the %s version' => 'Přidat verzi %s',
    'Add subcategory' => 'Přidat podkategorii',
    'Delete the category in every language? Its items stay in the collection; its page disappears.' => 'Smazat kategorii ve všech jazycích? Její položky v kolekci zůstanou, zmizí jen její stránka.',
    'From the name if left empty. It cannot be the address of an item of this collection.' => 'Prázdné = z názvu. Nesmí to být adresa položky této kolekce.',
    'Shown on the category page ({{popis}} in the category template) – an introduction for visitors and search engines.' => 'Zobrazí se na stránce kategorie ({{popis}} v šabloně kategorie) – úvod pro návštěvníky i vyhledávače.',
    'empty = the category name' => 'prázdné = název kategorie',
    'One or two sentences for search results (up to 160 characters). Empty = the beginning of the description.' => 'Jedna dvě věty do výsledků hledání (do 160 znaků). Prázdné = začátek popisu.',
    'Shared by every language' => 'Společné pro všechny jazyky',
    '– none (a top-level category) –' => '– žádná (kategorie nejvyšší úrovně) –',
    'It has subcategories, so it stays a top-level category.' => 'Má podkategorie, takže zůstává kategorií nejvyšší úrovně.',
    'Shown on the category page and its card ({{obrazek}}) and when the page is shared.' => 'Zobrazí se na stránce kategorie, na její kartě ({{obrazek}}) a při sdílení stránky.',
    'A hidden category has no page and is in no list; its items stay where they are.' => 'Skrytá kategorie nemá stránku a není v žádném výpisu; její položky zůstávají, kde jsou.',
    'Save category' => 'Uložit kategorii',
    'Remove the %s version of the category? The other languages keep it.' => 'Odebrat verzi %s kategorie? Ostatní jazyky ji ponechají.',
    'Remove this language version' => 'Odebrat tuto jazykovou verzi',
    'The item is listed on the pages of the ticked categories (a top-level category page also lists the items of its subcategories).' => 'Položka se vypíše na stránkách zaškrtnutých kategorií (stránka kategorie nejvyšší úrovně vypíše i položky svých podkategorií).',
    'Manage categories' => 'Spravovat kategorie',
    'Attachment size limit per file in MB (1–25). This server accepts files up to %s, so a higher limit applies only up to that.' => 'Limit velikosti jedné přílohy v MB (1–25). Tento server přijme soubory nejvýš do %s, vyšší limit proto platí jen do této hranice.',
    'Attachment size limit per file in MB (1–25). This server accepts files up to %s.' => 'Limit velikosti jedné přílohy v MB (1–25). Tento server přijme soubory až do %s.',
    'Attachment size limit per file in MB (1–25)' => 'Limit velikosti jedné přílohy v MB (1–25)',
    'The address “%s” belongs to a category of this collection – give the item another address.' => 'Adresa „%s“ patří kategorii této kolekce – dejte položce jinou adresu.',
    'The category does not exist in this collection.' => 'Kategorie v této kolekci neexistuje.',
    'The category needs a name.' => 'Kategorie musí mít název.',
    'The address “%s” cannot be used for a category.' => 'Adresu „%s“ nejde použít pro kategorii.',
    'The address “%s” is already used by another category of this collection.' => 'Adresu „%s“ už používá jiná kategorie této kolekce.',
    'The address “%s” is already used by an item of this collection – a category page and an item page cannot share it.' => 'Adresu „%s“ už používá položka této kolekce – stránka kategorie a stránka položky ji nemohou sdílet.',
    'A subcategory belongs under a top-level category of the same collection (two levels).' => 'Podkategorie patří pod kategorii nejvyšší úrovně ve stejné kolekci (dvě úrovně).',
    'The category has subcategories, so it cannot become a subcategory itself (two levels).' => 'Kategorie má podkategorie, takže sama podkategorií být nemůže (dvě úrovně).',
    'The image must be a file from Media or an https address.' => 'Obrázek musí být soubor z Médií nebo adresa https.',
    'The category has subcategories – delete them or move them under another category first.' => 'Kategorie má podkategorie – nejdřív je smažte nebo přesuňte pod jinou kategorii.',
    'There is nothing in this category yet.' => 'V této kategorii zatím nic není.',
    'Item name' => 'Název položky',
    'Previous and next item' => 'Předchozí a další položka',
    'The category was saved.' => 'Kategorie byla uložena.',
    'The category was deleted; its items stay in the collection.' => 'Kategorie byla smazána; její položky v kolekci zůstaly.',
    'Previous / next item' => 'Předchozí / další položka',
    'Links to the previous and the next item on an item page (references, products, projects) – in the collection order or by date, within the item’s category.' => 'Odkazy na předchozí a další položku na stránce položky (reference, produkty, projekty) – v pořadí kolekce nebo podle data, v rámci kategorie položky.',
    'items' => 'položky',
    'List' => 'Vypsat',
    'Category (its address; * = the category page shown, on an item page the item’s category). Categories: the subcategories of it, empty = the top-level ones' => 'Kategorie (její adresa; * = zobrazená stránka kategorie, na stránce položky kategorie položky). U kategorií: její podkategorie, prázdné = kategorie nejvyšší úrovně',
    'as in the administration (order, then name)' => 'jako v administraci (pořadí, pak název)',
    'by date (previous = older)' => 'podle data (předchozí = starší)',
    'Only within the item’s category (when it has one)' => 'Jen v rámci kategorie položky (když nějakou má)',
    'Label of the previous item' => 'Popisek předchozí položky',
    'Label of the next item' => 'Popisek další položky',
    'Show the item names' => 'Zobrazit názvy položek',
    'Show thumbnails' => 'Zobrazit náhledy',
    'Thumbnail field (key of an image field; empty = the first image field)' => 'Pole náhledu (klíč obrázkového pole; prázdné = první obrázkové pole)',
    'Collection categories' => 'Kategorie kolekcí',
    'version %s needs PHP %s or newer, the server runs PHP %s – ask the hosting for a newer PHP to update' => 'verze %s potřebuje PHP %s nebo novější, na serveru běží PHP %s – pro aktualizaci požádejte hosting o novější PHP',
    'Version %s needs PHP %s or newer; the server runs PHP %s. Ask your hosting to switch the site to a newer PHP, then the update will be offered here.' => 'Verze %s potřebuje PHP %s nebo novější, na serveru běží PHP %s. Požádejte hosting o přepnutí webu na novější PHP, pak se vám tu aktualizace nabídne.',
    'The robots.txt of the old site is very long: only its first %s KB and %s rules for Kaleta were read.' => 'Soubor robots.txt starého webu je velmi dlouhý: přečetlo se jen jeho prvních %s KB a %s pravidel pro Kaletu.',
    '%s sitemaps on other hosts were not read (%s): only the old site’s own sitemaps are followed.' => '%s map webu na jiných hostitelích se nečetlo (%s): čtou se jen mapy na adrese starého webu.',
    '%s more sitemaps were not read: at most %s are read.' => 'Dalších %s map webu se nečetlo: čte se jich nejvýš %s.',
    'Finished imports' => 'Dokončené importy',
    'The result of an import stays here until you remove it, at most %s days; the items stay either way. The uploaded rows are deleted as soon as they are saved.' => 'Výsledek importu tu zůstane, dokud ho neodeberete, nejvýš %s dní; položky zůstanou tak jako tak. Nahrané řádky se smažou hned po uložení.',
    'Remove this import' => 'Odebrat tento import',
    'The address %s is used by the system, so the page got %s.' => 'Adresu %s používá systém, proto stránka dostala %s.',
    'The page has been restored with the address %s, because its old address %s is used by the system – publish it in its settings.' => 'Stránka je obnovená s adresou %s, protože její dřívější adresu %s používá systém – zveřejněte ji v jejím nastavení.',
    'Changed so the site keeps working:' => 'Změněno, aby web dál fungoval:',
    'Collection category %s: its parent is not a top-level category of the same collection, so it became a top-level category.' => 'Kategorie kolekce %s: její nadřazená kategorie není kategorie první úrovně ze stejné kolekce, proto se z ní stala kategorie první úrovně.',
    'Collection category “%s”: the address %s cannot be used (an item of the collection has it, or it is reserved), so the category got %s.' => 'Kategorie kolekce „%s“: adresu %s nelze použít (má ji položka kolekce, nebo je vyhrazená), proto kategorie dostala %s.',
    'Its address %s is taken by another item or a category now, so the item keeps %s.' => 'Její adresu %s teď má jiná položka nebo kategorie, proto položce zůstává %s.',
    'The item was restored as hidden with the address %s, because a category of the collection has its old address.' => 'Položka je obnovená jako skrytá s adresou %s, protože její dřívější adresu má kategorie kolekce.',
    'The address “%s” belongs to a category of this collection, so the item has “%s”.' => 'Adresa „%s“ patří kategorii této kolekce, proto má položka „%s“.',
    'Items with another address: %d' => 'Položky s jinou adresou: %d',
    'A cron job that calls /tasks reaches that page and runs nothing – point it at /ulohy.' => 'Cron, který volá /tasks, se dostane na tu stránku a nic nespustí – nasměrujte ho na /ulohy.',
    'PHP JIT' => 'JIT v PHP',
    'opcache.jit = %s on PHP %s can crash pages (a bug in PHP 8.3) – ask the hosting for opcache.jit = tracing (the default) or PHP 8.4' => 'opcache.jit = %s na PHP %s může shazovat stránky (chyba PHP 8.3) – požádejte hosting o opcache.jit = tracing (výchozí) nebo PHP 8.4',
    'https://… or /page' => 'https://… nebo /stranka',
    'The update source of the stable channel does not offer a stable-channel release (aktualizace-stable.json), so nothing is offered. Switch to the Latest channel or check the custom update source.' => 'Zdroj aktualizací stabilního kanálu nenabízí vydání stabilního kanálu (aktualizace-stable.json), proto se nic nenabízí. Přepněte na kanál Nejnovější, nebo zkontrolujte vlastní zdroj aktualizací.',
    'Latest channel' => 'kanál Nejnovější',
    'Stable channel' => 'kanál Stabilní',
    'custom update source' => 'vlastní zdroj aktualizací',
    'This site runs version %s, which is newer than the stable channel (%s). Nothing is offered until the stable channel moves past this version – a site never goes back to an older one. Until then, security fixes reach this site only on the Latest channel.' => 'Web běží na verzi %s, která je novější než stabilní kanál (%s). Dokud stabilní kanál tuto verzi nepředežene, nic se nenabízí – web se nikdy nevrací ke starší verzi. Do té doby k němu bezpečnostní opravy dorazí jen na kanálu Nejnovější.',
    'You have the newest version of the stable channel.' => 'Máte nejnovější verzi stabilního kanálu.',
    'Update channel' => 'Kanál aktualizací',
    'Latest' => 'Nejnovější',
    'A new minor version every week, with new features and fixes. Recommended for most sites.' => 'Každý týden nová verze s novinkami a opravami. Doporučeno pro většinu webů.',
    'Stable' => 'Stabilní',
    'Security fixes only, and a new minor version about once a month, after it has run on Latest. For sites that should change as little as possible.' => 'Jen bezpečnostní opravy a zhruba jednou za měsíc nová verze s novinkami, až se osvědčí na kanálu Nejnovější. Pro weby, které se mají měnit co nejméně.',
    'The custom update source below is not a file named aktualizace.json, so it has no stable twin: the site follows it whatever channel you choose.' => 'Vlastní zdroj aktualizací níže není soubor aktualizace.json, a nemá proto stabilní protějšek: web se jím řídí, ať zvolíte jakýkoli kanál.',
    'A site on Stable never goes back to an older version: after switching from Latest it waits until the stable channel passes the version it runs.' => 'Web na kanálu Stabilní se nikdy nevrací ke starší verzi: po přepnutí z kanálu Nejnovější počká, až stabilní kanál předežene verzi, na které běží.',
    'Stable – this site runs %s, newer than the stable channel (%s): nothing is offered until the stable channel passes it, so security fixes reach it only on Latest (Settings → Backups and updates)' => 'Stabilní – web běží na %s, novější než stabilní kanál (%s): dokud ho stabilní kanál nepředežene, nic se nenabízí, bezpečnostní opravy tak dorazí jen na kanálu Nejnovější (Nastavení → Zálohy a aktualizace)',
    'Stable – security fixes only, a new minor version about once a month' => 'Stabilní – jen bezpečnostní opravy, nová verze zhruba jednou za měsíc',
    'custom update source – the site follows it whatever channel is chosen' => 'vlastní zdroj aktualizací – web se jím řídí bez ohledu na zvolený kanál',
    'Latest – a new minor version every week' => 'Nejnovější – každý týden nová verze',
    'Kaleta version' => 'Verze Kalety',
    'The markup is %s bytes long; the limit is %s.' => 'Kód má %s bajtů; limit je %s.',
    'The markup is nested %s levels deep; the limit is %s.' => 'Kód je vnořený do %s úrovní; limit je %s.',
    'An element in the markup has %s attributes; the limit is %s.' => 'Prvek v kódu má %s atributů; limit je %s.',
    'The markup has %s elements; the limit is %s.' => 'Kód má %s prvků; limit je %s.',
    'The SVG file was refused: %s' => 'Soubor SVG byl odmítnut: %s',
    'The page was not imported: %s' => 'Stránka nebyla importována: %s',
    'Nothing was saved: %s' => 'Nic nebylo uloženo: %s',
    'The description: %s' => 'Popis: %s',
    'The old page is over a safety limit for HTML (too large or nested too deeply), so only the address was checked.' => 'Stará stránka je přes bezpečnostní limit pro HTML (příliš velká nebo hluboce vnořená), proto se zkontrolovala jen adresa.',
    'Not imported – the HTML is over a safety limit:' => 'Neimportováno – HTML je přes bezpečnostní limit:',
    '“%s” was skipped: %s' => '„%s“ vynecháno: %s',
    'A builder field (%s) was over a safety limit for HTML and was left empty.' => 'Pole builderu (%s) bylo přes bezpečnostní limit pro HTML a zůstalo prázdné.',
    'Collection category “%s”: the description was left empty: %s' => 'Kategorie kolekce „%s“: popis zůstal prázdný: %s',
    'The assistant\'s reply is over a safety limit for HTML. Please try again.' => 'Odpověď asistenta je přes bezpečnostní limit pro HTML. Zkuste to prosím znovu.',
    'The text is over a safety limit for HTML (too large or nested too deeply), so it cannot be translated.' => 'Text je přes bezpečnostní limit pro HTML (příliš velký nebo hluboce vnořený), proto ho nejde přeložit.',
    'Nothing was saved: the text is over a safety limit for HTML (too large or nested too deeply).' => 'Nic nebylo uloženo: text je přes bezpečnostní limit pro HTML (příliš velký nebo hluboce vnořený).',
    'Send through' => 'Odesílat přes',
    'Other server – your host, Google Workspace, Seznam…' => 'Jiný server – váš hosting, Google Workspace, Seznam…',
    'Mail services with an SMTP relay' => 'E-mailové služby s odesíláním přes SMTP',
    'A mail service fills in the server, the port and the encryption. The user name and the password stay yours to paste – the service’s SMTP credentials, not its API key unless the service says so.' => 'E-mailová služba doplní server, port a zabezpečení. Přihlašovací jméno a heslo vložíte sami – jsou to SMTP údaje služby, ne její API klíč, pokud služba sama neříká jinak.',
    'Amazon SES region' => 'Oblast Amazon SES',
    'The region where the sending domain is verified in Amazon SES – the SMTP credentials work only there.' => 'Oblast, ve které je odesílací doména ověřená v Amazon SES – SMTP údaje platí jen tam.',
    'User name' => 'Přihlašovací jméno',
    'Your newsletter integration uses %s too. Its API key is not copied here – the SMTP relay signs in with its own credentials, so paste them below.' => 'Napojení newsletteru používá také %s. Jeho API klíč se sem nekopíruje – SMTP relay se přihlašuje vlastními údaji, vložte je níže.',
    'Newsletter integration' => 'Napojení newsletteru',
    '%s: SMTP guide' => '%s: návod k SMTP',
    'Your newsletter integration uses %s, which also relays e-mail over SMTP – choose %s above to send the site’s mail through the same account.' => 'Napojení newsletteru používá %s, která umí posílat i přes SMTP – zvolte nahoře %s a pošta webu půjde přes stejný účet.',
    'DNS records for %s' => 'DNS záznamy pro %s',
    'The SPF record of %s must include %s – one SPF record per domain, for example:' => 'SPF záznam domény %s musí obsahovat %s – doména má jen jeden SPF záznam, například:',
    'none found on %s' => 'na %s žádný není',
    'found – all is well' => 'nalezen – v pořádku',
    'found, but it does not seem to include %s yet' => 'nalezen, ale zřejmě ještě neobsahuje %s',
    'not found yet' => 'zatím nenalezen',
    'System status checks the sending domain once a day; after adding the records, use Check now there.' => 'Stav systému kontroluje odesílací doménu jednou denně; po přidání záznamů tam použijte Zkontrolovat teď.',
    'The site’s own e-mail goes through %s too (Settings → Mail), signed in with an SMTP key of its own – this API key is not used there.' => 'Vlastní pošta webu jde také přes %s (Nastavení → Pošta) s vlastním SMTP klíčem – tento API klíč se tam nepoužívá.',
    '%s can also send the site’s own e-mail (password resets, enquiries, newsletters) over SMTP – choose it in Settings → Mail and paste an SMTP key there; this API key is not copied.' => '%s umí přes SMTP posílat i vlastní poštu webu (obnovu hesla, poptávky, newslettery) – zvolte ji v Nastavení → Pošta a vložte tam SMTP klíč; tento API klíč se nekopíruje.',
    'Settings → Mail' => 'Nastavení → Pošta',
    '%s needs no include in this record – its DKIM and return-path records authenticate the mail' => '%s v tomto záznamu include nepotřebuje – poštu ověřují její záznamy DKIM a return-path',
    'no DKIM key found under the common selectors. %s: %s' => 'pod běžnými selektory se klíč DKIM nenašel. %s: %s',
    'via %s (SMTP server %s)' => 'přes %s (SMTP server %s)',
    'E-mail: sent through %s (SMTP server %s) – the service processes the recipients’ addresses and the messages.' => 'E-mail: odesílán přes %s (SMTP server %s) – služba zpracovává adresy příjemců a zprávy.',
    '%s – password: %s' => '%s – heslo: %s',
    'The SMTP login shown in Brevo under SMTP & API → SMTP (it ends in @smtp-brevo.com).' => 'SMTP login, který Brevo ukazuje v SMTP & API → SMTP (končí na @smtp-brevo.com).',
    'An SMTP key generated on the same page – not an API key: the Brevo relay refuses API keys.' => 'SMTP klíč vytvořený na stejné stránce – ne API klíč: relay Brevo API klíče odmítá.',
    'In Brevo → Senders, Domains → Domains, authenticate the sending domain: add the brevo-code TXT record and the two DKIM records (brevo1._domainkey and brevo2._domainkey) Brevo shows. With shared sending IPs no SPF include is needed.' => 'V Brevo → Senders, Domains → Domains ověřte odesílací doménu: přidejte TXT záznam brevo-code a dva záznamy DKIM (brevo1._domainkey a brevo2._domainkey), které Brevo ukáže. Při sdílených odesílacích IP adresách není SPF include potřeba.',
    'The SMTP login of your sending domain from Mailgun → Sending → Domain settings → SMTP credentials, for example postmaster@mg.example.com.' => 'SMTP login vaší odesílací domény z Mailgun → Sending → Domain settings → SMTP credentials, například postmaster@mg.example.com.',
    'The password of that SMTP login – not the Mailgun API key.' => 'Heslo tohoto SMTP loginu – ne API klíč Mailgunu.',
    'Mailgun → Sending → Domains → DNS records lists the SPF (include:mailgun.org) and DKIM TXT records for the sending domain – add both.' => 'Mailgun → Sending → Domains → DNS records uvádí pro odesílací doménu TXT záznamy SPF (include:mailgun.org) a DKIM – přidejte oba.',
    'The SMTP user name from Amazon SES → SMTP settings → Create SMTP credentials – not the AWS access key ID.' => 'SMTP uživatelské jméno z Amazon SES → SMTP settings → Create SMTP credentials – ne AWS access key ID.',
    'The SMTP password shown once with it – not the AWS secret access key.' => 'SMTP heslo, které se ukáže jednou spolu s ním – ne AWS secret access key.',
    'Verify the sending domain in Amazon SES with Easy DKIM: add the three CNAME records (…._domainkey) SES shows. include:amazonses.com in SPF is needed only with a custom MAIL FROM domain.' => 'Ověřte odesílací doménu v Amazon SES přes Easy DKIM: přidejte tři záznamy CNAME (…._domainkey), které SES ukáže. include:amazonses.com v SPF je potřeba jen s vlastní doménou MAIL FROM.',
    'The Access Key of an SMTP token (Postmark → your server → the message stream → Settings), or the Server API token. For newsletters use a broadcast stream and the server smtp-broadcasts.postmarkapp.com.' => 'Access Key SMTP tokenu (Postmark → váš server → message stream → Settings), nebo Server API token. Pro newslettery použijte broadcast stream a server smtp-broadcasts.postmarkapp.com.',
    'The Secret Key of that SMTP token – or the same Server API token again, which Postmark accepts as both.' => 'Secret Key toho SMTP tokenu – nebo znovu tentýž Server API token, Postmark ho přijme jako obojí.',
    'Postmark → Sender signatures → DNS settings: add the DKIM TXT record (…pm._domainkey) and the Return-Path CNAME pointing to pm.mtasv.net. Postmark needs no SPF include.' => 'Postmark → Sender signatures → DNS settings: přidejte TXT záznam DKIM (…pm._domainkey) a CNAME Return-Path směřující na pm.mtasv.net. Postmark SPF include nepotřebuje.',
    'Literally apikey – the same for every account.' => 'Doslova apikey – pro každý účet stejně.',
    'A SendGrid API key with the Mail Send permission: SendGrid uses the API key as the SMTP password.' => 'API klíč SendGridu s oprávněním Mail Send: SendGrid používá API klíč jako SMTP heslo.',
    'SendGrid → Settings → Sender authentication → Authenticate your domain: add the CNAME records it shows (em…, s1._domainkey and s2._domainkey); they cover SPF and DKIM.' => 'SendGrid → Settings → Sender authentication → Authenticate your domain: přidejte záznamy CNAME, které ukáže (em…, s1._domainkey a s2._domainkey); pokrývají SPF i DKIM.',
    'The SMTP user MailerSend generates on the domain page (Domains → your domain → SMTP).' => 'SMTP uživatel, kterého MailerSend vygeneruje na stránce domény (Domains → vaše doména → SMTP).',
    'The password of that SMTP user – shown only once; not an API token.' => 'Heslo tohoto SMTP uživatele – ukáže se jen jednou; ne API token.',
    'MailerSend → Domains → your domain: add the SPF (include:_spf.mailersend.net), DKIM and Return-Path records it shows.' => 'MailerSend → Domains → vaše doména: přidejte záznamy SPF (include:_spf.mailersend.net), DKIM a Return-Path, které ukáže.',
    'An SMTP user created in SMTP2GO → Sending → SMTP Users – not your dashboard login. If port 587 is blocked, use 2525.' => 'SMTP uživatel vytvořený v SMTP2GO → Sending → SMTP Users – ne vaše přihlášení do jejich administrace. Když je port 587 blokovaný, použijte 2525.',
    'The password of that SMTP user.' => 'Heslo tohoto SMTP uživatele.',
    'SMTP2GO → Sending → Verified senders: add the sending domain and the CNAME records it shows (return path, DKIM and link tracking); they cover SPF.' => 'SMTP2GO → Sending → Verified senders: přidejte odesílací doménu a záznamy CNAME, které ukáže (return path, DKIM a sledování odkazů); pokrývají i SPF.',
    'Your Mailjet API key (Account settings → SMTP and Send API settings) – Mailjet uses it as the SMTP user name.' => 'Váš API klíč Mailjetu (Account settings → SMTP and Send API settings) – Mailjet ho používá jako SMTP uživatelské jméno.',
    'The secret key belonging to that API key.' => 'Tajný klíč (secret key) patřící k tomuto API klíči.',
    'Mailjet → Account settings → Domains: add include:spf.mailjet.com to the SPF record and the DKIM TXT record (mailjet._domainkey) Mailjet shows.' => 'Mailjet → Account settings → Domains: přidejte include:spf.mailjet.com do SPF záznamu a TXT záznam DKIM (mailjet._domainkey), který Mailjet ukáže.',
    'Any name – Mailchimp does not check it and recommends your account’s primary contact e-mail.' => 'Libovolné jméno – Mailchimp ho nekontroluje a doporučuje hlavní kontaktní e-mail vašeho účtu.',
    'A Mailchimp Transactional (Mandrill) API key from Settings → SMTP & API Info – a Mailchimp marketing API key does not work.' => 'API klíč Mailchimp Transactional (Mandrill) ze Settings → SMTP & API Info – marketingový API klíč Mailchimpu nefunguje.',
    'Mailchimp Transactional → Domains → Sending domains: verify the domain and add the DKIM and SPF records it shows (include:spf.mandrillapp.com).' => 'Mailchimp Transactional → Domains → Sending domains: ověřte doménu a přidejte záznamy DKIM a SPF, které ukáže (include:spf.mandrillapp.com).',
    'Ecomail sends transactional e-mail only through its API, not over SMTP – keep it for the newsletter and choose another service or your mailbox for the site’s mail.' => 'Ecomail posílá transakční e-maily jen přes své API, ne přes SMTP – nechte ho pro newsletter a pro poštu webu zvolte jinou službu nebo svou schránku.',
    'SmartEmailing sends transactional e-mail only through its API, not over SMTP – keep it for the newsletter and choose another service or your mailbox for the site’s mail.' => 'SmartEmailing posílá transakční e-maily jen přes své API, ne přes SMTP – nechte ho pro newsletter a pro poštu webu zvolte jinou službu nebo svou schránku.',
    'MailerLite has no SMTP relay of its own; its transactional service is MailerSend, a separate account with its own SMTP user.' => 'MailerLite vlastní SMTP relay nemá; jeho transakční službou je MailerSend – samostatný účet s vlastním SMTP uživatelem.',
    'The update information file is not signed by the Kaleta publisher (signature v2), so nothing is offered or installed.' => 'Soubor s informací o aktualizaci není podepsaný vydavatelem Kalety (podpis v2), proto se nic nenabízí ani neinstaluje.',
    'Multilingual site (%s): %s.' => 'Vícejazyčný web (%s): %s.',
    'languages in the addresses' => 'jazyky v adresách',
    'no language named' => 'jazyk neuveden',
    'Each post, page and category arrives in its language version and is linked to its original in the default language.' => 'Každý příspěvek, stránka i kategorie přijde do své jazykové verze a propojí se se svým originálem ve výchozím jazyce.',
    'Not imported – this site cannot offer these languages yet: %s.' => 'Nepřeneseno – tyto jazyky web zatím nabídnout neumí: %s.',
    'Translations linked to their original' => 'Překlady propojené s originálem',
    'Language versions added to the site: %s.' => 'Jazykové verze přidané na web: %s.',
    'Addresses another language version already had (%s)' => 'Adresy, které už měla jiná jazyková verze (%s)',
    'These got a number at the end; the old address redirects to the new one. Once each language version can have its own addresses, they can get their original address back.' => 'Dostaly na konec číslo; stará adresa přesměruje na novou. Až bude mít každá jazyková verze vlastní adresy, mohou dostat původní adresu zpět.',
    '%s instead of %s – %s has it' => '%s místo %s – tu má %s',
    'Banner text and policy link in other language versions' => 'Text lišty a odkaz na zásady v dalších jazykových verzích',
    'Visitors of each language version read the banner in its language. An empty field means the same as in the default language.' => 'Návštěvníci každé jazykové verze čtou lištu v jejím jazyce. Prázdné pole znamená totéž co ve výchozím jazyce.',
    'The same address in every language' => 'Stejná adresa ve všech jazycích',
    'A page, a news item or a category may have the same address as one in another language version (/kontakt and /en/kontakt), as on a multilingual WordPress site. System addresses and language codes stay reserved in every language. Switching it off again is possible only while no two language versions share an address.' => 'Stránka, novinka nebo kategorie smí mít stejnou adresu jako jiná v jiné jazykové verzi (/kontakt a /en/kontakt), jako na vícejazyčném webu z WordPressu. Adresy systému a kódy jazyků zůstávají vyhrazené ve všech jazycích. Znovu vypnout to jde, jen dokud žádné dvě jazykové verze nesdílejí adresu.',
    'The same address in every language cannot be switched off while two language versions share an address: %s. Change one of each pair first.' => 'Stejnou adresu ve všech jazycích nejde vypnout, dokud dvě jazykové verze sdílejí adresu: %s. Nejdřív u každé dvojice jednu změňte.',
    'The database is not updated yet (migration 0083) – open the administration once more and try again.' => 'Databáze ještě není aktualizovaná (migrace 0083) – otevřete administraci znovu a zkuste to ještě jednou.',
    'A news item of this category has the same address as a news item in that language version. Change one of them first.' => 'Novinka této kategorie má stejnou adresu jako novinka v té jazykové verzi. Nejdřív jednu z nich změňte.',
    'Two language versions in the export share addresses, so the same address in every language was switched on (Settings → General).' => 'Dvě jazykové verze v exportu sdílejí adresy, proto se zapnula stejná adresa ve všech jazycích (Nastavení → Základní).',
    'Skipped: %d (that language version already has the address).' => 'Přeskočeno: %d (ta jazyková verze už adresu má).',
    'Apps connected to this account (the Claude connector) are disconnected with the new password – connect them again in the Claude app.' => 'Aplikace připojené k tomuto účtu (konektor Claude) se novým heslem odpojí – připojte je znovu v aplikaci Claude.',
